export const BODY = {"level-10":{"id":"level-10","kind":"level","level":10,"src":"level:10","title":"Level 10 · The Stretch","body":"Every strand at its hardest: powers and roots, per cents and compound interest, equations, sequences and inequalities, sets, Pythagoras and trigonometry, and counting and probability, with no stabilisers.","more":"Its lands: Powers, roots and factors · Fractions, ratio and growth · Equations and sequences · Sets and logic · Circles and triangles · Counting and chance · The ladder at full stretch · The board at full stretch · Contest stretch.","where":"Level 10 · age 15 and over","route":"#/journey/10","cta":"See the road"},"land-l10-powers":{"id":"land-l10-powers","kind":"land","level":10,"src":"land:l10-powers","title":"Powers, roots and factors — in The Square Palace","body":"4 stops on this stretch of the road: Squares and brackets · The index laws · Counting factors from the stones · Which square roots are fractions.","art":"art/w-palace.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Square Palace · Level 10","route":"#/world/palace","cta":"Visit Palace"},"land-l10-decimals":{"id":"land-l10-decimals","kind":"land","level":10,"src":"land:l10-decimals","title":"Fractions, ratio and growth — in The Decimal Dock","body":"4 stops on this stretch of the road: Dividing by a fraction · Sales and rises · Ratio: simplify and share · Interest on interest.","art":"art/w-dock.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Decimal Dock · Level 10","route":"#/world/dock","cta":"Visit Dock"},"land-l10-algebra":{"id":"land-l10-algebra","kind":"land","level":10,"src":"land:l10-algebra","title":"Equations and sequences — in Set Island","body":"5 stops on this stretch of the road: Letters for numbers · Solving equations on a balance · The nth term · Straight-line graphs · Inequalities.","art":"art/w-setisland.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"Set Island · Level 10","route":"#/world/setisland","cta":"Visit Set Island"},"land-l10-sets":{"id":"land-l10-sets","kind":"land","level":10,"src":"land:l10-sets","title":"Sets and logic — in Set Island","body":"3 stops on this stretch of the road: Union and intersection · Venn diagrams that count · How many subsets?.","art":"art/w-setisland.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"Set Island · Level 10","route":"#/world/setisland","cta":"Visit Set Island"},"land-l10-shape":{"id":"land-l10-shape","kind":"land","level":10,"src":"land:l10-shape","title":"Circles and triangles — in The Lighthouse","body":"6 stops on this stretch of the road: Round the circle · Pythagoras’ theorem · Tan: how tall is the tower? · Sin and cos: the ladder · The three special angles · Bearings: the way back.","art":"art/w-lighthouse.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Lighthouse · Level 10","route":"#/world/lighthouse","cta":"Visit Lighthouse"},"land-l10-data":{"id":"land-l10-data","kind":"land","level":10,"src":"land:l10-data","title":"Counting and chance — in The Data Carnival","body":"4 stops on this stretch of the road: Permutations: order matters · Combinations: order doesn't matter · Tree diagrams · Expected frequency.","art":"art/w-carnival.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Data Carnival · Level 10","route":"#/world/carnival","cta":"Visit Carnival"},"land-l10-vedic":{"id":"land-l10-vedic","kind":"land","level":10,"src":"land:l10-vedic","title":"The ladder at full stretch — in The Sutra Ladder","body":"6 stops on this stretch of the road: Cube roots by sight · Divisibility by osculators · Square roots by the duplex · Two equations, crosswise · Factorising, proportionately · Pick the sutra.","art":"art/w-ladder.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Sutra Ladder · Level 10","route":"#/world/ladder","cta":"Visit Ladder"},"land-l10-chinese":{"id":"land-l10-chinese","kind":"land","level":10,"src":"land:l10-chinese","title":"The board at full stretch — in The Counting Court","body":"4 stops on this stretch of the road: Remainders by multipliers · The sea island survey · Liu Hui's polygons · The hundred fowls.","art":"art/w-court.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Counting Court · Level 10","route":"#/world/court","cta":"Visit Court"},"land-l10-contest":{"id":"land-l10-contest","kind":"land","level":10,"src":"land:l10-contest","title":"Contest stretch — in The Strategy School","body":"5 stops on this stretch of the road: Pretend they are all the same · The gap never changes · Try a smaller one first · Closing the gap · Ride the cycle.","art":"art/w-strategy.webp","more":"At its end, a 20-question test: 12 right passes, and 5 bonus questions count double.","where":"The Strategy School · Level 10","route":"#/world/strategy","cta":"Visit Strategy"},"hook-divide-fractions-hook":{"id":"hook-divide-fractions-hook","kind":"hook","src":"stop:divide-fractions#hook","title":"Can you? — Dividing by a fraction","body":"3 ÷ 1/2 — how many halves fit in 3?","more":"The way in: Keep the first, change ÷ to ×, flip the second.","cta":"Find out how","where":"The Fraction Bakery · Level 10","level":10,"route":"#/stop/divide-fractions|learn"},"worked-divide-fractions-worked0":{"id":"worked-divide-fractions-worked0","kind":"worked","src":"stop:divide-fractions#worked0","title":"Worked out — Dividing by a fraction: Whole ÷ a unit fraction","body":"3 ÷ 1/2: How many 1/2s fit in one whole? → 2 · In 3 wholes: 3 × 2 → 6","more":"What is special here: How many halves fit in 3? Each whole holds 2, so multiply the wholes by the bottom number.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 10","level":10,"route":"#/stop/divide-fractions|learn|0"},"worked-divide-fractions-worked1":{"id":"worked-divide-fractions-worked1","kind":"worked","src":"stop:divide-fractions#worked1","title":"Worked out — Dividing by a fraction: Whole ÷ a bigger fraction","body":"6 ÷ 2/3: Pieces: 6 × 3 → 18 · Helpings of 2 pieces: ÷ 2 → 9","more":"What is special here: Count the pieces first, then group them into helpings the size of the top number: multiply, then divide.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 10","level":10,"route":"#/stop/divide-fractions|learn|1"},"worked-divide-fractions-worked2":{"id":"worked-divide-fractions-worked2","kind":"worked","src":"stop:divide-fractions#worked2","title":"Worked out — Dividing by a fraction: Fraction ÷ fraction","body":"2/3 ÷ 3/4: Keep 2/3, change ÷ to ×, flip 3/4 → 4/3 · Tops: 2 × 4 → 8 · Bottoms: 3 × 3 → 9 · Top over bottom → 8/9","more":"What is special here: Now both are fractions. Keep the first, change ÷ to ×, flip the second, and multiply straight across.","cta":"Watch it step by step","where":"The Fraction Bakery · Level 10","level":10,"route":"#/stop/divide-fractions|learn|2"},"why-divide-fractions-why2":{"id":"why-divide-fractions-why2","kind":"why","src":"stop:divide-fractions#why2","title":"Why “Dividing by a fraction” works","body":"That is all \"keep, change, flip\" is: the bottom of the divisor tells you how many pieces each whole breaks into, and the top tells you how many pieces make one helping.","more":"The trick: Keep the first, change ÷ to ×, flip the second.","cta":"See why","where":"The Fraction Bakery · Level 10","level":10,"route":"#/stop/divide-fractions|learn"},"moral-divide-fractions-beat5":{"id":"moral-divide-fractions-beat5","kind":"moral","src":"story:divide-fractions#beat5","badge":{"id":"story","label":"A story"},"title":"Vesper, in “How many helpings?”","body":"Times by 3, divide by 2. Flip it and multiply.","more":"The trick in the story: Keep the first, change ÷ to ×, flip the second.","cta":"Read the story","where":"The Fraction Bakery · Level 10","level":10,"route":"#/stop/divide-fractions|story|5"},"algebra-divide-fractions-alg":{"id":"algebra-divide-fractions-alg","kind":"algebra","src":"stop:divide-fractions#alg","title":"The algebra behind “Dividing by a fraction”","body":"a/b ÷ c/d = a/b × d/c","more":"In words: Keep the first, change ÷ to ×, flip the second.","cta":"See why","where":"The Fraction Bakery · Level 10","level":10,"route":"#/stop/divide-fractions|learn"},"try-divide-fractions-L10":{"id":"try-divide-fractions-L10","kind":"try","level":10,"src":"try:divide-fractions@10/3#0","title":"Dividing by a fraction — your turn","where":"The Fraction Bakery · Level 10","route":"#/stop/divide-fractions|drill","cta":"Practise this stop","play":{"q":"1/2 ÷ 1/2 = ?","opts":["2/2","2/1","3/2"],"after":"Keep the first, change ÷ to ×, flip the second.","show":[0,2,1]}},"hook-interest-compound-hook":{"id":"hook-interest-compound-hook","kind":"hook","src":"stop:interest-compound#hook","title":"Can you? — Interest on interest","body":"200 coins in the story's bank at 5% a year, and each year's interest stays in. How much after 2 years?","more":"The way in: Each year, add the interest to the account — so next year the interest is worked out on the bigger amount.","cta":"Find out how","where":"Coin Street · Level 10","level":10,"route":"#/stop/interest-compound|learn"},"worked-interest-compound-worked0":{"id":"worked-interest-compound-worked0","kind":"worked","src":"stop:interest-compound#worked0","title":"Worked out — Interest on interest: The account, year by year","body":"The story's bank pays 5% a year and each year's interest stays in the account (compound). Ines puts in 200 coins. How many coins after 2 years?: After year 1: add 5% of 200 → 210 · After year 2: add 5% of 210 → 220.5","more":"What is special here: Each year's interest is worked out on the bigger amount, so go one year at a time — never multiply one year's interest by the years.","cta":"Watch it step by step","where":"Coin Street · Level 10","level":10,"route":"#/stop/interest-compound|learn|0"},"worked-interest-compound-worked1":{"id":"worked-interest-compound-worked1","kind":"worked","src":"stop:interest-compound#worked1","title":"Worked out — Interest on interest: Compound beats simple by…","body":"The story's bank pays 10% a year. Suki leaves 200 coins for 2 years with the interest kept in (compound). How many coins more is that than simple interest would give?: Compound: 200 → year 1 → year 2 → 242 · Simple: 200 + 2 × 10% of 200 → 240 · The difference: interest on interest → 2","more":"What is special here: Work out both accounts after two years and take one from the other. The gap is the interest earned on interest.","cta":"Watch it step by step","where":"Coin Street · Level 10","level":10,"route":"#/stop/interest-compound|learn|1"},"why-interest-compound-why2":{"id":"why-interest-compound-why2","kind":"why","src":"stop:interest-compound#why2","title":"Why “Interest on interest” works","body":"The numbers here always come out to whole hundredths of a coin, so nothing needs rounding. A quick way to do one year: multiply by 1.05 for 5%, 1.1 for 10% — the 1 keeps the coins you had, the rest adds the interest. The rates are the story's, not a real bank's.","more":"The trick: Each year, add the interest to the account — so next year the interest is worked out on the bigger amount.","cta":"See why","where":"Coin Street · Level 10","level":10,"route":"#/stop/interest-compound|learn"},"moral-interest-compound-beat5":{"id":"moral-interest-compound-beat5","kind":"moral","src":"story:interest-compound#beat5","badge":{"id":"story","label":"A story"},"title":"Kwame, in “Leave it in”","body":"220.50 coins. The gap grows every year it stays in.","more":"The trick in the story: Each year, add the interest to the account — so next year the interest is worked out on the bigger amount.","cta":"Read the story","where":"Coin Street · Level 10","level":10,"route":"#/stop/interest-compound|story|5"},"algebra-interest-compound-alg":{"id":"algebra-interest-compound-alg","kind":"algebra","src":"stop:interest-compound#alg","title":"The algebra behind “Interest on interest”","body":"A = P × (1 + r/100)ⁿ;  after 2 years, compound − simple = P × (r/100)²","more":"In words: Each year, add the interest to the account — so next year the interest is worked out on the bigger amount.","cta":"See why","where":"Coin Street · Level 10","level":10,"route":"#/stop/interest-compound|learn"},"try-interest-compound-L10":{"id":"try-interest-compound-L10","kind":"try","level":10,"src":"try:interest-compound@10/3#0","title":"Interest on interest — your turn","where":"Coin Street · Level 10","route":"#/stop/interest-compound|drill","cta":"Practise this stop","play":{"q":"The story's bank pays 6% a year. Theo leaves 600 coins for 2 years with the interest kept in (compound). How many coins more is that than simple interest would give?","opts":["2.16","1.16","3.16"],"after":"Each year, add the interest to the account — so next year the interest is worked out on the bigger amount.","show":[2,1,0]}},"hook-round-the-circle-hook":{"id":"hook-round-the-circle-hook","kind":"hook","src":"stop:round-the-circle#hook","title":"Can you? — Round the circle","body":"A bicycle wheel is 60 cm across. How far does it roll in one turn?","more":"The way in: The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.","cta":"Find out how","where":"Shape City · Level 10","level":10,"route":"#/stop/round-the-circle|learn"},"worked-round-the-circle-worked0":{"id":"worked-round-the-circle-worked0","kind":"worked","src":"stop:round-the-circle#worked0","title":"Worked out — Round the circle: Radius to diameter","body":"A circle has a radius of 6 cm. What is its diameter, in cm?: The radius → 6 · Two radii end to end → 12","more":"What is special here: The diameter goes right across through the centre: one radius out and one radius back, so double it.","cta":"Watch it step by step","where":"Shape City · Level 10","level":10,"route":"#/stop/round-the-circle|learn|0"},"worked-round-the-circle-worked1":{"id":"worked-round-the-circle-worked1","kind":"worked","src":"stop:round-the-circle#worked1","title":"Worked out — Round the circle: Diameter to radius","body":"A circle has a diameter of 14 cm. What is its radius, in cm?: The diameter → 14 · Half of it → 7","more":"What is special here: Going the other way, the radius is only halfway across — so halve the diameter.","cta":"Watch it step by step","where":"Shape City · Level 10","level":10,"route":"#/stop/round-the-circle|learn|1"},"worked-round-the-circle-worked2":{"id":"worked-round-the-circle-worked2","kind":"worked","src":"stop:round-the-circle#worked2","title":"Worked out — Round the circle: Round, from the diameter","body":"A circle has a diameter of 12 cm. Using π ≈ 3.14, how far is it round the edge, in cm?: 3 × 12 → 36 · 0.14 × 12 → 1.68 · Add them → 37.68","more":"What is special here: The distance round is a little more than 3 diameters: 3.14 × the diameter. Do the 3 × first, then add the small 0.14 ×.","cta":"Watch it step by step","where":"Shape City · Level 10","level":10,"route":"#/stop/round-the-circle|learn|2"},"worked-round-the-circle-worked3":{"id":"worked-round-the-circle-worked3","kind":"worked","src":"stop:round-the-circle#worked3","title":"Worked out — Round the circle: Round, from the radius","body":"A circle has a radius of 5 cm. Using π ≈ 3.14, how far is it round the edge, in cm?: The diameter: 2 × 5 → 10 · 3 × 10 → 30 · 0.14 × 10 → 1.4 · Add them → 31.4","more":"What is special here: π works with the diameter, so double the radius FIRST. Multiplying the radius by 3.14 gives only half the way round.","cta":"Watch it step by step","where":"Shape City · Level 10","level":10,"route":"#/stop/round-the-circle|learn|3"},"why-round-the-circle-why2":{"id":"why-round-the-circle-why2","kind":"why","src":"stop:round-the-circle#why2","title":"Why “Round the circle” works","body":"You can see why it is a bit more than 3. Fit a hexagon inside the circle: its six sides are each one radius long, so its perimeter is 6 radii — exactly 3 diameters. The circle bulges outside the hexagon, so it must be a little longer than 3 diameters. A square drawn around the outside is 4 diameters, so π sits between 3 and 4.","more":"The trick: The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.","cta":"See why","where":"Shape City · Level 10","level":10,"route":"#/stop/round-the-circle|learn"},"moral-round-the-circle-beat5":{"id":"moral-round-the-circle-beat5","kind":"moral","src":"story:round-the-circle#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The rolling wheel”","body":"188.4 cm every turn — nearly two metres!","more":"The trick in the story: The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.","cta":"Read the story","where":"Shape City · Level 10","level":10,"route":"#/stop/round-the-circle|story|5"},"algebra-round-the-circle-alg":{"id":"algebra-round-the-circle-alg","kind":"algebra","src":"stop:round-the-circle#alg","title":"The algebra behind “Round the circle”","body":"d = 2r · C = π × d ≈ 3.14 × d","more":"In words: The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.","cta":"See why","where":"Shape City · Level 10","level":10,"route":"#/stop/round-the-circle|learn"},"try-round-the-circle-L10":{"id":"try-round-the-circle-L10","kind":"try","level":10,"src":"try:round-the-circle@10/3#0","title":"Round the circle — your turn","where":"Shape City · Level 10","route":"#/stop/round-the-circle|drill","cta":"Practise this stop","play":{"q":"A circle has a radius of 12 cm. Using π ≈ 3.14, how far is it round the edge, in cm?","opts":["75.36","24","753.6"],"after":"The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter.","show":[0,2,1]}},"hook-negative-squares-hook":{"id":"hook-negative-squares-hook","kind":"hook","src":"stop:negative-squares#hook","title":"Can you? — Squares and brackets","body":"(−3)² and −3². Are they the same number?","more":"The way in: Powers come before the minus sign in front — unless brackets put the minus inside the square.","cta":"Find out how","where":"The Deep Mine · Level 10","level":10,"route":"#/stop/negative-squares|learn"},"worked-negative-squares-worked0":{"id":"worked-negative-squares-worked0","kind":"worked","src":"stop:negative-squares#worked0","title":"Worked out — Squares and brackets: Square in brackets","body":"(−3)²: (−3)² is (−3) × (−3). The sizes: 3 × 3 → 9 · Two negatives multiplied make a positive, so → 9","more":"What is special here: The bracket puts the minus inside the square, so it is multiplied by itself too — and two negatives make a positive.","cta":"Watch it step by step","where":"The Deep Mine · Level 10","level":10,"route":"#/stop/negative-squares|learn|0"},"worked-negative-squares-worked1":{"id":"worked-negative-squares-worked1","kind":"worked","src":"stop:negative-squares#worked1","title":"Worked out — Squares and brackets: Minus, no brackets","body":"−3²: No brackets, so the power goes first: 3² → 9 · Then the minus in front → -9","more":"What is special here: No brackets, so the power goes first and the minus waits: square the number, then make it negative.","cta":"Watch it step by step","where":"The Deep Mine · Level 10","level":10,"route":"#/stop/negative-squares|learn|1"},"worked-negative-squares-worked2":{"id":"worked-negative-squares-worked2","kind":"worked","src":"stop:negative-squares#worked2","title":"Worked out — Squares and brackets: Square, then take away","body":"(−4)² − 5: Powers first: (−4)² → 16 · 16 − 5 → 11","more":"What is special here: Powers come before take-away: square the bracket first, then subtract.","cta":"Watch it step by step","where":"The Deep Mine · Level 10","level":10,"route":"#/stop/negative-squares|learn|2"},"worked-negative-squares-worked3":{"id":"worked-negative-squares-worked3","kind":"worked","src":"stop:negative-squares#worked3","title":"Worked out — Squares and brackets: Times a negative","body":"10 − 4 × (−3): Multiply first: 4 × (−3) → -12 · 10 − (−12) is 10 + 12 → 22","more":"What is special here: Multiply before you take away. Then taking away a negative is the same as adding.","cta":"Watch it step by step","where":"The Deep Mine · Level 10","level":10,"route":"#/stop/negative-squares|learn|3"},"worked-negative-squares-worked4":{"id":"worked-negative-squares-worked4","kind":"worked","src":"stop:negative-squares#worked4","title":"Worked out — Squares and brackets: Minus square plus a product","body":"−3² + 4 × 5: Powers first: −3² (square, then the minus) → -9 · Then multiply: 4 × 5 → 20 · −9 + 20 → 11","more":"What is special here: Two jobs before the add: the power (square, then the minus) and the multiplication. Only then add.","cta":"Watch it step by step","where":"The Deep Mine · Level 10","level":10,"route":"#/stop/negative-squares|learn|4"},"why-negative-squares-why2":{"id":"why-negative-squares-why2","kind":"why","src":"stop:negative-squares#why2","title":"Why “Squares and brackets” works","body":"The same order runs whole sums: powers, then × and ÷, then + and −. In 10 − 4 × (−3), multiply first: 4 × (−3) = −12. Then 10 − (−12) is 10 + 12 = 22. Take each step on its own and the signs look after themselves.","more":"The trick: Powers come before the minus sign in front — unless brackets put the minus inside the square.","cta":"See why","where":"The Deep Mine · Level 10","level":10,"route":"#/stop/negative-squares|learn"},"moral-negative-squares-beat5":{"id":"moral-negative-squares-beat5","kind":"moral","src":"story:negative-squares#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “The calculator argument”","body":"So the calculator is right. −3² is −9, and (−3)² is 9. The brackets decide.","more":"The trick in the story: Powers come before the minus sign in front — unless brackets put the minus inside the square.","cta":"Read the story","where":"The Deep Mine · Level 10","level":10,"route":"#/stop/negative-squares|story|5"},"algebra-negative-squares-alg":{"id":"algebra-negative-squares-alg","kind":"algebra","src":"stop:negative-squares#alg","title":"The algebra behind “Squares and brackets”","body":"(−a)² = a² ; −a² = −(a²) ; c − d × (−e) = c + de","more":"In words: Powers come before the minus sign in front — unless brackets put the minus inside the square.","cta":"See why","where":"The Deep Mine · Level 10","level":10,"route":"#/stop/negative-squares|learn"},"try-negative-squares-L10":{"id":"try-negative-squares-L10","kind":"try","level":10,"src":"try:negative-squares@10/3#0","title":"Squares and brackets — your turn","where":"The Deep Mine · Level 10","route":"#/stop/negative-squares|drill","cta":"Practise this stop","play":{"q":"−3² + 4 × 29 = ?","opts":["107","116","170"],"after":"Powers come before the minus sign in front — unless brackets put the minus inside the square.","show":[2,1,0]}},"hook-factor-count-stones-hook":{"id":"hook-factor-count-stones-hook","kind":"hook","src":"stop:factor-count-stones#hook","title":"Can you? — Counting factors from the stones","body":"2³ × 3² — how many factors does it have, without listing a single one?","more":"The way in: For each prime, count how many of it a factor could take — none, one, two… up to all of them. Multiply those counts.","cta":"Find out how","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/factor-count-stones|learn"},"worked-factor-count-stones-worked0":{"id":"worked-factor-count-stones-worked0","kind":"worked","src":"stop:factor-count-stones#worked0","title":"Worked out — Counting factors from the stones: Every stone has a power","body":"2³ × 3² — how many factors?: How many 2s can a factor take? (none, one, … up to 3) → 4 · How many 3s can a factor take? (none, one, … up to 2) → 3 · Multiply the choices: 4 × 3 → 12","more":"What is special here: Three 2s give 4 choices (none, one, two, three) and two 3s give 3 choices. Every pairing is a different factor.","cta":"Watch it step by step","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/factor-count-stones|learn|0"},"worked-factor-count-stones-worked1":{"id":"worked-factor-count-stones-worked1","kind":"worked","src":"stop:factor-count-stones#worked1","title":"Worked out — Counting factors from the stones: A stone on its own","body":"2² × 5 — how many factors?: How many 2s can a factor take? (none, one, … up to 2) → 3 · How many 5s can a factor take? (none, one, … up to 1) → 2 · Multiply the choices: 3 × 2 → 6","more":"What is special here: A stone with no little number is there ONCE: a factor can take none of it or one. That is 2 choices, not 1.","cta":"Watch it step by step","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/factor-count-stones|learn|1"},"why-factor-count-stones-why2":{"id":"why-factor-count-stones-why2","kind":"why","src":"stop:factor-count-stones#why2","title":"Why “Counting factors from the stones” works","body":"So the rule is: add one to each little power, and multiply. The \"add one\" is the choice of taking none of that stone — the factor 1 comes from taking none of anything. A stone written with no little number is there once, so it still gives two choices: none of it, or one.","more":"The trick: For each prime, count how many of it a factor could take — none, one, two… up to all of them. Multiply those counts.","cta":"See why","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/factor-count-stones|learn"},"moral-factor-count-stones-beat5":{"id":"moral-factor-count-stones-beat5","kind":"moral","src":"story:factor-count-stones#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “Bags of biscuits”","body":"Each pair of choices builds a different size. Twelve bag sizes.","more":"The trick in the story: For each prime, count how many of it a factor could take — none, one, two… up to all of them. Multiply those counts.","cta":"Read the story","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/factor-count-stones|story|5"},"algebra-factor-count-stones-alg":{"id":"algebra-factor-count-stones-alg","kind":"algebra","src":"stop:factor-count-stones#alg","title":"The algebra behind “Counting factors from the stones”","body":"n = p^a × q^b × r^c ⇒ number of factors = (a + 1)(b + 1)(c + 1)","more":"In words: For each prime, count how many of it a factor could take — none, one, two… up to all of them. Multiply those counts.","cta":"See why","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/factor-count-stones|learn"},"hook-rational-roots-hook":{"id":"hook-rational-roots-hook","kind":"hook","src":"stop:rational-roots#hook","title":"Can you? — Which square roots are fractions","body":"√49 is 7. Is √50 some fraction — one whole number over another?","more":"The way in: Write the number in prime stones. If every stone has a partner, the root is a whole number (or a fraction). If any stone is left alone, the root is irrational: no fraction is exactly it.","cta":"Find out how","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/rational-roots|learn"},"worked-rational-roots-worked0":{"id":"worked-rational-roots-worked0","kind":"worked","src":"stop:rational-roots#worked0","title":"Worked out — Which square roots are fractions: A lonely stone","body":"√50 — rational or irrational?: Write 50 in prime stones. How many different stones are left without a partner? → 1 · A lonely stone, so the root is → irrational","more":"What is special here: 50 = 2 × 5 × 5. The 5s pair up but the 2 is alone, so no fraction squared can ever make 50: √50 is irrational.","cta":"Watch it step by step","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/rational-roots|learn|0"},"worked-rational-roots-worked1":{"id":"worked-rational-roots-worked1","kind":"worked","src":"stop:rational-roots#worked1","title":"Worked out — Which square roots are fractions: Every stone paired","body":"√36 — rational or irrational?: Write 36 in prime stones. How many different stones are left without a partner? → 0 · Every stone has a partner, so the root is → rational","more":"What is special here: 36 = 2 × 2 × 3 × 3: every stone has a partner, so 36 is a square and √36 = 6 — rational.","cta":"Watch it step by step","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/rational-roots|learn|1"},"worked-rational-roots-worked2":{"id":"worked-rational-roots-worked2","kind":"worked","src":"stop:rational-roots#worked2","title":"Worked out — Which square roots are fractions: A fraction, all paired","body":"√(4/9) — rational or irrational?: How many different stones of 4 are left without a partner? → 0 · And of 9? → 0 · Every stone paired, top and bottom, so it is → rational","more":"What is special here: For a fraction in lowest terms, check the top AND the bottom. 4 and 9 are both squares, so √(4/9) = 2/3 — rational.","cta":"Watch it step by step","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/rational-roots|learn|2"},"worked-rational-roots-worked3":{"id":"worked-rational-roots-worked3","kind":"worked","src":"stop:rational-roots#worked3","title":"Worked out — Which square roots are fractions: A fraction, one lonely","body":"√(8/9) — rational or irrational?: How many different stones of 8 are left without a partner? → 1 · And of 9? → 0 · A lonely stone somewhere, so √ of this fraction is → irrational","more":"What is special here: The bottom 9 is a square, but the top 8 = 2 × 2 × 2 leaves a 2 alone. One lonely stone anywhere makes it irrational.","cta":"Watch it step by step","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/rational-roots|learn|3"},"why-rational-roots-why2":{"id":"why-rational-roots-why2","kind":"why","src":"stop:rational-roots#why2","title":"Why “Which square roots are fractions” works","body":"It is still a real length — the diagonal of a square with sides 5 — and 99/14 gets very close: 99 × 99 = 9801, while 50 × 14 × 14 = 9800. Close is not equal. The same argument works for fractions: in lowest terms, √(p/q) is rational only when p and q are both squares.","more":"The trick: Write the number in prime stones. If every stone has a partner, the root is a whole number (or a fraction). If any stone is left alone, the root is irrational: no fraction is exactly it.","cta":"See why","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/rational-roots|learn"},"moral-rational-roots-beat6":{"id":"moral-rational-roots-beat6","kind":"moral","src":"story:rational-roots#beat6","badge":{"id":"story","label":"A story"},"title":"Vesper, in “The lonely stone”","body":"So √50 is irrational. A real length — but no fraction is exactly it.","more":"The trick in the story: Write the number in prime stones. If every stone has a partner, the root is a whole number (or a fraction). If any stone is left alone, the root is irrational: no fraction is exactly it.","cta":"Read the story","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/rational-roots|story|6"},"algebra-rational-roots-alg":{"id":"algebra-rational-roots-alg","kind":"algebra","src":"stop:rational-roots#alg","title":"The algebra behind “Which square roots are fractions”","body":"√n is rational ⇔ n is a perfect square ⇔ every prime stone of n appears an even number of times","more":"In words: Write the number in prime stones. If every stone has a partner, the root is a whole number (or a fraction). If any stone is left alone, the root is irrational: no fraction is exactly it.","cta":"See why","where":"The Prime Quarry · Level 10","level":10,"route":"#/stop/rational-roots|learn"},"try-rational-roots-L10":{"id":"try-rational-roots-L10","kind":"try","level":10,"src":"try:rational-roots@10/3#0","title":"Which square roots are fractions — your turn","where":"The Prime Quarry · Level 10","route":"#/stop/rational-roots|drill","cta":"Practise this stop","play":{"q":"√400 — rational or irrational?","opts":["rational","irrational"],"after":"Write the number in prime stones. If every stone has a partner, the root is a whole number (or a fraction). If any stone is left alone, the root is irrational: no fraction is exactly it.","show":[1,0]}},"hook-index-laws-hook":{"id":"hook-index-laws-hook","kind":"hook","src":"stop:index-laws#hook","title":"Can you? — The index laws","body":"2³ × 2⁴ as one power of 2 — without working either out.","more":"The way in: Multiplying powers of the same number adds the indices; dividing subtracts them.","cta":"Find out how","where":"The Square Palace · Level 10","level":10,"route":"#/stop/index-laws|learn"},"worked-index-laws-worked0":{"id":"worked-index-laws-worked0","kind":"worked","src":"stop:index-laws#worked0","title":"Worked out — The index laws: Multiplying: add","body":"2³ × 2⁴ as one power of 2 — the index?: How many 2s in 2³? → 3 · And in 2⁴? → 4 · 3 + 4 → 7","more":"What is special here: Put the two lots side by side and count all the 2s together — so the indices add.","cta":"Watch it step by step","where":"The Square Palace · Level 10","level":10,"route":"#/stop/index-laws|learn|0"},"worked-index-laws-worked1":{"id":"worked-index-laws-worked1","kind":"worked","src":"stop:index-laws#worked1","title":"Worked out — The index laws: Dividing: take away","body":"5⁶ ÷ 5² as one power of 5 — the index?: 5s on top → 6 · 5s underneath, to cancel → 2 · 6 − 2 → 4","more":"What is special here: Each one underneath cancels one on top, so the indices take away.","cta":"Watch it step by step","where":"The Square Palace · Level 10","level":10,"route":"#/stop/index-laws|learn|1"},"worked-index-laws-worked2":{"id":"worked-index-laws-worked2","kind":"worked","src":"stop:index-laws#worked2","title":"Worked out — The index laws: Standard form","body":"34,000 = 3.4 × 10 to the power ? — the index?: How many digits in 34,000? → 5 · The point moves one fewer places → 4","more":"What is special here: One digit before the point, and the power of ten is how many places the point has to move — one fewer than the digits.","cta":"Watch it step by step","where":"The Square Palace · Level 10","level":10,"route":"#/stop/index-laws|learn|2"},"worked-index-laws-worked3":{"id":"worked-index-laws-worked3","kind":"worked","src":"stop:index-laws#worked3","title":"Worked out — The index laws: Multiplying in standard form","body":"(3 × 10⁴) × (2 × 10³) = 6 × 10 to the power ? — the index?: 3 × 2 → 6 · 4 + 3 → 7 · 6 is under 10 — the index stays → 7","more":"What is special here: Multiply the front numbers, add the powers of ten.","cta":"Watch it step by step","where":"The Square Palace · Level 10","level":10,"route":"#/stop/index-laws|learn|3"},"worked-index-laws-worked4":{"id":"worked-index-laws-worked4","kind":"worked","src":"stop:index-laws#worked4","title":"Worked out — The index laws: When the front goes past 10","body":"(4 × 10²) × (5 × 10³) = 2 × 10 to the power ? — the index?: 4 × 5 → 20 · 2 + 3 → 5 · 20 is 2 × 10 — one more power → 6","more":"What is special here: If the front numbers make 10 or more, one ten slides into the power, so the index goes up by one more.","cta":"Watch it step by step","where":"The Square Palace · Level 10","level":10,"route":"#/stop/index-laws|learn|4"},"why-index-laws-why2":{"id":"why-index-laws-why2","kind":"why","src":"stop:index-laws#why2","title":"Why “The index laws” works","body":"This is exactly how scientists write huge numbers. 34,000 is 3.4 × 10,000 = 3.4 × 10⁴ — \"standard form\", one digit before the point and a power of ten. Multiply two of them and the indices add: (3 × 10⁴) × (2 × 10³) = 6 × 10⁷. If the front numbers make 10 or more, one more ten moves into the power: (4 × 10²) × (5 × 10³) = 20 × 10⁵ = 2 × 10⁶.","more":"The trick: Multiplying powers of the same number adds the indices; dividing subtracts them.","cta":"See why","where":"The Square Palace · Level 10","level":10,"route":"#/stop/index-laws|learn"},"moral-index-laws-beat5":{"id":"moral-index-laws-beat5","kind":"moral","src":"story:index-laws#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “Stars over the palace”","body":"Sixty million stars — and I never wrote a single long row of zeros.","more":"The trick in the story: Multiplying powers of the same number adds the indices; dividing subtracts them.","cta":"Read the story","where":"The Square Palace · Level 10","level":10,"route":"#/stop/index-laws|story|5"},"algebra-index-laws-alg":{"id":"algebra-index-laws-alg","kind":"algebra","src":"stop:index-laws#alg","title":"The algebra behind “The index laws”","body":"aᵐ × aⁿ = aᵐ⁺ⁿ   ·   aᵐ ÷ aⁿ = aᵐ⁻ⁿ   ·   standard form: A × 10ⁿ, 1 ≤ A < 10","more":"In words: Multiplying powers of the same number adds the indices; dividing subtracts them.","cta":"See why","where":"The Square Palace · Level 10","level":10,"route":"#/stop/index-laws|learn"},"try-index-laws-L10":{"id":"try-index-laws-L10","kind":"try","level":10,"src":"try:index-laws@10/3#0","title":"The index laws — your turn","where":"The Square Palace · Level 10","route":"#/stop/index-laws|drill","cta":"Practise this stop","play":{"q":"4,100 = 4.1 × 10 to the power ? — the index?","opts":["3","4","5"],"after":"Multiplying powers of the same number adds the indices; dividing subtracts them.","show":[2,0,1]}},"hook-percent-change-hook":{"id":"hook-percent-change-hook","kind":"hook","src":"stop:percent-change#hook","title":"Can you? — Sales and rises","body":"A 60-coin jacket has 20% off. What do you pay?","more":"The way in: Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).","cta":"Find out how","where":"The Decimal Dock · Level 10","level":10,"route":"#/stop/percent-change|learn"},"worked-percent-change-worked0":{"id":"worked-percent-change-worked0","kind":"worked","src":"stop:percent-change#worked0","title":"Worked out — Sales and rises: Money off","body":"60 with 20% off: 20% of 60 → 12 · Take it off → 48","more":"What is special here: Find the percentage of the price, then take it away.","cta":"Watch it step by step","where":"The Decimal Dock · Level 10","level":10,"route":"#/stop/percent-change|learn|0"},"worked-percent-change-worked1":{"id":"worked-percent-change-worked1","kind":"worked","src":"stop:percent-change#worked1","title":"Worked out — Sales and rises: Money added","body":"80 with 15% added: 15% of 80 → 12 · Add it on → 92","more":"What is special here: The same two steps upwards: find the percentage, then add it on.","cta":"Watch it step by step","where":"The Decimal Dock · Level 10","level":10,"route":"#/stop/percent-change|learn|1"},"worked-percent-change-worked2":{"id":"worked-percent-change-worked2","kind":"worked","src":"stop:percent-change#worked2","title":"Worked out — Sales and rises: Off, in one step","body":"120 with 35% off: Per cent you pay: 100 − 35 → 65 · 65% of 120 → 78","more":"What is special here: Think about what you DO pay: 35% off leaves 65%, so find 65% of the price straight away.","cta":"Watch it step by step","where":"The Decimal Dock · Level 10","level":10,"route":"#/stop/percent-change|learn|2"},"worked-percent-change-worked3":{"id":"worked-percent-change-worked3","kind":"worked","src":"stop:percent-change#worked3","title":"Worked out — Sales and rises: Added, in one step","body":"200 with 15% added: New per cent: 100 + 15 → 115 · 115% of 200 → 230","more":"What is special here: A rise of 15% makes 115% of the old amount — find that directly.","cta":"Watch it step by step","where":"The Decimal Dock · Level 10","level":10,"route":"#/stop/percent-change|learn|3"},"why-percent-change-why2":{"id":"why-percent-change-why2","kind":"why","src":"stop:percent-change#why2","title":"Why “Sales and rises” works","body":"Increases work the same way upwards: 15% more than 80 is 115% of 80, which is 92. Shops, wages and prices all move by per cents, and this is how to see where they land.","more":"The trick: Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).","cta":"See why","where":"The Decimal Dock · Level 10","level":10,"route":"#/stop/percent-change|learn"},"moral-percent-change-beat5":{"id":"moral-percent-change-beat5","kind":"moral","src":"story:percent-change#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The jacket sale”","body":"48 coins, both ways.","more":"The trick in the story: Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).","cta":"Read the story","where":"The Decimal Dock · Level 10","level":10,"route":"#/stop/percent-change|story|5"},"algebra-percent-change-alg":{"id":"algebra-percent-change-alg","kind":"algebra","src":"stop:percent-change#alg","title":"The algebra behind “Sales and rises”","body":"n with p% off = n × (100 − p)/100; n with p% added = n × (100 + p)/100","more":"In words: Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).","cta":"See why","where":"The Decimal Dock · Level 10","level":10,"route":"#/stop/percent-change|learn"},"try-percent-change-L10":{"id":"try-percent-change-L10","kind":"try","level":10,"src":"try:percent-change@10/3#0","title":"Sales and rises — your turn","where":"The Decimal Dock · Level 10","route":"#/stop/percent-change|drill","cta":"Practise this stop","play":{"q":"360 with 40% added = ?","opts":["504","140","404"],"after":"Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price).","show":[0,2,1]}},"idea-ratio-share-case0":{"id":"idea-ratio-share-case0","kind":"idea","src":"stop:ratio-share#case0","title":"Ratio: simplify and share: Share in a ratio","body":"Add the parts to get one round of sharing. Find one part, then multiply by the share you want.","more":"The method: Add the parts to find how many equal shares there are. Find one share, then multiply.","cta":"See it worked","where":"The Decimal Dock · Level 10","level":10,"route":"#/stop/ratio-share|learn|0"},"worked-ratio-share-worked1":{"id":"worked-ratio-share-worked1","kind":"worked","src":"stop:ratio-share#worked1","title":"Worked out — Ratio: simplify and share: Simplify a ratio","body":"12 : 18 in simplest form is 2 : ?: 12 ÷ what makes 2? → 6 · Same to the other side: 18 ÷ 6 → 3","more":"What is special here: Divide both sides by the same number, just like simplifying a fraction. The mix stays the same.","cta":"Watch it step by step","where":"The Decimal Dock · Level 10","level":10,"route":"#/stop/ratio-share|learn|1"},"moment-ratio-share-beat3":{"id":"moment-ratio-share-beat3","kind":"moment","src":"story:ratio-share#beat3","badge":{"id":"story","label":"A story"},"title":"The mango crate — on the notepad","body":"Rafi: Five rounds of 2 for me. 5 × 2 = 10","more":"The trick in the story: Add the parts to find how many equal shares there are. Find one share, then multiply.","cta":"Read the story","where":"The Decimal Dock · Level 10","level":10,"route":"#/stop/ratio-share|story|3"},"try-ratio-share-L10":{"id":"try-ratio-share-L10","kind":"try","level":10,"src":"try:ratio-share@10/3#0","title":"Ratio: simplify and share — your turn","where":"The Decimal Dock · Level 10","route":"#/stop/ratio-share|drill","cta":"Practise this stop","play":{"q":"Share 136 in the ratio 3 : 5. How much is the smaller share?","opts":["51","8","61"],"after":"Add the parts to find how many equal shares there are. Find one share, then multiply.","show":[0,1,2]}},"hook-union-meet-hook":{"id":"hook-union-meet-hook","kind":"hook","src":"stop:union-meet#hook","title":"Can you? — Union and intersection","body":"A = {2, 4, 6, 8, 10}, B = {3, 6, 9}. How many in A ∪ B?","more":"The way in: A ∪ B (union) is everything in A or B or both; A ∩ B (intersection) is only what is in both. Count the shared ones once.","cta":"Find out how","where":"Set Island · Level 10","level":10,"route":"#/stop/union-meet|learn"},"worked-union-meet-worked0":{"id":"worked-union-meet-worked0","kind":"worked","src":"stop:union-meet#worked0","title":"Worked out — Union and intersection: Union of two lists","body":"A = {2, 4, 6, 8, 10}, B = {3, 6, 9}. n(A ∪ B)?: How many are in both A and B? → 1 · n(A) + n(B) = 5 + 3 → 8 · Take the shared ones once: − 1 → 7","more":"What is special here: Pour both lists into one bag, but a shared member goes in only once: add the two counts, then take the shared ones away.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/union-meet|learn|0"},"worked-union-meet-worked1":{"id":"worked-union-meet-worked1","kind":"worked","src":"stop:union-meet#worked1","title":"Worked out — Union and intersection: Intersection of two lists","body":"A = {1, 3, 5, 7, 9}, B = {3, 4, 5, 6}. n(A ∩ B)?: How many are in both A and B? → 2 · So n(A ∩ B) → 2","more":"What is special here: Keep only what is in BOTH lists — walk along one list and tick each member that the other list has too.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/union-meet|learn|1"},"worked-union-meet-worked2":{"id":"worked-union-meet-worked2","kind":"worked","src":"stop:union-meet#worked2","title":"Worked out — Union and intersection: Intersection by rule","body":"A = {multiples of 4 up to 50}, B = {multiples of 6 up to 50}. n(A ∩ B)?: In both means a multiple of 4 AND 6: the smallest is → 12 · How many multiples of 12 up to 50? → 4","more":"What is special here: A multiple of 4 AND of 6 is a multiple of their lowest common multiple, 12 — so count the multiples of 12.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/union-meet|learn|2"},"worked-union-meet-worked3":{"id":"worked-union-meet-worked3","kind":"worked","src":"stop:union-meet#worked3","title":"Worked out — Union and intersection: Union by rule","body":"A = {multiples of 3 up to 40}, B = {multiples of 5 up to 40}. n(A ∪ B)?: In both means a multiple of 3 AND 5: the smallest is → 15 · How many multiples of 15 up to 40? → 2 · n(A) + n(B) = 13 + 8 → 21 · − 2, counted twice → 19","more":"What is special here: Count each rule on its own and add — but the common multiples were counted twice, so take them away once.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/union-meet|learn|3"},"why-union-meet-why2":{"id":"why-union-meet-why2","kind":"why","src":"stop:union-meet#why2","title":"Why “Union and intersection” works","body":"So there is always a check: n(A ∪ B) = n(A) + n(B) − n(A ∩ B). The shared ones were counted twice by adding, so take them away once.","more":"The trick: A ∪ B (union) is everything in A or B or both; A ∩ B (intersection) is only what is in both. Count the shared ones once.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/union-meet|learn"},"moral-union-meet-beat5":{"id":"moral-union-meet-beat5","kind":"moral","src":"story:union-meet#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “Two teams, one bus”","body":"Seven seats for A union B. The shared ones go in once.","more":"The trick in the story: A ∪ B (union) is everything in A or B or both; A ∩ B (intersection) is only what is in both. Count the shared ones once.","cta":"Read the story","where":"Set Island · Level 10","level":10,"route":"#/stop/union-meet|story|5"},"try-union-meet-L10":{"id":"try-union-meet-L10","kind":"try","level":10,"src":"try:union-meet@10/3#0","title":"Union and intersection — your turn","where":"Set Island · Level 10","route":"#/stop/union-meet|drill","cta":"Practise this stop","play":{"q":"A = {3, 6, 8, 10, 16, 17, 19}, B = {4, 5, 11, 16, 18, 19, 20}. n(A ∩ B)?","opts":["2","1","6"],"after":"A ∪ B (union) is everything in A or B or both; A ∩ B (intersection) is only what is in both. Count the shared ones once.","show":[1,2,0]}},"hook-venn-count-hook":{"id":"hook-venn-count-hook","kind":"hook","src":"stop:venn-count#hook","title":"Can you? — Venn diagrams that count","body":"14 children play cricket, 11 play chess, 5 play both. How many play at least one?","more":"The way in: Add the two circles, then take away the overlap — it was counted twice.","cta":"Find out how","where":"Set Island · Level 10","level":10,"route":"#/stop/venn-count|learn"},"worked-venn-count-worked0":{"id":"worked-venn-count-worked0","kind":"worked","src":"stop:venn-count#worked0","title":"Worked out — Venn diagrams that count: Add the three parts","body":"The Venn diagram shows Cricket and Chess. How many are in at least one circle?: 9 + 5 → 14 · + 6 → 20","more":"What is special here: When the diagram shows every part, each child is in exactly one part — so just add them up.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/venn-count|learn|0"},"worked-venn-count-worked1":{"id":"worked-venn-count-worked1","kind":"worked","src":"stop:venn-count#worked1","title":"Worked out — Venn diagrams that count: Add, then take the overlap","body":"14 like Cricket, 11 like Chess, 5 like both. How many like at least one?: 14 + 11 → 25 · Take the overlap once: − 5 → 20","more":"What is special here: The totals for each circle both include the middle, so adding them counts the middle twice. Take it away once.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/venn-count|learn|1"},"worked-venn-count-worked2":{"id":"worked-venn-count-worked2","kind":"worked","src":"stop:venn-count#worked2","title":"Worked out — Venn diagrams that count: Find the overlap","body":"A class of 24: 14 like Cricket, 11 like Chess, 4 like neither. How many like both?: In the circles: 24 − 4 → 20 · 14 + 11 → 25 · Counted twice: 25 − 20 → 5","more":"What is special here: Backwards: the class minus \"neither\" is everyone in the circles. Adding the two circles overshoots — by exactly the ones in both.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/venn-count|learn|2"},"why-venn-count-why2":{"id":"why-venn-count-why2","kind":"why","src":"stop:venn-count#why2","title":"Why “Venn diagrams that count” works","body":"It runs backwards too. In a class of 24 where 4 play neither, 20 children are inside the circles. Adding the circles gave 25 — five too many — and the only children counted twice are the ones in the middle. So 5 play both. Whichever number is missing, the same equation finds it.","more":"The trick: Add the two circles, then take away the overlap — it was counted twice.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/venn-count|learn"},"moral-venn-count-beat5":{"id":"moral-venn-count-beat5","kind":"moral","src":"story:venn-count#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The club list”","body":"Twenty children. Add both circles, take the overlap once.","more":"The trick in the story: Add the two circles, then take away the overlap — it was counted twice.","cta":"Read the story","where":"Set Island · Level 10","level":10,"route":"#/stop/venn-count|story|5"},"try-venn-count-L10":{"id":"try-venn-count-L10","kind":"try","level":10,"src":"try:venn-count@10/3#0","title":"Venn diagrams that count — your turn","where":"Set Island · Level 10","route":"#/stop/venn-count|drill","cta":"Practise this stop","play":{"q":"A class of 37: 16 like Swim, 17 like Run, 5 like neither. How many like both?","opts":["1","7","2"],"after":"Add the two circles, then take away the overlap — it was counted twice.","show":[0,2,1]}},"hook-substitute-hook":{"id":"hook-substitute-hook","kind":"hook","src":"stop:substitute#hook","title":"Can you? — Letters for numbers","body":"If n = 4, what is 3n + 2?","more":"The way in: A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.","cta":"Find out how","where":"Set Island · Level 10","level":10,"route":"#/stop/substitute|learn"},"worked-substitute-worked0":{"id":"worked-substitute-worked0","kind":"worked","src":"stop:substitute#worked0","title":"Worked out — Letters for numbers: Times, then add","body":"If n = 4, what is 3n + 2?: 3 × 4 → 12 · Add 2 → 14","more":"What is special here: 3n is 3 × n — the × is hidden. Do the multiplying first, then the adding or taking away.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/substitute|learn|0"},"worked-substitute-worked1":{"id":"worked-substitute-worked1","kind":"worked","src":"stop:substitute#worked1","title":"Worked out — Letters for numbers: Brackets first","body":"If n = 6, what is 4(n − 2)?: Brackets first: 6 − 2 → 4 · 4 × 4 → 16","more":"What is special here: A number outside brackets multiplies the whole bracket, so work out the inside first.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/substitute|learn|1"},"worked-substitute-worked2":{"id":"worked-substitute-worked2","kind":"worked","src":"stop:substitute#worked2","title":"Worked out — Letters for numbers: Squaring a negative","body":"If n = −3, what is 2n² + 5?: n² = −3 × −3 → 9 · 2 × 9 → 18 · Add 5 → 23","more":"What is special here: n² is n × n. With a negative in the box, negative times negative is positive — so the square is never below zero.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/substitute|learn|2"},"worked-substitute-worked3":{"id":"worked-substitute-worked3","kind":"worked","src":"stop:substitute#worked3","title":"Worked out — Letters for numbers: Two letters","body":"If a = 4 and b = −2, what is 3a + 2b?: 3 × 4 → 12 · 2 × −2 → -4 · Add them → 8","more":"What is special here: Each letter has its own number. Fill both boxes, work out each term, then add — a negative term takes away.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/substitute|learn|3"},"why-substitute-why2":{"id":"why-substitute-why2","kind":"why","src":"stop:substitute#why2","title":"Why “Letters for numbers” works","body":"The order still matters: multiply before you add. And a number just outside brackets multiplies everything inside: 4(n − 2) with n = 6 is 4 × 4 = 16. n² means n × n, so a negative in the box comes out positive: (−3) × (−3) = 9. And with two letters, each gets its own number.","more":"The trick: A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/substitute|learn"},"moral-substitute-beat5":{"id":"moral-substitute-beat5","kind":"moral","src":"story:substitute#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The matchstick pattern”","body":"Fourteen matches! And the same rule tells me 40 triangles would need 122.","more":"The trick in the story: A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.","cta":"Read the story","where":"Set Island · Level 10","level":10,"route":"#/stop/substitute|story|5"},"algebra-substitute-alg":{"id":"algebra-substitute-alg","kind":"algebra","src":"stop:substitute#alg","title":"The algebra behind “Letters for numbers”","body":"an + b with n = k  →  a × k + b","more":"In words: A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/substitute|learn"},"try-substitute-L10":{"id":"try-substitute-L10","kind":"try","level":10,"src":"try:substitute@10/3#0","title":"Letters for numbers — your turn","where":"Set Island · Level 10","route":"#/stop/substitute|drill","cta":"Practise this stop","play":{"q":"If n = −9, what is 9n² + 17?","opts":["746","729","7460"],"after":"A letter is a box holding a number. Put the number in the box, then do the sum — times before plus.","show":[0,2,1]}},"hook-subset-count-hook":{"id":"hook-subset-count-hook","kind":"hook","src":"stop:subset-count#hook","title":"Can you? — How many subsets?","body":"{a, b, c, d} — how many different smaller sets can you make from it (counting the empty one)?","more":"The way in: Every member is either in or out. Two choices each, so n members give 2 × 2 × … × 2 = 2ⁿ subsets.","cta":"Find out how","where":"Set Island · Level 10","level":10,"route":"#/stop/subset-count|learn"},"worked-subset-count-worked0":{"id":"worked-subset-count-worked0","kind":"worked","src":"stop:subset-count#worked0","title":"Worked out — How many subsets?: All the subsets","body":"How many subsets does {a, b, c, d} have?: How many members? → 4 · In or out for each: 2 × 2 × 2 × 2 → 16","more":"What is special here: Every member is in or out — two choices each — so double for every member. The empty set and the whole set both count.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/subset-count|learn|0"},"worked-subset-count-worked1":{"id":"worked-subset-count-worked1","kind":"worked","src":"stop:subset-count#worked1","title":"Worked out — How many subsets?: Not empty","body":"How many subsets of {a, b, c, d} are NOT empty?: How many members? → 4 · In or out for each: 2 × 2 × 2 × 2 → 16 · Leave out the empty set → 15","more":"What is special here: Only one subset has every member out: the empty set. Count them all, then take away that one.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/subset-count|learn|1"},"worked-subset-count-worked2":{"id":"worked-subset-count-worked2","kind":"worked","src":"stop:subset-count#worked2","title":"Worked out — How many subsets?: Must contain a","body":"How many subsets of {a, b, c, d, e} contain a?: a is fixed in. How many members still to decide? → 4 · 2 choices each: 2 × 2 × 2 × 2 → 16","more":"What is special here: a has no choice now — it is in. Only the other members get in-or-out, so there are half as many.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/subset-count|learn|2"},"why-subset-count-why2":{"id":"why-subset-count-why2","kind":"why","src":"stop:subset-count#why2","title":"Why “How many subsets?” works","body":"Add one more member and every old subset splits in two — one without the new member, one with it. So each extra member doubles the count. Leave out the empty set and there are 2ⁿ − 1; insist a certain member is in and you have halved it: 2ⁿ⁻¹.","more":"The trick: Every member is either in or out. Two choices each, so n members give 2 × 2 × … × 2 = 2ⁿ subsets.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/subset-count|learn"},"moral-subset-count-beat5":{"id":"moral-subset-count-beat5","kind":"moral","src":"story:subset-count#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “Toppings on the pizza”","body":"Sixteen pizzas — and one of them is plain, with no topping at all. The empty set counts too!","more":"The trick in the story: Every member is either in or out. Two choices each, so n members give 2 × 2 × … × 2 = 2ⁿ subsets.","cta":"Read the story","where":"Set Island · Level 10","level":10,"route":"#/stop/subset-count|story|5"},"algebra-subset-count-alg":{"id":"algebra-subset-count-alg","kind":"algebra","src":"stop:subset-count#alg","title":"The algebra behind “How many subsets?”","body":"a set with n members has 2ⁿ subsets","more":"In words: Every member is either in or out. Two choices each, so n members give 2 × 2 × … × 2 = 2ⁿ subsets.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/subset-count|learn"},"try-subset-count-L10":{"id":"try-subset-count-L10","kind":"try","level":10,"src":"try:subset-count@10/3#0","title":"How many subsets? — your turn","where":"Set Island · Level 10","route":"#/stop/subset-count|drill","cta":"Practise this stop","play":{"q":"How many subsets does {a, b, c, d, e, f} have?","opts":["64","74","640"],"after":"Every member is either in or out. Two choices each, so n members give 2 × 2 × … × 2 = 2ⁿ subsets.","show":[2,1,0]}},"hook-solve-balance-hook":{"id":"hook-solve-balance-hook","kind":"hook","src":"stop:solve-balance#hook","title":"Can you? — Solving equations on a balance","body":"3x + 4 = 19 — what is x?","more":"The way in: An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.","cta":"Find out how","where":"Set Island · Level 10","level":10,"route":"#/stop/solve-balance|learn"},"worked-solve-balance-worked0":{"id":"worked-solve-balance-worked0","kind":"worked","src":"stop:solve-balance#worked0","title":"Worked out — Solving equations on a balance: Undo an add","body":"x + 7 = 16. What is x?: What has been added to x? → 7 · Take 7 off both sides: 16 − 7 → 9","more":"What is special here: Something was added to x. Take the same amount off both sides and x stands alone.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/solve-balance|learn|0"},"worked-solve-balance-worked1":{"id":"worked-solve-balance-worked1","kind":"worked","src":"stop:solve-balance#worked1","title":"Worked out — Solving equations on a balance: Undo a times","body":"4x = 24. What is x?: How many x's on the left? → 4 · Share both sides into 4: 24 ÷ 4 → 6","more":"What is special here: 4x means four x's. Share both sides into four equal parts to find one x.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/solve-balance|learn|1"},"worked-solve-balance-worked2":{"id":"worked-solve-balance-worked2","kind":"worked","src":"stop:solve-balance#worked2","title":"Worked out — Solving equations on a balance: Two steps","body":"3x + 4 = 19. What is x?: Take 4 off both sides → 15 · Share both sides into 3 → 5","more":"What is special here: Undo the last thing first: take away the plain number, THEN share. Doing it the other way round breaks the balance sum.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/solve-balance|learn|2"},"worked-solve-balance-worked3":{"id":"worked-solve-balance-worked3","kind":"worked","src":"stop:solve-balance#worked3","title":"Worked out — Solving equations on a balance: Words into an equation","body":"I think of a number. I multiply it by 4, then take away 3, and I get 25. What was my number?: As an equation: 4x − 3 = 25. What does 4x − 3 equal? → 25 · Add 3 to both sides → 28 · Share both sides into 4 → 7","more":"What is special here: Write the words as an equation first. Here a number was taken away, so undo it by adding to both sides.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/solve-balance|learn|3"},"why-solve-balance-why2":{"id":"why-solve-balance-why2","kind":"why","src":"stop:solve-balance#why2","title":"Why “Solving equations on a balance” works","body":"The order is the building order backwards. To make 3x + 4 you multiplied by 3, then added 4; to unmake it, take the 4 away first, then divide by 3. That is also how a word puzzle becomes an equation: \"I think of a number, times it by 3 and add 4, and get 19\" IS 3x + 4 = 19.","more":"The trick: An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/solve-balance|learn"},"moral-solve-balance-beat5":{"id":"moral-solve-balance-beat5","kind":"moral","src":"story:solve-balance#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “The weighing scale”","body":"Five marbles in each bag. Same to both sides, always.","more":"The trick in the story: An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.","cta":"Read the story","where":"Set Island · Level 10","level":10,"route":"#/stop/solve-balance|story|5"},"algebra-solve-balance-alg":{"id":"algebra-solve-balance-alg","kind":"algebra","src":"stop:solve-balance#alg","title":"The algebra behind “Solving equations on a balance”","body":"ax + b = c  ⇒  x = (c − b) ÷ a","more":"In words: An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/solve-balance|learn"},"try-solve-balance-L10":{"id":"try-solve-balance-L10","kind":"try","level":10,"src":"try:solve-balance@10/3#0","title":"Solving equations on a balance — your turn","where":"Set Island · Level 10","route":"#/stop/solve-balance|drill","cta":"Practise this stop","play":{"q":"I think of a number. I multiply it by 9, then take away 19, and I get 107. What was my number?","opts":["14","4","126"],"after":"An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone.","show":[2,1,0]}},"hook-nth-term-hook":{"id":"hook-nth-term-hook","kind":"hook","src":"stop:nth-term#hook","title":"Can you? — The nth term","body":"5, 8, 11, 14, … — what is the 20th number, without writing all twenty?","more":"The way in: Find the step. The nth term is the step × n, plus whatever fixes the first term.","cta":"Find out how","where":"Set Island · Level 10","level":10,"route":"#/stop/nth-term|learn"},"worked-nth-term-worked0":{"id":"worked-nth-term-worked0","kind":"worked","src":"stop:nth-term#worked0","title":"Worked out — The nth term: Find a far term","body":"5, 8, 11, 14, … What is the 20th term?: The step → 3 · Steps from the 1st to the 20th → 19 · 19 × 3 → 57 · + the first term, 5 → 62","more":"What is special here: From the 1st term to the 20th is 19 steps, not 20 — the first term is there before any step.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/nth-term|learn|0"},"worked-nth-term-worked1":{"id":"worked-nth-term-worked1","kind":"worked","src":"stop:nth-term#worked1","title":"Worked out — The nth term: The nth-term rule","body":"7, 11, 15, 19, … The nth term is 4n + □. What is □?: The step → 4 · 4n when n = 1 → 4 · First term − 4: what fixes it? → 3","more":"What is special here: The step is the times table. Compare the first term with the step: whatever you add (or take) to fix it is the number in the box.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/nth-term|learn|1"},"worked-nth-term-worked2":{"id":"worked-nth-term-worked2","kind":"worked","src":"stop:nth-term#worked2","title":"Worked out — The nth term: Which term is it?","body":"5, 8, 11, 14, … Which term is 47?: The step → 3 · Distance from the first term: 47 − 5 → 42 · Steps: 42 ÷ 3 → 14 · Plus one for the first term → 15","more":"What is special here: Run it backwards: how far from the first term, how many steps is that, then add one for the first term.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/nth-term|learn|2"},"why-nth-term-why2":{"id":"why-nth-term-why2","kind":"why","src":"stop:nth-term#why2","title":"Why “The nth term” works","body":"A sequence that goes up by the same amount each time is called linear, because if you plot it the points lie on a straight line. The step is the slope of that line — the next stop on this island.","more":"The trick: Find the step. The nth term is the step × n, plus whatever fixes the first term.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/nth-term|learn"},"moral-nth-term-beat5":{"id":"moral-nth-term-beat5","kind":"moral","src":"story:nth-term#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “Beach huts”","body":"Sixty-two. And 3 × 20 + 2 agrees: the rule is 3n + 2.","more":"The trick in the story: Find the step. The nth term is the step × n, plus whatever fixes the first term.","cta":"Read the story","where":"Set Island · Level 10","level":10,"route":"#/stop/nth-term|story|5"},"algebra-nth-term-alg":{"id":"algebra-nth-term-alg","kind":"algebra","src":"stop:nth-term#alg","title":"The algebra behind “The nth term”","body":"nth term = d·n + (a − d),  a = first term, d = step","more":"In words: Find the step. The nth term is the step × n, plus whatever fixes the first term.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/nth-term|learn"},"try-nth-term-L10":{"id":"try-nth-term-L10","kind":"try","level":10,"src":"try:nth-term@10/3#0","title":"The nth term — your turn","where":"Set Island · Level 10","route":"#/stop/nth-term|drill","cta":"Practise this stop","play":{"q":"2, 6, 10, 14, … Which term is 70?","opts":["18","17","4"],"after":"Find the step. The nth term is the step × n, plus whatever fixes the first term.","show":[0,1,2]}},"hook-line-graph-hook":{"id":"hook-line-graph-hook","kind":"hook","src":"stop:line-graph#hook","title":"Can you? — Straight-line graphs","body":"y = 2x + 1. When x = 3, where is the point?","more":"The way in: The rule turns every x into its y. m is how much y climbs for each step of x; c is where the line crosses the y-axis.","cta":"Find out how","where":"Set Island · Level 10","level":10,"route":"#/stop/line-graph|learn"},"worked-line-graph-worked0":{"id":"worked-line-graph-worked0","kind":"worked","src":"stop:line-graph#worked0","title":"Worked out — Straight-line graphs: Find y from the rule","body":"y = 2x + 1. What is y when x = 3?: 2 × 3 → 6 · Add 1 → 7","more":"What is special here: Put x into the rule: times by m, then add c. Every point on the line obeys it.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/line-graph|learn|0"},"worked-line-graph-worked1":{"id":"worked-line-graph-worked1","kind":"worked","src":"stop:line-graph#worked1","title":"Worked out — Straight-line graphs: Gradient from two points","body":"A straight line goes through (1, 5) and (3, 11). What is its gradient m?: The climb: 11 − 5 → 6 · The steps across: 3 − 1 → 2 · Climb ÷ steps → 3","more":"What is special here: The gradient is the climb divided by the steps across. Take the y's from each other, then the x's, then divide.","cta":"Watch it step by step","where":"Set Island · Level 10","level":10,"route":"#/stop/line-graph|learn|1"},"why-line-graph-why2":{"id":"why-line-graph-why2","kind":"why","src":"stop:line-graph#why2","title":"Why “Straight-line graphs” works","body":"So from two points you can find m: how far it climbed, divided by how far it went across. From (1, 5) to (3, 11) it climbed 6 in 2 steps: m = 3. It is the nth-term step again, drawn as a picture.","more":"The trick: The rule turns every x into its y. m is how much y climbs for each step of x; c is where the line crosses the y-axis.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/line-graph|learn"},"moral-line-graph-beat5":{"id":"moral-line-graph-beat5","kind":"moral","src":"story:line-graph#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The tide post”","body":"Seven metres deep after three hours.","more":"The trick in the story: The rule turns every x into its y. m is how much y climbs for each step of x; c is where the line crosses the y-axis.","cta":"Read the story","where":"Set Island · Level 10","level":10,"route":"#/stop/line-graph|story|5"},"algebra-line-graph-alg":{"id":"algebra-line-graph-alg","kind":"algebra","src":"stop:line-graph#alg","title":"The algebra behind “Straight-line graphs”","body":"y = mx + c   ·   m = (y₂ − y₁) ÷ (x₂ − x₁)","more":"In words: The rule turns every x into its y. m is how much y climbs for each step of x; c is where the line crosses the y-axis.","cta":"See why","where":"Set Island · Level 10","level":10,"route":"#/stop/line-graph|learn"},"try-line-graph-L10":{"id":"try-line-graph-L10","kind":"try","level":10,"src":"try:line-graph@10/3#0","title":"Straight-line graphs — your turn","where":"Set Island · Level 10","route":"#/stop/line-graph|drill","cta":"Practise this stop","play":{"q":"A straight line goes through (1, 3) and (5, 7). What is its gradient m?","opts":["1","4","6"],"after":"The rule turns every x into its y. m is how much y climbs for each step of x; c is where the line crosses the y-axis.","show":[0,1,2]}},"idea-cube-root-sight-case0":{"id":"idea-cube-root-sight-case0","kind":"idea","src":"stop:cube-root-sight#case0","title":"Cube roots by sight: The ending stays","body":"Endings 0, 1, 4, 5, 6 and 9 come back as themselves.","more":"The method: The last digit of a cube names the last digit of its root; the digits before the last three give the tens.","cta":"See it worked","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/cube-root-sight|learn|0"},"worked-cube-root-sight-worked1":{"id":"worked-cube-root-sight-worked1","kind":"worked","src":"stop:cube-root-sight#worked1","title":"Worked out — Cube roots by sight: The ending swaps","body":"The cube root of 54872: 54872 ends in 2. The root ends in → 8 · Cover the last three digits: 54. The biggest cube not over it is ?³ → 3 · Tens 3, ending 8: the root → 38","more":"What is special here: A cube ending in 2 has a root ending in 8 (and the other way round); 3 and 7 swap too.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/cube-root-sight|learn|1"},"algebra-cube-root-sight-alg":{"id":"algebra-cube-root-sight-alg","kind":"algebra","src":"stop:cube-root-sight#alg","title":"The algebra behind “Cube roots by sight”","body":"(10t + u)³ = 1000t³ + 300t²u + 30tu² + u³, so the last digit is the last digit of u³ and the thousands lie between t³ and (t + 1)³","more":"In words: The last digit of a cube names the last digit of its root; the digits before the last three give the tens.","cta":"See why","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/cube-root-sight|learn"},"try-cube-root-sight-L10":{"id":"try-cube-root-sight-L10","kind":"try","level":10,"src":"try:cube-root-sight@10/3#0","title":"Cube roots by sight — your turn","where":"The Sutra Ladder · Level 10","route":"#/stop/cube-root-sight|drill","cta":"Practise this stop","play":{"q":"The cube root of 226981 = ?","opts":["61","16","51"],"after":"The last digit of a cube names the last digit of its root; the digits before the last three give the tens.","show":[0,1,2]}},"idea-osculator-case0":{"id":"idea-osculator-case0","kind":"idea","src":"stop:osculator#case0","title":"Divisibility by osculators: The osculator: ends in 9","body":"A divisor ending in 9: one more than the digits before the 9.","more":"The method: Find the osculator, then chop off the last digit, multiply it by the osculator and add it to what is left. Repeat until the number is small.","cta":"See it worked","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/osculator|learn|0"},"worked-osculator-worked1":{"id":"worked-osculator-worked1","kind":"worked","src":"stop:osculator#worked1","title":"Worked out — Divisibility by osculators: The osculator: make a 9","body":"The osculator for 13?: 13 times what ends in 9? → 3 · 13 × 3 → 39 · One more than the digits before the 9 → 4","more":"What is special here: Not ending in 9? Multiply it until it does, then take one more than the digits before the 9.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/osculator|learn|1"},"why-osculator-why1":{"id":"why-osculator-why1","kind":"why","src":"stop:osculator#why1","title":"Why “Divisibility by osculators” works","body":"Why: 2 × 10 = 20 is one more than 19. Writing 4807 as 480 × 10 + 7, the step makes 480 + 2 × 7; times 10 that is 4800 + 140, which differs from 4807 by 7 × 19 — a multiple of 19. So the new number is in the 19 times table exactly when the old one was.","more":"The trick: Find the osculator, then chop off the last digit, multiply it by the osculator and add it to what is left. Repeat until the number is small.","cta":"See why","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/osculator|learn"},"moment-osculator-beat3":{"id":"moment-osculator-beat3","kind":"moment","src":"story:osculator#beat3","badge":{"id":"story","label":"A story"},"title":"Shelves of nineteen — on the notepad","body":"Ines: Again: chop off the 4, double it, add it to 49. 49 + 4 × 2 = 57","more":"The trick in the story: Find the osculator, then chop off the last digit, multiply it by the osculator and add it to what is left. Repeat until the number is small.","cta":"Read the story","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/osculator|story|3"},"try-osculator-L10":{"id":"try-osculator-L10","kind":"try","level":10,"src":"try:osculator@10/3#0","title":"Divisibility by osculators — your turn","where":"The Sutra Ladder · Level 10","route":"#/stop/osculator|drill","cta":"Practise this stop","play":{"q":"Is 41301 divisible by 13?","opts":["Yes","No"],"after":"Find the osculator, then chop off the last digit, multiply it by the osculator and add it to what is left. Repeat until the number is small.","show":[0,1]}},"idea-root-long-case0":{"id":"idea-root-long-case0","kind":"idea","src":"stop:root-long#case0","title":"Square roots by the duplex: Straight through","body":"Each division gives its digit straight away, and the last columns come out at zero.","more":"The method: Root the first group, then divide by twice that digit, taking off the duplex of the root digits found so far.","cta":"See it worked","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/root-long|learn|0"},"worked-root-long-worked1":{"id":"worked-root-long-worked1","kind":"worked","src":"stop:root-long#worked1","title":"Worked out — Square roots by the duplex: One less","body":"√20449: First group 2: the biggest square not over it is ?² → 1 · Divisor 2 × 1 = 2. 1 left, bring down 0: 10 ÷ 2 — one less, or the next column goes below zero → 4 · 2 left, bring down 4, take off the duplex 4² → 8 · 8 ÷ 2 — one less, or a later column goes below zero → 3 · The root → 143","more":"What is special here: A division would give a digit too big — the next column would go below zero — so take one less.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/root-long|learn|1"},"sutra-root-long-sutra":{"id":"sutra-root-long-sutra","kind":"sutra","src":"stop:root-long#sutra","title":"Ūrdhva-tiryagbhyām","body":"“vertically and crosswise” — the sutra behind Square roots by the duplex.","more":"What it does: Root the first group, then divide by twice that digit, taking off the duplex of the root digits found so far.","cta":"Open the stop","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/root-long|learn"},"algebra-root-long-alg":{"id":"algebra-root-long-alg","kind":"algebra","src":"stop:root-long#alg","title":"The algebra behind “Square roots by the duplex”","body":"(100a + 10b + c)² = 10⁴a² + 2a·(10b + c)·100 + (10b + c)²","more":"In words: Root the first group, then divide by twice that digit, taking off the duplex of the root digits found so far.","cta":"See why","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/root-long|learn"},"try-root-long-L10":{"id":"try-root-long-L10","kind":"try","level":10,"src":"try:root-long@10/3#0","title":"Square roots by the duplex — your turn","where":"The Sutra Ladder · Level 10","route":"#/stop/root-long|drill","cta":"Practise this stop","play":{"q":"√793881 = ?","opts":["891","881","819"],"after":"Root the first group, then divide by twice that digit, taking off the duplex of the root digits found so far.","show":[0,2,1]}},"idea-sutra-equations-case0":{"id":"idea-sutra-equations-case0","kind":"idea","src":"stop:sutra-equations#case0","title":"Two equations, crosswise: Swapped numbers","body":"The numbers swap places, so adding and subtracting give x + y and x − y at once.","more":"The method: Swapped numbers: add and subtract. Any numbers: cross-multiply, always in the same cycle, and divide.","cta":"See it worked","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/sutra-equations|learn|0"},"worked-sutra-equations-worked1":{"id":"worked-sutra-equations-worked1","kind":"worked","src":"stop:sutra-equations#worked1","title":"Worked out — Two equations, crosswise: Any numbers","body":"2x + 3y = 13 and 5x + 2y = 16. What is y?: Bottom: 3 × 5 − 2 × 2 → 11 · Top for y: 13 × 5 − 16 × 2 → 33 · y = top ÷ bottom → 3","more":"What is special here: Cross-multiply for the bottom and for each top, always in the same cycle, then divide.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/sutra-equations|learn|1"},"sutra-sutra-equations-sutra":{"id":"sutra-sutra-equations-sutra","kind":"sutra","src":"stop:sutra-equations#sutra","title":"Saṅkalana-vyavakalanābhyām","body":"“by addition and by subtraction” — the sutra behind Two equations, crosswise.","more":"What it does: Swapped numbers: add and subtract. Any numbers: cross-multiply, always in the same cycle, and divide.","cta":"Open the stop","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/sutra-equations|learn"},"algebra-sutra-equations-alg":{"id":"algebra-sutra-equations-alg","kind":"algebra","src":"stop:sutra-equations#alg","title":"The algebra behind “Two equations, crosswise”","body":"a₁x + b₁y = c₁, a₂x + b₂y = c₂  ⇒  x = (b₁c₂ − b₂c₁) ÷ (b₁a₂ − b₂a₁),  y = (c₁a₂ − c₂a₁) ÷ (b₁a₂ − b₂a₁)","more":"In words: Swapped numbers: add and subtract. Any numbers: cross-multiply, always in the same cycle, and divide.","cta":"See why","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/sutra-equations|learn"},"try-sutra-equations-L10":{"id":"try-sutra-equations-L10","kind":"try","level":10,"src":"try:sutra-equations@10/3#0","title":"Two equations, crosswise — your turn","where":"The Sutra Ladder · Level 10","route":"#/stop/sutra-equations|drill","cta":"Practise this stop","play":{"q":"−6x + 9y = 66 and 7x + y = 61. What is x?","opts":["7","69","13"],"after":"Swapped numbers: add and subtract. Any numbers: cross-multiply, always in the same cycle, and divide.","show":[1,2,0]}},"hook-quadratic-split-hook":{"id":"hook-quadratic-split-hook","kind":"hook","src":"stop:quadratic-split#hook","title":"Can you? — Factorising, proportionately","body":"6x² + 7x + 2 — which two brackets multiply to make it?","more":"The way in: Split the middle number so the first two numbers are in the same ratio as the last two. That ratio IS one bracket.","cta":"Find out how","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/quadratic-split|learn"},"worked-quadratic-split-worked0":{"id":"worked-quadratic-split-worked0","kind":"worked","src":"stop:quadratic-split#worked0","title":"Worked out — Factorising, proportionately: x²: last number positive","body":"x² − 7x + 12 = 0. The larger value of x?: Two numbers that multiply to 12 and add to −7: the larger → -3 · and the smaller → -4 · So (x − 3)(x − 4) = 0. The larger x is minus the smaller number → 4","more":"What is special here: The two numbers multiply to a positive number, so they have the same sign — both + or both −.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/quadratic-split|learn|0"},"worked-quadratic-split-worked1":{"id":"worked-quadratic-split-worked1","kind":"worked","src":"stop:quadratic-split#worked1","title":"Worked out — Factorising, proportionately: x²: last number negative","body":"x² + 2x − 15 = 0. The larger value of x?: Two numbers that multiply to −15 and add to 2: the larger → 5 · and the smaller → -3 · So (x + 5)(x − 3) = 0. The larger x is minus the smaller number → 3","more":"What is special here: A negative product means one number is + and the other −; the bigger one takes the middle number's sign.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/quadratic-split|learn|1"},"worked-quadratic-split-worked2":{"id":"worked-quadratic-split-worked2","kind":"worked","src":"stop:quadratic-split#worked2","title":"Worked out — Factorising, proportionately: A number before x²","body":"6x² + 7x + 2 = (2x + ?)(3x + ?). The number in the first bracket?: Split 7 into two parts that multiply to 6 × 2 = 12: the larger part → 4 · and the smaller part → 3 · 6 : part, in lowest terms, is 2 : ? — for the part that gives 2 → 1","more":"What is special here: Split the middle so the ratios match; the ratio is one bracket, and first-by-first, last-by-last gives the other.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/quadratic-split|learn|2"},"why-quadratic-split-why2":{"id":"why-quadratic-split-why2","kind":"why","src":"stop:quadratic-split#why2","title":"Why “Factorising, proportionately” works","body":"Why: (rx + p)(sx + q) = rs·x² + (rq + ps)·x + pq. The middle is made of two parts, rq and ps. And rs : ps = r : p — the first number and one part of the middle are always in the ratio of one bracket. The book's split is just reading that bracket back.","more":"The trick: Split the middle number so the first two numbers are in the same ratio as the last two. That ratio IS one bracket.","cta":"See why","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/quadratic-split|learn"},"moment-quadratic-split-beat2":{"id":"moment-quadratic-split-beat2","kind":"moment","src":"story:quadratic-split#beat2","badge":{"id":"story","label":"A story"},"title":"The tile rectangle — on the notepad","body":"Vesper: Split the 7 into 4 and 3. They multiply to 12 as well. 4 × 3 = 12","more":"The trick in the story: Split the middle number so the first two numbers are in the same ratio as the last two. That ratio IS one bracket.","cta":"Read the story","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/quadratic-split|story|2"},"algebra-quadratic-split-alg":{"id":"algebra-quadratic-split-alg","kind":"algebra","src":"stop:quadratic-split#alg","title":"The algebra behind “Factorising, proportionately”","body":"(rx + p)(sx + q) = rs·x² + (rq + ps)·x + pq,  and  rs : ps = rq : pq = r : p … s : q","more":"In words: Split the middle number so the first two numbers are in the same ratio as the last two. That ratio IS one bracket.","cta":"See why","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/quadratic-split|learn"},"try-quadratic-split-L10":{"id":"try-quadratic-split-L10","kind":"try","level":10,"src":"try:quadratic-split@10/3#0","title":"Factorising, proportionately — your turn","where":"The Sutra Ladder · Level 10","route":"#/stop/quadratic-split|drill","cta":"Practise this stop","play":{"q":"x² + 2x − 80 = 0. The larger value of x?","opts":["8","10","12"],"after":"Split the middle number so the first two numbers are in the same ratio as the last two. That ratio IS one bracket.","show":[2,0,1]}},"hook-pick-the-sutra-hook":{"id":"hook-pick-the-sutra-hook","kind":"hook","src":"stop:pick-the-sutra#hook","title":"Can you? — Pick the sutra","body":"98 × 97, 46 × 44, 43 × 27 — three products, three different best methods.","more":"The way in: Ask two questions in order: do the fronts match with last digits making ten? Are both close to the same base? If neither, vertically and crosswise.","cta":"Find out how","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/pick-the-sutra|learn"},"worked-pick-the-sutra-worked0":{"id":"worked-pick-the-sutra-worked0","kind":"worked","src":"stop:pick-the-sutra#worked0","title":"Worked out — Pick the sutra: Near a base","body":"98 × 97: which method fits best?: Same front part, and last digits that add to 10? → No · Both within a tenth of the same base (100 or 1000)? → Yes · So the best method is → Nikhilam: near a base","more":"What is special here: Both numbers sit close to 100 (or 1000), so the gaps are small: Nikhilam.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/pick-the-sutra|learn|0"},"worked-pick-the-sutra-worked1":{"id":"worked-pick-the-sutra-worked1","kind":"worked","src":"stop:pick-the-sutra#worked1","title":"Worked out — Pick the sutra: Last digits make ten","body":"46 × 44: which method fits best?: Same front part, and last digits that add to 10? → Yes · Both within a tenth of the same base (100 or 1000)? → No · So the best method is → Last digits make ten","more":"What is special here: Same front part, and the last digits add to 10: one more than the front, then the last digits multiplied.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/pick-the-sutra|learn|1"},"worked-pick-the-sutra-worked2":{"id":"worked-pick-the-sutra-worked2","kind":"worked","src":"stop:pick-the-sutra#worked2","title":"Worked out — Pick the sutra: Neither: crosswise","body":"43 × 27: which method fits best?: Same front part, and last digits that add to 10? → No · Both within a tenth of the same base (100 or 1000)? → No · So the best method is → Vertically and crosswise","more":"What is special here: No base nearby and no tens to make — vertically and crosswise works for every pair.","cta":"Watch it step by step","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/pick-the-sutra|learn|2"},"why-pick-the-sutra-why2":{"id":"why-pick-the-sutra-why2","kind":"why","src":"stop:pick-the-sutra#why2","title":"Why “Pick the sutra” works","body":"Otherwise, vertically and crosswise, which works for any two numbers at all (43 × 27). If a sum passes BOTH first tests, like 96 × 94, either quick method is fine — so this stop never asks about one.","more":"The trick: Ask two questions in order: do the fronts match with last digits making ten? Are both close to the same base? If neither, vertically and crosswise.","cta":"See why","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/pick-the-sutra|learn"},"moral-pick-the-sutra-beat5":{"id":"moral-pick-the-sutra-beat5","kind":"moral","src":"story:pick-the-sutra#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “Three sums, three tools”","body":"Three different tools, three right answers.","more":"The trick in the story: Ask two questions in order: do the fronts match with last digits making ten? Are both close to the same base? If neither, vertically and crosswise.","cta":"Read the story","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/pick-the-sutra|story|5"},"algebra-pick-the-sutra-alg":{"id":"algebra-pick-the-sutra-alg","kind":"algebra","src":"stop:pick-the-sutra#alg","title":"The algebra behind “Pick the sutra”","body":"same front and last digits sum to 10 → last digits make ten; else both within B/10 of a base B → Nikhilam; else → vertically and crosswise","more":"In words: Ask two questions in order: do the fronts match with last digits making ten? Are both close to the same base? If neither, vertically and crosswise.","cta":"See why","where":"The Sutra Ladder · Level 10","level":10,"route":"#/stop/pick-the-sutra|learn"},"try-pick-the-sutra-L10":{"id":"try-pick-the-sutra-L10","kind":"try","level":10,"src":"try:pick-the-sutra@10/3#0","title":"Pick the sutra — your turn","where":"The Sutra Ladder · Level 10","route":"#/stop/pick-the-sutra|drill","cta":"Practise this stop","play":{"q":"90 × 92: which method fits best?","opts":["Nikhilam: near a base","Last digits make ten","Vertically and crosswise"],"after":"Ask two questions in order: do the fronts match with last digits making ten? Are both close to the same base? If neither, vertically and crosswise.","show":[0,2,1]}},"worked-sunzi-multipliers-worked0":{"id":"worked-sunzi-multipliers-worked0","kind":"worked","src":"stop:sunzi-multipliers#worked0","title":"Worked out — Remainders by multipliers","body":"A number leaves 2 when divided by 3, and 4 when divided by 7. What is the smallest such number?: The smallest multiple of 7 that leaves 1 when divided by 3 → 7 · The smallest multiple of 3 that leaves 1 when divided by 7 → 15 · 2 lots of the first, plus 4 lots of the second → 74 · Take away 21 as many times as you can → 11","more":"The method: Build one multiplier for each divisor — a number that leaves 1 by that divisor and nothing by the other — then take each remainder lots of its multiplier, add, and take away the product as often as you can.","cta":"Watch it step by step","where":"The Counting Court · Level 10","level":10,"route":"#/stop/sunzi-multipliers|learn|0"},"moment-sunzi-multipliers-beat3":{"id":"moment-sunzi-multipliers-beat3","kind":"moment","src":"story:sunzi-multipliers#beat3","badge":{"id":"story","label":"A story"},"title":"The cupcake boxes — on the notepad","body":"Rafi: Two lots of the first, four of the second. 2 × 7 + 4 × 15 = 74","more":"The trick in the story: Build one multiplier for each divisor — a number that leaves 1 by that divisor and nothing by the other — then take each remainder lots of its multiplier, add, and take away the product as often as you can.","cta":"Read the story","where":"The Counting Court · Level 10","level":10,"route":"#/stop/sunzi-multipliers|story|3"},"try-sunzi-multipliers-L10":{"id":"try-sunzi-multipliers-L10","kind":"try","level":10,"src":"try:sunzi-multipliers@10/3#0","title":"Remainders by multipliers — your turn","where":"The Counting Court · Level 10","route":"#/stop/sunzi-multipliers|drill","cta":"Practise this stop","play":{"q":"A number leaves 5 when divided by 13, and 6 when divided by 12. What is the smallest such number?","opts":["18","13","8"],"after":"Build one multiplier for each divisor — a number that leaves 1 by that divisor and nothing by the other — then take each remainder lots of its multiplier, add, and take away the product as often as you can.","show":[0,2,1]}},"idea-sea-island-case0":{"id":"idea-sea-island-case0","kind":"idea","src":"stop:sea-island#case0","title":"The sea island survey: How tall is the peak?","body":"The gap fits into the pole distance some number of times: that many poles, plus one.","more":"The method: Set up two equal poles in line with the peak; the difference between how far back you must lie to sight the peak over each pole gives the height and the distance by similar triangles.","cta":"See it worked","where":"The Counting Court · Level 10","level":10,"route":"#/stop/sea-island|learn|0"},"worked-sea-island-worked1":{"id":"worked-sea-island-worked1","kind":"worked","src":"stop:sea-island#worked1","title":"Worked out — The sea island survey: How far away is it?","body":"Two poles, each 4 m tall, stand 80 m apart in a straight line with an island peak. Lying 7 m behind the nearer pole, you see the peak just over its top; behind the further pole you must lie 11 m back. How far is the nearer pole from the peak, in m?: How much further back did you lie the second time? → 4 · How many times does that fit into the 80 m between the poles? → 20 · Times the first back-step, 7 m → 140","more":"What is special here: The same number of times the first back-step.","cta":"Watch it step by step","where":"The Counting Court · Level 10","level":10,"route":"#/stop/sea-island|learn|1"},"moment-sea-island-beat3":{"id":"moment-sea-island-beat3","kind":"moment","src":"story:sea-island#beat3","badge":{"id":"story","label":"A story"},"title":"The rock in the lake — on the notepad","body":"Mira: It fits into the 60 m between the poles this many times. 60 ÷ 3 = 20","more":"The trick in the story: Set up two equal poles in line with the peak; the difference between how far back you must lie to sight the peak over each pole gives the height and the distance by similar triangles.","cta":"Read the story","where":"The Counting Court · Level 10","level":10,"route":"#/stop/sea-island|story|3"},"idea-liu-hui-case0":{"id":"idea-liu-hui-case0","kind":"idea","src":"stop:liu-hui#case0","title":"Liu Hui's polygons: The hexagon","body":"Six equilateral triangles: every side is a radius.","more":"The method: Fit a regular polygon inside the circle, double its number of sides again and again with Pythagoras, and its perimeter creeps up on the circle's.","cta":"See it worked","where":"The Counting Court · Level 10","level":10,"route":"#/stop/liu-hui|learn|0"},"worked-liu-hui-worked1":{"id":"worked-liu-hui-worked1","kind":"worked","src":"stop:liu-hui#worked1","title":"Worked out — Liu Hui's polygons: Double the sides","body":"A regular hexagon fits inside a circle of radius 10 cm. Put a new corner on the circle halfway between each pair of corners to make a regular 12-sided shape. How long is each of its sides, to 2 decimal places?: Half a side of the hexagon → 5 · Centre to the middle of that side: √(r² − half²), to 2 places → 8.66 · The gap from there out to the circle: r minus that → 1.34 · New side: √(half² + gap²), to 2 places → 5.18","more":"What is special here: Pythagoras twice: half a side and the gap make the new side.","cta":"Watch it step by step","where":"The Counting Court · Level 10","level":10,"route":"#/stop/liu-hui|learn|1"},"idea-liu-hui-case3":{"id":"idea-liu-hui-case3","kind":"idea","src":"stop:liu-hui#case3","title":"Liu Hui's polygons: Which is closer?","body":"Write both as decimals and compare with 3.1416.","more":"The method: Fit a regular polygon inside the circle, double its number of sides again and again with Pythagoras, and its perimeter creeps up on the circle's.","cta":"See it worked","where":"The Counting Court · Level 10","level":10,"route":"#/stop/liu-hui|learn|3"},"why-liu-hui-why2":{"id":"why-liu-hui-why2","kind":"why","src":"stop:liu-hui#why2","title":"Why “Liu Hui's polygons” works","body":"To double the sides, put a new corner on the circle halfway between two old ones. Pythagoras gives the distance from the centre to the middle of an old side; the radius minus that is a small gap; and Pythagoras again, with half an old side and the gap, gives the new side. Every doubling hugs the circle more tightly — 12 sides give about 3.11, 24 about 3.13, 96 about 3.14 — always a little under π, never over.","more":"The trick: Fit a regular polygon inside the circle, double its number of sides again and again with Pythagoras, and its perimeter creeps up on the circle's.","cta":"See why","where":"The Counting Court · Level 10","level":10,"route":"#/stop/liu-hui|learn"},"algebra-liu-hui-alg":{"id":"algebra-liu-hui-alg","kind":"algebra","src":"stop:liu-hui#alg","title":"The algebra behind “Liu Hui's polygons”","body":"s₂ₙ = √((sₙ/2)² + (r − √(r² − (sₙ/2)²))²)  ·  π ≈ n·sₙ ÷ 2r","more":"In words: Fit a regular polygon inside the circle, double its number of sides again and again with Pythagoras, and its perimeter creeps up on the circle's.","cta":"See why","where":"The Counting Court · Level 10","level":10,"route":"#/stop/liu-hui|learn"},"try-liu-hui-L10":{"id":"try-liu-hui-L10","kind":"try","level":10,"src":"try:liu-hui@10/3#0","title":"Liu Hui's polygons — your turn","where":"The Counting Court · Level 10","route":"#/stop/liu-hui|drill","cta":"Practise this stop","play":{"q":"A regular 24-sided shape fits inside a circle of radius 1. Each side is 0.2611 long. Perimeter ÷ diameter gives a value for π. What is it, to 2 decimal places?","opts":["3.13","3.03","6.2664"],"after":"Fit a regular polygon inside the circle, double its number of sides again and again with Pythagoras, and its perimeter creeps up on the circle's.","show":[1,0,2]}},"worked-hundred-fowls-worked0":{"id":"worked-hundred-fowls-worked0","kind":"worked","src":"stop:hundred-fowls#worked0","title":"Worked out — The hundred fowls","body":"At a farm sale a rooster costs 5 coins, a hen 3 coins, and chicks are sold 3 for 1 coin. Buy exactly 100 birds for exactly 100 coins, with at least one of each and as many roosters as possible. How many hens?: Multiply the coins by 3 and take away the birds: 14 for each rooster and 8 for each hen make → 200 · Roosters can only change in steps of 8 ÷ 2 to keep the hens whole. Step size → 4 · The most roosters on that ladder that leave at least one hen and some chicks → 12 · Hens: what the roosters leave, ÷ 8 → 4","more":"The method: Fold the two facts (birds and coins) into one that leaves out the chicks; its answers come in a family that steps along evenly, and a stated rule picks out exactly one.","cta":"Watch it step by step","where":"The Counting Court · Level 10","level":10,"route":"#/stop/hundred-fowls|learn|0"},"moment-hundred-fowls-beat4":{"id":"moment-hundred-fowls-beat4","kind":"moment","src":"story:hundred-fowls#beat4","badge":{"id":"story","label":"A story"},"title":"The farm sale — on the notepad","body":"Suki: As many roosters as possible: 12. Then the hens. (200 − 14 × 12) ÷ 8 = 4","more":"The trick in the story: Fold the two facts (birds and coins) into one that leaves out the chicks; its answers come in a family that steps along evenly, and a stated rule picks out exactly one.","cta":"Read the story","where":"The Counting Court · Level 10","level":10,"route":"#/stop/hundred-fowls|story|4"},"hook-pythagoras-side-hook":{"id":"hook-pythagoras-side-hook","kind":"hook","src":"stop:pythagoras-side#hook","title":"Can you? — Pythagoras’ theorem","body":"A rope runs from the top of a 12 m mast to a ring 5 m from its foot. How long is the rope — without climbing up to measure it?","more":"The way in: In a right-angled triangle, square the two short sides and add: that is the square of the longest side.","cta":"Find out how","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/pythagoras-side|learn"},"worked-pythagoras-side-worked0":{"id":"worked-pythagoras-side-worked0","kind":"worked","src":"stop:pythagoras-side#worked0","title":"Worked out — Pythagoras’ theorem: Find the longest side","body":"A right-angled triangle has short sides 12 m and 5 m. How long is the longest side?: 12² → 144 · 5² → 25 · 144 + 25 → 169 · Which number squared makes 169? → 13","more":"What is special here: Square the two short sides and ADD: the total is the square on the longest side.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/pythagoras-side|learn|0"},"worked-pythagoras-side-worked1":{"id":"worked-pythagoras-side-worked1","kind":"worked","src":"stop:pythagoras-side#worked1","title":"Worked out — Pythagoras’ theorem: Find a short side","body":"A right-angled triangle has a longest side of 17 m and one short side of 15 m. How long is the other short side?: 17² → 289 · 15² → 225 · 289 − 225 → 64 · Which number squared makes 64? → 8","more":"What is special here: Now the longest side is given, so its square is the big one. Take the small square AWAY from it instead of adding.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/pythagoras-side|learn|1"},"why-pythagoras-side-why2":{"id":"why-pythagoras-side-why2","kind":"why","src":"stop:pythagoras-side#why2","title":"Why “Pythagoras’ theorem” works","body":"It runs backwards too. If you know the longest side and one short side, take the small square away from the big one: 13² − 5² = 169 − 25 = 144, and 144 is 12². Sets of whole numbers that fit, like 3, 4, 5 and 5, 12, 13, are called Pythagorean triples — and any multiple of one (6, 8, 10) fits as well, because the whole triangle has just been scaled up.","more":"The trick: In a right-angled triangle, square the two short sides and add: that is the square of the longest side.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/pythagoras-side|learn"},"moral-pythagoras-side-beat6":{"id":"moral-pythagoras-side-beat6","kind":"moral","src":"story:pythagoras-side#beat6","badge":{"id":"story","label":"A story"},"title":"Mira, in “The mast rope”","body":"Thirteen metres of rope. Measured without leaving the deck.","more":"The trick in the story: In a right-angled triangle, square the two short sides and add: that is the square of the longest side.","cta":"Read the story","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/pythagoras-side|story|6"},"algebra-pythagoras-side-alg":{"id":"algebra-pythagoras-side-alg","kind":"algebra","src":"stop:pythagoras-side#alg","title":"The algebra behind “Pythagoras’ theorem”","body":"a² + b² = c² , where c is the side opposite the right angle","more":"In words: In a right-angled triangle, square the two short sides and add: that is the square of the longest side.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/pythagoras-side|learn"},"try-pythagoras-side-L10":{"id":"try-pythagoras-side-L10","kind":"try","level":10,"src":"try:pythagoras-side@10/3#0","title":"Pythagoras’ theorem — your turn","where":"The Lighthouse · Level 10","route":"#/stop/pythagoras-side|drill","cta":"Practise this stop","play":{"q":"A right-angled triangle has short sides 120 m and 27 m. How long is the longest side?","opts":["123","729","223"],"after":"In a right-angled triangle, square the two short sides and add: that is the square of the longest side.","show":[1,0,2]}},"hook-tan-height-hook":{"id":"hook-tan-height-hook","kind":"hook","src":"stop:tan-height#hook","title":"Can you? — Tan: how tall is the tower?","body":"A boat is 40 m from the lighthouse. The angle up to the lamp is 35°. How tall is the tower — from the boat?","more":"The way in: tan of the angle = opposite ÷ adjacent, so the height is the distance × tan of the angle.","cta":"Find out how","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tan-height|learn"},"worked-tan-height-worked0":{"id":"worked-tan-height-worked0","kind":"worked","src":"stop:tan-height#worked0","title":"Worked out — Tan: how tall is the tower?: Find the height","body":"A boat is 40 m from the foot of the lighthouse. The angle up to the top is 35°. Using tan 35° ≈ 0.7, how tall is the lighthouse, in metres?: Height is opposite the angle, distance is adjacent. Which ratio links them? → tan · height = distance × tan 35° = 40 × 0.7 → 28","more":"What is special here: The height is opposite and the distance adjacent, so height = distance × tan of the angle.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tan-height|learn|0"},"worked-tan-height-worked1":{"id":"worked-tan-height-worked1","kind":"worked","src":"stop:tan-height#worked1","title":"Worked out — Tan: how tall is the tower?: Find the distance","body":"The lighthouse is 25 m tall. From a boat, the angle up to the top is 27°. Using tan 27° ≈ 0.5, how far is the boat from the foot of the tower, in metres?: Height is opposite the angle, distance is adjacent. Which ratio links them? → tan · distance = height ÷ tan 27° = 25 ÷ 0.5 → 50","more":"What is special here: Going the other way, undo the times: distance = height ÷ tan of the angle.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tan-height|learn|1"},"why-tan-height-why2":{"id":"why-tan-height-why2","kind":"why","src":"stop:tan-height#why2","title":"Why “Tan: how tall is the tower?” works","body":"So the height is 40 × 0.7 = 28 m. To go the other way — from the height back to the distance — divide instead: distance = height ÷ tan. The answer is only as good as the given ratio: tan 35° is really 0.7002…, so 28 m is right to the nearest metre.","more":"The trick: tan of the angle = opposite ÷ adjacent, so the height is the distance × tan of the angle.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tan-height|learn"},"moral-tan-height-beat6":{"id":"moral-tan-height-beat6","kind":"moral","src":"story:tan-height#beat6","badge":{"id":"story","label":"A story"},"title":"Vesper, in “Measuring the tower”","body":"And the lamp-room plaque says 28 m.","more":"The trick in the story: tan of the angle = opposite ÷ adjacent, so the height is the distance × tan of the angle.","cta":"Read the story","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tan-height|story|6"},"algebra-tan-height-alg":{"id":"algebra-tan-height-alg","kind":"algebra","src":"stop:tan-height#alg","title":"The algebra behind “Tan: how tall is the tower?”","body":"tan θ = opposite ÷ adjacent ⇒ opposite = adjacent × tan θ","more":"In words: tan of the angle = opposite ÷ adjacent, so the height is the distance × tan of the angle.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tan-height|learn"},"try-tan-height-L10":{"id":"try-tan-height-L10","kind":"try","level":10,"src":"try:tan-height@10/3#0","title":"Tan: how tall is the tower? — your turn","where":"The Lighthouse · Level 10","route":"#/stop/tan-height|drill","cta":"Practise this stop","play":{"q":"A boat is 125 m from the foot of the lighthouse. The angle up to the top is 31°. Using tan 31° ≈ 0.6, how tall is the lighthouse, in metres?","opts":["75","85","750"],"after":"tan of the angle = opposite ÷ adjacent, so the height is the distance × tan of the angle.","show":[1,2,0]}},"hook-sin-cos-side-hook":{"id":"hook-sin-cos-side-hook","kind":"hook","src":"stop:sin-cos-side#hook","title":"Can you? — Sin and cos: the ladder","body":"A 10 m ladder leans on the lighthouse wall at 53° to the ground. How high does it reach? How far out is its foot?","more":"The way in: With the hypotenuse known: opposite = hypotenuse × sin, adjacent = hypotenuse × cos.","cta":"Find out how","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/sin-cos-side|learn"},"worked-sin-cos-side-worked0":{"id":"worked-sin-cos-side-worked0","kind":"worked","src":"stop:sin-cos-side#worked0","title":"Worked out — Sin and cos: the ladder: Height up the wall: sin","body":"A 10 m ladder leans on the lighthouse wall, at 53° to the ground. sin 53° ≈ 0.8 and cos 53° ≈ 0.6. How high up the wall does it reach, in metres?: The ladder is the hypotenuse. The height up the wall is the side… → opposite · So the ratio to use is → sin · 10 × sin 53° = 10 × 0.8 → 8","more":"What is special here: The height is opposite the angle at the ground, and the ladder is the hypotenuse: height = ladder × sin.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/sin-cos-side|learn|0"},"worked-sin-cos-side-worked1":{"id":"worked-sin-cos-side-worked1","kind":"worked","src":"stop:sin-cos-side#worked1","title":"Worked out — Sin and cos: the ladder: Foot from the wall: cos","body":"A 10 m ladder leans on the lighthouse wall, at 53° to the ground. sin 53° ≈ 0.8 and cos 53° ≈ 0.6. How far is its foot from the wall, in metres?: The ladder is the hypotenuse. The distance along the ground is the side… → adjacent · So the ratio to use is → cos · 10 × cos 53° = 10 × 0.6 → 6","more":"What is special here: The ground side touches the angle — it is adjacent — so use cos: distance = ladder × cos.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/sin-cos-side|learn|1"},"worked-sin-cos-side-worked2":{"id":"worked-sin-cos-side-worked2","kind":"worked","src":"stop:sin-cos-side#worked2","title":"Worked out — Sin and cos: the ladder: Ladder from height","body":"A ladder leans on the lighthouse wall at 30° to the ground and reaches 6 m up the wall. sin 30° = 0.5 and cos 30° ≈ 0.87. How long is the ladder, in metres?: The ladder is the hypotenuse. The height up the wall is the side… → opposite · So the ratio to use is → sin · ladder = 6 ÷ sin 30° = 6 ÷ 0.5 → 12","more":"What is special here: Now the ladder is the unknown. Height = ladder × sin, so undo it: ladder = height ÷ sin.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/sin-cos-side|learn|2"},"worked-sin-cos-side-worked3":{"id":"worked-sin-cos-side-worked3","kind":"worked","src":"stop:sin-cos-side#worked3","title":"Worked out — Sin and cos: the ladder: Ladder from foot","body":"A ladder leans on the lighthouse wall at 37° to the ground, with its foot 12 m from the wall. sin 37° ≈ 0.6 and cos 37° ≈ 0.8. How long is the ladder, in metres?: The ladder is the hypotenuse. The distance along the ground is the side… → adjacent · So the ratio to use is → cos · ladder = 12 ÷ cos 37° = 12 ÷ 0.8 → 15","more":"What is special here: The same undoing with the ground side: ladder = distance along the ground ÷ cos.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/sin-cos-side|learn|3"},"why-sin-cos-side-why2":{"id":"why-sin-cos-side-why2","kind":"why","src":"stop:sin-cos-side#why2","title":"Why “Sin and cos: the ladder” works","body":"To remember which is which: sin goes with the opposite side, cos with the adjacent side, tan divides those two. Some people say SOH CAH TOA — Sin Opposite over Hypotenuse, Cos Adjacent over Hypotenuse, Tan Opposite over Adjacent. If you know a short side and want the ladder, divide instead: ladder = height ÷ sin.","more":"The trick: With the hypotenuse known: opposite = hypotenuse × sin, adjacent = hypotenuse × cos.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/sin-cos-side|learn"},"moral-sin-cos-side-beat6":{"id":"moral-sin-cos-side-beat6","kind":"moral","src":"story:sin-cos-side#beat6","badge":{"id":"story","label":"A story"},"title":"Mira, in “The painter’s ladder”","body":"It reaches 8 metres up.","more":"The trick in the story: With the hypotenuse known: opposite = hypotenuse × sin, adjacent = hypotenuse × cos.","cta":"Read the story","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/sin-cos-side|story|6"},"algebra-sin-cos-side-alg":{"id":"algebra-sin-cos-side-alg","kind":"algebra","src":"stop:sin-cos-side#alg","title":"The algebra behind “Sin and cos: the ladder”","body":"sin θ = opp ÷ hyp · cos θ = adj ÷ hyp ⇒ opp = hyp × sin θ , adj = hyp × cos θ","more":"In words: With the hypotenuse known: opposite = hypotenuse × sin, adjacent = hypotenuse × cos.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/sin-cos-side|learn"},"try-sin-cos-side-L10":{"id":"try-sin-cos-side-L10","kind":"try","level":10,"src":"try:sin-cos-side@10/3#0","title":"Sin and cos: the ladder — your turn","where":"The Lighthouse · Level 10","route":"#/stop/sin-cos-side|drill","cta":"Practise this stop","play":{"q":"A 19 m ladder leans on the lighthouse wall, at 24° to the ground. sin 24° ≈ 0.4 and cos 24° ≈ 0.9. How far is its foot from the wall, in metres?","opts":["17.1","16.1","7.1"],"after":"With the hypotenuse known: opposite = hypotenuse × sin, adjacent = hypotenuse × cos.","show":[1,0,2]}},"hook-special-angles-hook":{"id":"hook-special-angles-hook","kind":"hook","src":"stop:special-angles#hook","title":"Can you? — The three special angles","body":"sin x = 1/2. Which angle is x — and can you know without a calculator?","more":"The way in: Two triangles hold the exact ratios: half a square (45°) and half an equilateral triangle (30° and 60°).","cta":"Find out how","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/special-angles|learn"},"worked-special-angles-worked0":{"id":"worked-special-angles-worked0","kind":"worked","src":"stop:special-angles#worked0","title":"Worked out — The three special angles: Sin: opposite ÷ hypotenuse","body":"sin x = 1/2, and x is between 0° and 90°. What is x?: Which triangle has sides that give 1/2: the half-square (1, 1, √2) or the half-equilateral (1, √3, 2)? → half-equilateral · In it, which angle has sin = 1/2? → 30°","more":"What is special here: In the half-equilateral, the short side 1 over the hypotenuse 2 is a half — and 1 is opposite the 30° corner.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/special-angles|learn|0"},"why-special-angles-why2":{"id":"why-special-angles-why2","kind":"why","src":"stop:special-angles#why2","title":"Why “The three special angles” works","body":"Read the ratios off it. From the 30° corner, the side opposite is the short one, 1: sin 30° = 1/2. From the 60° corner, that same side of 1 is adjacent: cos 60° = 1/2. And tan 60° = √3 ÷ 1 = √3. Every one of these is exact, and every one is a proof you can draw on the back of an envelope.","more":"The trick: Two triangles hold the exact ratios: half a square (45°) and half an equilateral triangle (30° and 60°).","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/special-angles|learn"},"moral-special-angles-beat5":{"id":"moral-special-angles-beat5","kind":"moral","src":"story:special-angles#beat5","badge":{"id":"story","label":"A story"},"title":"Mira, in “The folded napkin”","body":"So sin 30° is exactly one half. No calculator — just a folded napkin.","more":"The trick in the story: Two triangles hold the exact ratios: half a square (45°) and half an equilateral triangle (30° and 60°).","cta":"Read the story","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/special-angles|story|5"},"algebra-special-angles-alg":{"id":"algebra-special-angles-alg","kind":"algebra","src":"stop:special-angles#alg","title":"The algebra behind “The three special angles”","body":"sin 30° = cos 60° = 1/2 · sin 45° = cos 45° = 1/√2 · tan 45° = 1 · sin 60° = cos 30° = √3/2 · tan 60° = √3 · tan 30° = 1/√3","more":"In words: Two triangles hold the exact ratios: half a square (45°) and half an equilateral triangle (30° and 60°).","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/special-angles|learn"},"hook-bearings-hook":{"id":"hook-bearings-hook","kind":"hook","src":"stop:bearings#hook","title":"Can you? — Bearings: the way back","body":"A ship leaves the lighthouse on a bearing of 065°. What bearing brings it straight home?","more":"The way in: A bearing is measured clockwise from north, in three figures; the way back is the way out ± 180°.","cta":"Find out how","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/bearings|learn"},"worked-bearings-worked0":{"id":"worked-bearings-worked0","kind":"worked","src":"stop:bearings#worked0","title":"Worked out — Bearings: the way back: Out under 180°: add","body":"A ship leaves the lighthouse on a bearing of 065°. What bearing takes it straight back? Type the number of degrees (a leading zero is fine either way).: Is 065° less than 180°? → Yes · So add half a turn: 65 + 180 → 245","more":"What is special here: Half a turn more still fits inside a whole turn, so add 180°.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/bearings|learn|0"},"worked-bearings-worked1":{"id":"worked-bearings-worked1","kind":"worked","src":"stop:bearings#worked1","title":"Worked out — Bearings: the way back: Out over 180°: take away","body":"A ship leaves the lighthouse on a bearing of 300°. What bearing takes it straight back? Type the number of degrees (a leading zero is fine either way).: Is 300° less than 180°? → No · So take half a turn away: 300 − 180 → 120","more":"What is special here: Adding 180° would go past 360°, all the way round. Take 180° away instead to face the opposite way.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/bearings|learn|1"},"why-bearings-why2":{"id":"why-bearings-why2","kind":"why","src":"stop:bearings#why2","title":"Why “Bearings: the way back” works","body":"Check it with a picture: north and south are opposite, and so are east and west. 090° and 270° differ by 180°, and so must any bearing and its way back. The back bearing is always the other number of the pair.","more":"The trick: A bearing is measured clockwise from north, in three figures; the way back is the way out ± 180°.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/bearings|learn"},"moral-bearings-beat5":{"id":"moral-bearings-beat5","kind":"moral","src":"story:bearings#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “The way home”","body":"Bearing 245. The lamp should be dead ahead.","more":"The trick in the story: A bearing is measured clockwise from north, in three figures; the way back is the way out ± 180°.","cta":"Read the story","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/bearings|story|5"},"algebra-bearings-alg":{"id":"algebra-bearings-alg","kind":"algebra","src":"stop:bearings#alg","title":"The algebra behind “Bearings: the way back”","body":"back bearing = bearing + 180° (if under 180°) , bearing − 180° (if over 180°)","more":"In words: A bearing is measured clockwise from north, in three figures; the way back is the way out ± 180°.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/bearings|learn"},"hook-tree-diagram-hook":{"id":"hook-tree-diagram-hook","kind":"hook","src":"stop:tree-diagram#hook","title":"Can you? — Tree diagrams","body":"The morning ferry is late 1 time in 4, the evening ferry 2 times in 5. What is the chance both are late?","more":"The way in: Multiply along the branches for one path; add the paths when more than one path counts.","cta":"Find out how","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tree-diagram|learn"},"worked-tree-diagram-worked0":{"id":"worked-tree-diagram-worked0","kind":"worked","src":"stop:tree-diagram#worked0","title":"Worked out — Tree diagrams: One path: multiply","body":"The chance that the morning ferry is late is 1/4. The chance that the evening ferry is late is 2/5, whatever the first one does. What is the chance that the morning ferry is late and the evening ferry is late?: The chance on the “late” branch for the morning ferry → 1/4 · The chance on the “late” branch for the evening ferry → 2/5 · Multiply along the path → 1/10","more":"What is special here: Follow the one path where both happen, and multiply the chances along it — a fraction of a fraction.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tree-diagram|learn|0"},"worked-tree-diagram-worked2":{"id":"worked-tree-diagram-worked2","kind":"worked","src":"stop:tree-diagram#worked2","title":"Worked out — Tree diagrams: Two paths: add","body":"The chance that the morning ferry is late is 1/4. The chance that the evening ferry is late is 2/5, whatever the first one does. What is the chance that exactly one of the two ferries is late?: Path late then on time: 1/4 × 3/5 → 3/20 · Path on time then late: 3/4 × 2/5 → 3/10 · Either path will do, so add them → 9/20","more":"What is special here: Exactly one late can happen two ways. Multiply along each path, then add the two, because either will do.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tree-diagram|learn|2"},"why-tree-diagram-why2":{"id":"why-tree-diagram-why2","kind":"why","src":"stop:tree-diagram#why2","title":"Why “Tree diagrams” works","body":"Why add? “Exactly one is late” can happen in two different ways — late then on time, or on time then late. Those paths never happen together, so their chances simply add. The chances on all four tips add up to 1, because between them they are everything that can happen.","more":"The trick: Multiply along the branches for one path; add the paths when more than one path counts.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tree-diagram|learn"},"moral-tree-diagram-beat5":{"id":"moral-tree-diagram-beat5","kind":"moral","src":"story:tree-diagram#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “Two ferries”","body":"One quarter times two fifths: two twentieths, which is one tenth.","more":"The trick in the story: Multiply along the branches for one path; add the paths when more than one path counts.","cta":"Read the story","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tree-diagram|story|5"},"algebra-tree-diagram-alg":{"id":"algebra-tree-diagram-alg","kind":"algebra","src":"stop:tree-diagram#alg","title":"The algebra behind “Tree diagrams”","body":"P(A and B) = P(A) × P(B) (independent) · P(one path or another) = sum of the paths","more":"In words: Multiply along the branches for one path; add the paths when more than one path counts.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/tree-diagram|learn"},"try-tree-diagram-L10":{"id":"try-tree-diagram-L10","kind":"try","level":10,"src":"try:tree-diagram@10/3#0","title":"Tree diagrams — your turn","where":"The Lighthouse · Level 10","route":"#/stop/tree-diagram|drill","cta":"Practise this stop","play":{"q":"The chance that the lamp bulb fails is 3/4. The chance that the spare bulb fails is 4/5, whatever the first one does. What is the chance that the two bulbs do the same thing (both fail, or both work)?","opts":["13/20","3/5","13/21"],"after":"Multiply along the branches for one path; add the paths when more than one path counts.","show":[2,0,1]}},"hook-expected-frequency-hook":{"id":"hook-expected-frequency-hook","kind":"hook","src":"stop:expected-frequency#hook","title":"Can you? — Expected frequency","body":"The logbook says it rains on 3 nights in every 10. How many wet nights should the keeper plan for in the next 60?","more":"The way in: Expected number = probability × number of trials: take that fraction of the trials.","cta":"Find out how","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/expected-frequency|learn"},"worked-expected-frequency-worked0":{"id":"worked-expected-frequency-worked0","kind":"worked","src":"stop:expected-frequency#worked0","title":"Worked out — Expected frequency: A fraction chance","body":"The keeper’s logbook shows rain on 3 nights in every 10. How many rainy nights would you expect in the next 60 nights?: The chance as a fraction: 3 out of 10, in its simplest form → 3/10 · Share the 60 trials into 10 equal parts: 60 ÷ 10 → 6 · Take 3 of those parts: 6 × 3 → 18","more":"What is special here: Split the trials into equal groups — the bottom of the fraction — and take the top number of those groups.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/expected-frequency|learn|0"},"worked-expected-frequency-worked1":{"id":"worked-expected-frequency-worked1","kind":"worked","src":"stop:expected-frequency#worked1","title":"Worked out — Expected frequency: Faces of a die","body":"A fair die is rolled 60 times. How many times would you expect to roll a 5 or a 6?: The chance: winning faces out of 6, in its simplest form → 1/3 · Share the 60 trials into 3 equal parts: 60 ÷ 3 → 20","more":"What is special here: The chance is not written down: count the faces that win, out of 6, and simplify before you share.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/expected-frequency|learn|1"},"worked-expected-frequency-worked2":{"id":"worked-expected-frequency-worked2","kind":"worked","src":"stop:expected-frequency#worked2","title":"Worked out — Expected frequency: A decimal chance","body":"The chance of fog on any night is 0.15. How many foggy nights would you expect in 200 nights?: 0.15 as a fraction in its simplest form → 3/20 · Share the 200 trials into 20 equal parts: 200 ÷ 20 → 10 · Take 3 of those parts: 10 × 3 → 30","more":"What is special here: A decimal is a fraction in disguise: 0.15 is 15 hundredths, which is 3/20.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/expected-frequency|learn|2"},"why-expected-frequency-why1":{"id":"why-expected-frequency-why1","kind":"why","src":"stop:expected-frequency#why1","title":"Why “Expected frequency” works","body":"Expected does not mean promised. Toss a coin 60 times and you expect 30 heads, but you might easily get 27, or 34 — every toss is still chancy. Real counts wobble around the expected number, sometimes above and sometimes below. What you can count on is the middle they wobble round: the more trials, the closer the share of heads creeps to 1/2, even though the count is rarely exactly half.","more":"The trick: Expected number = probability × number of trials: take that fraction of the trials.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/expected-frequency|learn"},"moment-expected-frequency-beat3":{"id":"moment-expected-frequency-beat3","kind":"moment","src":"story:expected-frequency#beat3","badge":{"id":"story","label":"A story"},"title":"Sixty nights of weather — on the notepad","body":"Theo: Six lots of ten nights, with 3 wet ones in each. 6 × 3 = 18","more":"The trick in the story: Expected number = probability × number of trials: take that fraction of the trials.","cta":"Read the story","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/expected-frequency|story|3"},"algebra-expected-frequency-alg":{"id":"algebra-expected-frequency-alg","kind":"algebra","src":"stop:expected-frequency#alg","title":"The algebra behind “Expected frequency”","body":"expected frequency = P(event) × number of trials","more":"In words: Expected number = probability × number of trials: take that fraction of the trials.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/expected-frequency|learn"},"try-expected-frequency-L10":{"id":"try-expected-frequency-L10","kind":"try","level":10,"src":"try:expected-frequency@10/3#6","title":"Expected frequency — your turn","where":"The Lighthouse · Level 10","route":"#/stop/expected-frequency|drill","cta":"Practise this stop","play":{"q":"The chance that a passing ship signals to the lighthouse is 0.05. 220 ships pass. How many would you expect to signal?","opts":["11","5","8"],"after":"Expected number = probability × number of trials: take that fraction of the trials.","show":[1,2,0]}},"hook-inequalities-hook":{"id":"hook-inequalities-hook","kind":"hook","src":"stop:inequalities#hook","title":"Can you? — Inequalities","body":"3x + 4 < 19. Not one answer this time — a whole range of them. What is the biggest whole number that works?","more":"The way in: Solve it like an equation, doing the same to both sides — but if you multiply or divide by a negative, turn the sign round.","cta":"Find out how","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/inequalities|learn"},"worked-inequalities-worked0":{"id":"worked-inequalities-worked0","kind":"worked","src":"stop:inequalities#worked0","title":"Worked out — Inequalities: Less than: the largest","body":"3x + 4 < 19. What is the largest integer x that makes this true?: Take 4 from both sides: 19 − 4 → 15 · Divide both sides by 3: 15 ÷ 3 → 5 · Did you divide by a negative number, so the sign turns round? → No · x < 5, so the largest integer is → 4","more":"What is special here: Solve it like an equation. x < 5 lets in 4 but not 5 itself, so the largest whole number is one below.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/inequalities|learn|0"},"worked-inequalities-worked1":{"id":"worked-inequalities-worked1","kind":"worked","src":"stop:inequalities#worked1","title":"Worked out — Inequalities: More than: the smallest","body":"2x + 3 > 11. What is the smallest integer x that makes this true?: Take 3 from both sides: 11 − 3 → 8 · Divide both sides by 2: 8 ÷ 2 → 4 · Did you divide by a negative number, so the sign turns round? → No · x > 4, so the smallest integer is → 5","more":"What is special here: Now the answers run upwards, so look for the smallest. x > 4 does not include 4, so start one above.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/inequalities|learn|1"},"worked-inequalities-worked3":{"id":"worked-inequalities-worked3","kind":"worked","src":"stop:inequalities#worked3","title":"Worked out — Inequalities: The whole answer","body":"Solve 4x − 2 ≥ 10. Which of these is the answer?: Add 2 to both sides: 10 + 2 → 12 · Divide both sides by 4: 12 ÷ 4 → 3 · Did you divide by a negative number, so the sign turns round? → No · So the answer is → x ≥ 3","more":"What is special here: The answer is a whole range, written like x ≥ 3. Dividing by a positive number, the sign stays the one you started with.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/inequalities|learn|3"},"worked-inequalities-worked4":{"id":"worked-inequalities-worked4","kind":"worked","src":"stop:inequalities#worked4","title":"Worked out — Inequalities: Dividing by a negative","body":"−2x + 1 < 7. What is the smallest integer x that makes this true?: Take 1 from both sides: 7 − 1 → 6 · Divide both sides by −2: 6 ÷ (−2) → -3 · Did you divide by a negative number, so the sign turns round? → Yes · x > −3, so the smallest integer is → -2","more":"What is special here: Dividing both sides by a negative number mirrors the number line, so the sign turns round: < becomes >.","cta":"Watch it step by step","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/inequalities|learn|4"},"why-inequalities-why2":{"id":"why-inequalities-why2","kind":"why","src":"stop:inequalities#why2","title":"Why “Inequalities” works","body":"The one trap: multiplying or dividing by a negative number flips the inequality round. On a number line, 2 < 6. Times both by −1 and you get −2 and −6 — and −2 is the higher one: −2 > −6. Multiplying by a negative mirrors the line, so the order reverses. That is why −2x < 6 means x > −3, not x < −3: try x = 0, and −2 × 0 = 0 is indeed less than 6.","more":"The trick: Solve it like an equation, doing the same to both sides — but if you multiply or divide by a negative, turn the sign round.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/inequalities|learn"},"moral-inequalities-beat6":{"id":"moral-inequalities-beat6","kind":"moral","src":"story:inequalities#beat6","badge":{"id":"story","label":"A story"},"title":"Kwame, in “The weight limit”","body":"The biggest whole number below 5.","more":"The trick in the story: Solve it like an equation, doing the same to both sides — but if you multiply or divide by a negative, turn the sign round.","cta":"Read the story","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/inequalities|story|6"},"algebra-inequalities-alg":{"id":"algebra-inequalities-alg","kind":"algebra","src":"stop:inequalities#alg","title":"The algebra behind “Inequalities”","body":"a·x + b < c ⇒ x < (c − b) ÷ a if a > 0 ; x > (c − b) ÷ a if a < 0","more":"In words: Solve it like an equation, doing the same to both sides — but if you multiply or divide by a negative, turn the sign round.","cta":"See why","where":"The Lighthouse · Level 10","level":10,"route":"#/stop/inequalities|learn"},"hook-permutations-hook":{"id":"hook-permutations-hook","kind":"hook","src":"stop:permutations#hook","title":"Can you? — Permutations: order matters","body":"8 runners in the final. How many ways can gold, silver and bronze be given out?","more":"The way in: When order matters and nothing repeats, count the choices for each place and multiply: n × (n − 1) × … for r places.","cta":"Find out how","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/permutations|learn"},"worked-permutations-worked0":{"id":"worked-permutations-worked0","kind":"worked","src":"stop:permutations#worked0","title":"Worked out — Permutations: order matters: Order, no repeats","body":"8 runners are in the final. How many ways can the gold, silver and bronze medals be given out?: Choices for gold → 8 · Then silver: one fewer to choose from → 7 · Then bronze: one fewer to choose from → 6 · 8 × 7 × 6 → 336","more":"What is special here: Gold, silver and bronze are different places, and nobody wins two medals: 8, then 7, then 6 choices.","cta":"Watch it step by step","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/permutations|learn|0"},"worked-permutations-worked1":{"id":"worked-permutations-worked1","kind":"worked","src":"stop:permutations#worked1","title":"Worked out — Permutations: order matters: Repeats allowed","body":"A padlock has 3 dials, each showing the digits 0 to 9. How many different codes can it show?: Choices for each place — and a repeat is allowed → 10 · How many places? → 3 · 10 × 10 × 10 → 1000","more":"What is special here: A digit can come back, so every place keeps ALL its choices: 10 × 10 × 10, not 10 × 9 × 8.","cta":"Watch it step by step","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/permutations|learn|1"},"worked-permutations-worked2":{"id":"worked-permutations-worked2","kind":"worked","src":"stop:permutations#worked2","title":"Worked out — Permutations: order matters: The ⁿPᵣ shorthand","body":"Work out ⁷P₃: Choices for the first place → 7 · Then the second place: one fewer to choose from → 6 · Then the third place: one fewer to choose from → 5 · 7 × 6 × 5 → 210","more":"What is special here: ⁷P₃ means \"choose 3 of 7, in order\": start at 7 and multiply 3 numbers going down.","cta":"Watch it step by step","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/permutations|learn|2"},"why-permutations-why2":{"id":"why-permutations-why2","kind":"why","src":"stop:permutations#why2","title":"Why “Permutations: order matters” works","body":"Watch for repeats. A padlock with 3 dials, each 0 to 9, can show 777 — so every dial keeps all 10 choices: 10 × 10 × 10 = 1,000 codes. With no repeats allowed, each place has one fewer: 10 × 9 × 8 = 720. Always ask first: can a thing be used twice?","more":"The trick: When order matters and nothing repeats, count the choices for each place and multiply: n × (n − 1) × … for r places.","cta":"See why","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/permutations|learn"},"moral-permutations-beat5":{"id":"moral-permutations-beat5","kind":"moral","src":"story:permutations#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “The medal table”","body":"Three hundred and thirty-six ways. Checked.","more":"The trick in the story: When order matters and nothing repeats, count the choices for each place and multiply: n × (n − 1) × … for r places.","cta":"Read the story","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/permutations|story|5"},"algebra-permutations-alg":{"id":"algebra-permutations-alg","kind":"algebra","src":"stop:permutations#alg","title":"The algebra behind “Permutations: order matters”","body":"ⁿPᵣ = n × (n − 1) × … (r factors) = n! ÷ (n − r)! · with repeats: n × n × … = nʳ","more":"In words: When order matters and nothing repeats, count the choices for each place and multiply: n × (n − 1) × … for r places.","cta":"See why","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/permutations|learn"},"try-permutations-L10":{"id":"try-permutations-L10","kind":"try","level":10,"src":"try:permutations@10/3#0","title":"Permutations: order matters — your turn","where":"The Data Carnival · Level 10","route":"#/stop/permutations|drill","cta":"Practise this stop","play":{"q":"Work out ¹¹P₃ = ?","opts":["990","9900","1000"],"after":"When order matters and nothing repeats, count the choices for each place and multiply: n × (n − 1) × … for r places.","show":[0,1,2]}},"hook-combinations-hook":{"id":"hook-combinations-hook","kind":"hook","src":"stop:combinations#hook","title":"Can you? — Combinations: order doesn't matter","body":"7 players, a team of 3. How many different teams — and why are there fewer than ways to give out 3 medals?","more":"The way in: Count as if order mattered, then divide by r! — the number of orders each group was counted in.","cta":"Find out how","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/combinations|learn"},"worked-combinations-worked0":{"id":"worked-combinations-worked0","kind":"worked","src":"stop:combinations#worked0","title":"Worked out — Combinations: order doesn't matter: Pairs: halve it","body":"6 friends want to enter the three-legged race. How many different pairs could they make?: In order: 6 × 5 → 30 · Each pair was counted twice — halve it → 15","more":"What is special here: Picking Asha then Ben gives the same pair as Ben then Asha. Count in order, then halve.","cta":"Watch it step by step","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/combinations|learn|0"},"worked-combinations-worked1":{"id":"worked-combinations-worked1","kind":"worked","src":"stop:combinations#worked1","title":"Worked out — Combinations: order doesn't matter: A group: ÷ r!","body":"How many different teams of 3 can be picked from 7 players?: Pick 3 in order: 7 × 6 × 5 → 210 · Orders of one group of 3: 3! → 6 · 210 ÷ 6 → 35","more":"What is special here: Count in order, then divide by the number of orders one team can be picked in: 3! = 6.","cta":"Watch it step by step","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/combinations|learn|1"},"worked-combinations-worked2":{"id":"worked-combinations-worked2","kind":"worked","src":"stop:combinations#worked2","title":"Worked out — Combinations: order doesn't matter: Choose who stays out","body":"10 children want to play, but the team has 8 places. How many different teams could be picked?: Choosing 8 to play is choosing who sits out. How many sit out? → 2 · Pick 2 in order: 10 × 9 → 90 · Orders of one group of 2: 2! → 2 · 90 ÷ 2 → 45","more":"What is special here: Picking 8 to play is picking 2 to sit out — the same number of ways, and far quicker to count.","cta":"Watch it step by step","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/combinations|learn|2"},"worked-combinations-worked3":{"id":"worked-combinations-worked3","kind":"worked","src":"stop:combinations#worked3","title":"Worked out — Combinations: order doesn't matter: A chance, by counting","body":"A drawer holds 4 yellow and 3 blue socks. You pull out 2 without looking. What is the chance both are yellow?: Pairs of yellow socks: 4 × 3 ÷ 2 → 6 · All the pairs: 7 × 6 ÷ 2 → 21 · The chance, as a fraction → 6/21","more":"What is special here: Count the pairs you want, then all the pairs. The chance is one over the other, as a fraction.","cta":"Watch it step by step","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/combinations|learn|3"},"why-combinations-why2":{"id":"why-combinations-why2","kind":"why","src":"stop:combinations#why2","title":"Why “Combinations: order doesn't matter” works","body":"Choosing who is IN also chooses who is OUT. Picking 8 of 10 for a team is the same as picking the 2 to leave out, so ¹⁰C₈ = ¹⁰C₂ = 10 × 9 ÷ 2 = 45. Count the smaller side. And a chance can be counted this way too: the pairs you want, out of all the pairs.","more":"The trick: Count as if order mattered, then divide by r! — the number of orders each group was counted in.","cta":"See why","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/combinations|learn"},"moral-combinations-beat5":{"id":"moral-combinations-beat5","kind":"moral","src":"story:combinations#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “Picking the quiz team”","body":"Thirty-five teams. Count in order, then divide by the orders.","more":"The trick in the story: Count as if order mattered, then divide by r! — the number of orders each group was counted in.","cta":"Read the story","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/combinations|story|5"},"algebra-combinations-alg":{"id":"algebra-combinations-alg","kind":"algebra","src":"stop:combinations#alg","title":"The algebra behind “Combinations: order doesn't matter”","body":"ⁿCᵣ = ⁿPᵣ ÷ r! = n! ÷ (r! × (n − r)!) · ⁿCᵣ = ⁿCₙ₋ᵣ","more":"In words: Count as if order mattered, then divide by r! — the number of orders each group was counted in.","cta":"See why","where":"The Data Carnival · Level 10","level":10,"route":"#/stop/combinations|learn"},"try-combinations-L10":{"id":"try-combinations-L10","kind":"try","level":10,"src":"try:combinations@10/3#0","title":"Combinations: order doesn't matter — your turn","where":"The Data Carnival · Level 10","route":"#/stop/combinations|drill","cta":"Practise this stop","play":{"q":"How many different teams of 3 can be picked from 7 players?","opts":["35","6","210"],"after":"Count as if order mattered, then divide by r! — the number of orders each group was counted in.","show":[2,0,1]}},"hook-heads-and-legs-hook":{"id":"hook-heads-and-legs-hook","kind":"hook","src":"stop:heads-and-legs#hook","title":"Can you? — Pretend they are all the same","body":"A farm has hens and goats: 12 heads and 34 legs. How many goats?","more":"The way in: Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.","cta":"Find out how","where":"The Strategy School · Level 10","level":10,"route":"#/stop/heads-and-legs|learn"},"worked-heads-and-legs-worked0":{"id":"worked-heads-and-legs-worked0","kind":"worked","src":"stop:heads-and-legs#worked0","title":"Worked out — Pretend they are all the same: Heads and legs","body":"A farm has hens (2 legs each) and goats (4 legs each): 12 heads and 34 legs altogether. How many goats are there?: If all 12 were hens: 12 × 2 → 24 · Still to explain: 34 − 24 → 10 · Each swap to a goat adds 4 − 2 legs → 2 · Swaps: 10 ÷ 2 → 5","more":"What is special here: Pretend they are all the kind with fewer legs; each swap adds the difference in legs.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/heads-and-legs|learn|0"},"worked-heads-and-legs-worked1":{"id":"worked-heads-and-legs-worked1","kind":"worked","src":"stop:heads-and-legs#worked1","title":"Worked out — Pretend they are all the same: Two kinds of coin","body":"Jai's jar has 15 coins. Some are 2s and the rest are 5s, and together they make 48. How many 5s are there?: If all 15 were 2s: 15 × 2 → 30 · Still to explain: 48 − 30 → 18 · Each swap to a 5 adds 5 − 2 → 3 · Swaps: 18 ÷ 3 → 6","more":"What is special here: Pretend they are all the smaller coin; each swap adds the difference in value.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/heads-and-legs|learn|1"},"worked-heads-and-legs-worked2":{"id":"worked-heads-and-legs-worked2","kind":"worked","src":"stop:heads-and-legs#worked2","title":"Worked out — Pretend they are all the same: Points won and lost","body":"A quiz has 20 questions. A right answer scores 5 points and a wrong answer loses 2. Zoe answered every question and scored 72. How many did Zoe get right?: If all 20 were right: 20 × 5 → 100 · Points short: 100 − 72 → 28 · Each wrong answer costs 5 + 2 → 7 · Wrong answers: 28 ÷ 7 → 4 · Right answers: 20 − 4 → 16","more":"What is special here: Pretend every answer was right; each wrong answer costs the points not won AND the points lost.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/heads-and-legs|learn|2"},"why-heads-and-legs-why2":{"id":"why-heads-and-legs-why2","kind":"why","src":"stop:heads-and-legs#why2","title":"Why “Pretend they are all the same” works","body":"The same trick works for coins (pretend they are all the small coin) and for quiz scores (pretend every answer was right — each wrong one costs the points you did not win AND the points you lost). Pretend, measure the gap, and divide by what one swap is worth.","more":"The trick: Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.","cta":"See why","where":"The Strategy School · Level 10","level":10,"route":"#/stop/heads-and-legs|learn"},"moral-heads-and-legs-beat5":{"id":"moral-heads-and-legs-beat5","kind":"moral","src":"story:heads-and-legs#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The farm count”","body":"Five swaps — five goats, seven hens. And 7 × 2 + 5 × 4 is 34.","more":"The trick in the story: Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.","cta":"Read the story","where":"The Strategy School · Level 10","level":10,"route":"#/stop/heads-and-legs|story|5"},"algebra-heads-and-legs-alg":{"id":"algebra-heads-and-legs-alg","kind":"algebra","src":"stop:heads-and-legs#alg","title":"The algebra behind “Pretend they are all the same”","body":"big kind = (total − count × small) ÷ (big − small)","more":"In words: Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.","cta":"See why","where":"The Strategy School · Level 10","level":10,"route":"#/stop/heads-and-legs|learn"},"try-heads-and-legs-L10":{"id":"try-heads-and-legs-L10","kind":"try","level":10,"src":"try:heads-and-legs@10/3#0","title":"Pretend they are all the same — your turn","where":"The Strategy School · Level 10","route":"#/stop/heads-and-legs|drill","cta":"Practise this stop","play":{"q":"A quiz has 25 questions. A right answer scores 5 points and a wrong answer loses 4. Asha answered every question and scored 116. How many did Asha get right?","opts":["24","9","125"],"after":"Pretend everything is the cheaper kind, see how far short you fall, and each swap to the other kind makes up the difference.","show":[2,1,0]}},"hook-age-problems-hook":{"id":"hook-age-problems-hook","kind":"hook","src":"stop:age-problems#hook","title":"Can you? — The gap never changes","body":"Dax is 11 and his uncle is 37. In how many years will his uncle be exactly twice as old?","more":"The way in: Two people always stay the same number of years apart — so pin the question to the gap, which never moves.","cta":"Find out how","where":"The Strategy School · Level 10","level":10,"route":"#/stop/age-problems|learn"},"worked-age-problems-worked0":{"id":"worked-age-problems-worked0","kind":"worked","src":"stop:age-problems#worked0","title":"Worked out — The gap never changes: When will the total be…?","body":"Maya is 7 and Hugo is 10. In how many years will their ages add up to 31?: Their ages add up to 7 + 10 now → 17 · Still to go: 31 − 17 → 14 · Each year, the total grows by → 2 · Years: 14 ÷ 2 → 7","more":"What is special here: The total of two ages grows by 2 every year — one year each.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/age-problems|learn|0"},"worked-age-problems-worked1":{"id":"worked-age-problems-worked1","kind":"worked","src":"stop:age-problems#worked1","title":"Worked out — The gap never changes: When will one be k times…?","body":"Dax is 11 and Dax's uncle is 37. In how many years will Dax's uncle be exactly twice as old as Dax?: The gap: 37 − 11 → 26 · It never changes. When it is twice, Dax's age equals the gap. So Dax is then → 26 · Years from now: 26 − 11 → 15","more":"What is special here: The gap stays fixed; when one is k times the other, the gap is (k − 1) lots of the younger age.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/age-problems|learn|1"},"worked-age-problems-worked2":{"id":"worked-age-problems-worked2","kind":"worked","src":"stop:age-problems#worked2","title":"Worked out — The gap never changes: How long ago was it?","body":"Priya is 12 and Priya's gran is 68. How many years ago was Priya's gran exactly 8 times as old as Priya?: The gap: 68 − 12 → 56 · It never changes. At 8 times, the gap is 7 lots of Priya's age. So Priya is then 56 ÷ 7 → 8 · Years ago: 12 − 8 → 4","more":"What is special here: Same gap, other direction: find how old the younger one was then, and count back to it.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/age-problems|learn|2"},"why-age-problems-why2":{"id":"why-age-problems-why2","kind":"why","src":"stop:age-problems#why2","title":"Why “The gap never changes” works","body":"Totals are different: they DO change, by 2 every year, because two people each get a year older. Whatever the question, ask first: what stays the same, and what changes by how much?","more":"The trick: Two people always stay the same number of years apart — so pin the question to the gap, which never moves.","cta":"See why","where":"The Strategy School · Level 10","level":10,"route":"#/stop/age-problems|learn"},"moral-age-problems-beat5":{"id":"moral-age-problems-beat5","kind":"moral","src":"story:age-problems#beat5","badge":{"id":"story","label":"A story"},"title":"Vesper, in “Twice as old”","body":"And 26 is this many years away.","more":"The trick in the story: Two people always stay the same number of years apart — so pin the question to the gap, which never moves.","cta":"Read the story","where":"The Strategy School · Level 10","level":10,"route":"#/stop/age-problems|story|5"},"algebra-age-problems-alg":{"id":"algebra-age-problems-alg","kind":"algebra","src":"stop:age-problems#alg","title":"The algebra behind “The gap never changes”","body":"older = k × younger ⇒ younger = gap ÷ (k − 1)","more":"In words: Two people always stay the same number of years apart — so pin the question to the gap, which never moves.","cta":"See why","where":"The Strategy School · Level 10","level":10,"route":"#/stop/age-problems|learn"},"try-age-problems-L10":{"id":"try-age-problems-L10","kind":"try","level":10,"src":"try:age-problems@10/3#0","title":"The gap never changes — your turn","where":"The Strategy School · Level 10","route":"#/stop/age-problems|drill","cta":"Practise this stop","play":{"q":"Zoe is 12 and Zoe's grandad is 57. How many years ago was Zoe's grandad exactly 6 times as old as Zoe?","opts":["3","2","1"],"after":"Two people always stay the same number of years apart — so pin the question to the gap, which never moves.","show":[1,0,2]}},"hook-simpler-case-hook":{"id":"hook-simpler-case-hook","kind":"hook","src":"stop:simpler-case#hook","title":"Can you? — Try a smaller one first","body":"A 60-metre fence has a post every 5 metres, at both ends too. Is it 12 posts? Try a tiny fence first.","more":"The way in: When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.","cta":"Find out how","where":"The Strategy School · Level 10","level":10,"route":"#/stop/simpler-case|learn"},"worked-simpler-case-worked0":{"id":"worked-simpler-case-worked0","kind":"worked","src":"stop:simpler-case#worked0","title":"Worked out — Try a smaller one first: Posts along a line","body":"A straight fence is 60 metres long. There is a post every 5 metres, with a post at each end. How many posts are there?: Tiny fence first: 10 metres. How many posts? → 3 · So posts = gaps + 1. Gaps in the real fence: 60 ÷ 5 → 12 · Posts: 12 + 1 → 13","more":"What is special here: A tiny fence shows it: posts are one more than the gaps.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/simpler-case|learn|0"},"worked-simpler-case-worked1":{"id":"worked-simpler-case-worked1","kind":"worked","src":"stop:simpler-case#worked1","title":"Worked out — Try a smaller one first: Cuts and pieces","body":"It takes 4 minutes to saw a log in two. How many minutes does it take to saw a log the same size into 6 pieces?: Tiny case first: how many cuts make 3 pieces? → 2 · So cuts = pieces − 1. Cuts for 6 pieces → 5 · Minutes: 5 × 4 → 20","more":"What is special here: Two cuts make three pieces — the cuts are one fewer than the pieces.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/simpler-case|learn|1"},"worked-simpler-case-worked2":{"id":"worked-simpler-case-worked2","kind":"worked","src":"stop:simpler-case#worked2","title":"Worked out — Try a smaller one first: All the way round","body":"The path all the way round a pond is 120 metres long. Trees are planted along it, 8 metres apart, all the way round. How many trees are there?: Tiny ring first: 3 gaps round a circle. How many trees? → 3 · In a ring, trees = gaps. Gaps: 120 ÷ 8 → 15","more":"What is special here: In a ring the last gap meets the first post, so trees and gaps are equal.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/simpler-case|learn|2"},"worked-simpler-case-worked3":{"id":"worked-simpler-case-worked3","kind":"worked","src":"stop:simpler-case#worked3","title":"Worked out — Try a smaller one first: Digits on the pages","body":"The pages of a book are numbered from 1 to 120. How many digits are printed altogether?: Pages 1 to 9: one digit each → 9 · Pages 10 to 99: 90 pages × 2 → 180 · Pages 100 to 120: 21 pages × 3 → 63 · Add: 9 + 180 + 63 → 252","more":"What is special here: Split where the rule changes: one-digit pages, two-digit pages, three-digit pages.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/simpler-case|learn|3"},"why-simpler-case-why2":{"id":"why-simpler-case-why2","kind":"why","src":"stop:simpler-case#why2","title":"Why “Try a smaller one first” works","body":"Some big counts are built from small ones. To count the digits on pages 1 to 120, do pages 1–9 (one digit each), then 10–99 (two each), then 100–120 (three each). Each small part is easy; the trick is cutting the problem where the rule changes.","more":"The trick: When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.","cta":"See why","where":"The Strategy School · Level 10","level":10,"route":"#/stop/simpler-case|learn"},"moral-simpler-case-beat5":{"id":"moral-simpler-case-beat5","kind":"moral","src":"story:simpler-case#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The rope fence”","body":"Thirteen posts. The tiny fence caught me.","more":"The trick in the story: When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.","cta":"Read the story","where":"The Strategy School · Level 10","level":10,"route":"#/stop/simpler-case|story|5"},"algebra-simpler-case-alg":{"id":"algebra-simpler-case-alg","kind":"algebra","src":"stop:simpler-case#alg","title":"The algebra behind “Try a smaller one first”","body":"posts in a line = gaps + 1 · posts in a ring = gaps · pieces = cuts + 1","more":"In words: When a problem is too big to picture, solve a tiny version you CAN draw, spot the rule, then use it on the big one.","cta":"See why","where":"The Strategy School · Level 10","level":10,"route":"#/stop/simpler-case|learn"},"hook-meeting-and-overtaking-hook":{"id":"hook-meeting-and-overtaking-hook","kind":"hook","src":"stop:meeting-and-overtaking#hook","title":"Can you? — Closing the gap","body":"Nova and Suki are 900 m apart and walk towards each other at 70 and 80 metres a minute. When do they meet?","more":"The way in: Watch the GAP, not the people: find how much it shrinks each minute, and divide.","cta":"Find out how","where":"The Strategy School · Level 10","level":10,"route":"#/stop/meeting-and-overtaking|learn"},"worked-meeting-and-overtaking-worked0":{"id":"worked-meeting-and-overtaking-worked0","kind":"worked","src":"stop:meeting-and-overtaking#worked0","title":"Worked out — Closing the gap: Towards each other: when?","body":"Nova and Suki are 900 metres apart and walk towards each other. Nova walks 70 metres a minute and Suki walks 80 metres a minute. After how many minutes do they meet?: Each minute the gap shrinks by 70 + 80 → 150 · Minutes: 900 ÷ 150 → 6","more":"What is special here: Both shrink the gap, so add the speeds.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/meeting-and-overtaking|learn|0"},"worked-meeting-and-overtaking-worked1":{"id":"worked-meeting-and-overtaking-worked1","kind":"worked","src":"stop:meeting-and-overtaking#worked1","title":"Worked out — Closing the gap: Towards each other: where?","body":"Chen and Ela are 600 metres apart and walk towards each other. Chen walks 60 metres a minute and Ela walks 90 metres a minute. How many metres from Chen's starting point do they meet?: Each minute the gap shrinks by 60 + 90 → 150 · Minutes: 600 ÷ 150 → 4 · Chen walks 4 × 60 → 240","more":"What is special here: Find when first, then how far one of them has walked by then.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/meeting-and-overtaking|learn|1"},"worked-meeting-and-overtaking-worked2":{"id":"worked-meeting-and-overtaking-worked2","kind":"worked","src":"stop:meeting-and-overtaking#worked2","title":"Worked out — Closing the gap: Catching up: when?","body":"Bea sets off along a path, walking 60 metres a minute. 7 minutes later Cal sets off from the same place, cycling 200 metres a minute. How many minutes after Cal sets off does Cal catch up with Bea?: Bea's head start: 7 × 60 → 420 · Each minute Cal gains 200 − 60 → 140 · Minutes to catch up: 420 ÷ 140 → 3","more":"What is special here: Same direction, so only the difference in speeds closes the gap.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/meeting-and-overtaking|learn|2"},"worked-meeting-and-overtaking-worked3":{"id":"worked-meeting-and-overtaking-worked3","kind":"worked","src":"stop:meeting-and-overtaking#worked3","title":"Worked out — Closing the gap: Catching up: where?","body":"Sami sets off along a path, walking 50 metres a minute. 4 minutes later Yusuf sets off from the same place, cycling 150 metres a minute. How many metres from the start does Yusuf catch up with Sami?: Sami's head start: 4 × 50 → 200 · Each minute Yusuf gains 150 − 50 → 100 · Minutes to catch up: 200 ÷ 100 → 2 · Yusuf cycles 2 × 150 → 300","more":"What is special here: Find when the chaser catches up, then how far the chaser has gone.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/meeting-and-overtaking|learn|3"},"why-meeting-and-overtaking-why2":{"id":"why-meeting-and-overtaking-why2","kind":"why","src":"stop:meeting-and-overtaking#why2","title":"Why “Closing the gap” works","body":"Once you know WHEN they meet, WHERE is easy: it is how far one of them has gone by then. Always check: the two distances should add up to the whole gap (meeting) or be equal (catching up).","more":"The trick: Watch the GAP, not the people: find how much it shrinks each minute, and divide.","cta":"See why","where":"The Strategy School · Level 10","level":10,"route":"#/stop/meeting-and-overtaking|learn"},"moral-meeting-and-overtaking-beat4":{"id":"moral-meeting-and-overtaking-beat4","kind":"moral","src":"story:meeting-and-overtaking#beat4","badge":{"id":"story","label":"A story"},"title":"Suki, in “Meeting at the bridge”","body":"So we meet where you have walked six minutes — at the little bridge.","more":"The trick in the story: Watch the GAP, not the people: find how much it shrinks each minute, and divide.","cta":"Read the story","where":"The Strategy School · Level 10","level":10,"route":"#/stop/meeting-and-overtaking|story|4"},"algebra-meeting-and-overtaking-alg":{"id":"algebra-meeting-and-overtaking-alg","kind":"algebra","src":"stop:meeting-and-overtaking#alg","title":"The algebra behind “Closing the gap”","body":"meet: time = gap ÷ (sum of speeds) · catch: time = head start ÷ (difference of speeds)","more":"In words: Watch the GAP, not the people: find how much it shrinks each minute, and divide.","cta":"See why","where":"The Strategy School · Level 10","level":10,"route":"#/stop/meeting-and-overtaking|learn"},"try-meeting-and-overtaking-L10":{"id":"try-meeting-and-overtaking-L10","kind":"try","level":10,"src":"try:meeting-and-overtaking@10/3#0","title":"Closing the gap — your turn","where":"The Strategy School · Level 10","route":"#/stop/meeting-and-overtaking|drill","cta":"Practise this stop","play":{"q":"Chen sets off along a path, walking 70 metres a minute. 12 minutes later Zoe sets off from the same place, cycling 110 metres a minute. How many metres from the start does Zoe catch up with Chen?","opts":["2310","840","2410"],"after":"Watch the GAP, not the people: find how much it shrinks each minute, and divide.","show":[2,0,1]}},"hook-units-digit-cycles-hook":{"id":"hook-units-digit-cycles-hook","kind":"hook","src":"stop:units-digit-cycles#hook","title":"Can you? — Ride the cycle","body":"7 multiplied by itself 50 times is a huge number. What is its last digit — without working it out?","more":"The way in: Last digits go round in a cycle. Find how long the cycle is, then see where your number lands in it.","cta":"Find out how","where":"The Strategy School · Level 10","level":10,"route":"#/stop/units-digit-cycles|learn"},"worked-units-digit-cycles-worked0":{"id":"worked-units-digit-cycles-worked0","kind":"worked","src":"stop:units-digit-cycles#worked0","title":"Worked out — Ride the cycle: A repeating pattern","body":"A row of digits repeats the same block for ever: 3, 8, 1, 6, 3, 8, 1, 6, 3, 8, 1, 6, … What is digit number 50 in the row?: How long is the block that repeats? → 4 · Place in the block: the remainder of 50 ÷ 4 (0 means the end) → 2 · So the digit is → 8","more":"What is special here: Find the block that repeats, then the remainder tells you the place in the block.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/units-digit-cycles|learn|0"},"worked-units-digit-cycles-worked1":{"id":"worked-units-digit-cycles-worked1","kind":"worked","src":"stop:units-digit-cycles#worked1","title":"Worked out — Ride the cycle: The last digit of a power","body":"7⁵⁰ means 50 lots of 7 multiplied together. What is its last digit?: Last digits of 7, 7², 7³, 7⁴, … repeat every → 4 · Place in the cycle: the remainder of 50 ÷ 4 (0 means the end) → 2 · So the last digit is → 9","more":"What is special here: The last digits of the powers repeat, so it is a pattern too — find its cycle first.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/units-digit-cycles|learn|1"},"worked-units-digit-cycles-worked2":{"id":"worked-units-digit-cycles-worked2","kind":"worked","src":"stop:units-digit-cycles#worked2","title":"Worked out — Ride the cycle: The last digit of a sum","body":"What is the last digit of 3²⁰²⁶ + 2³¹?: Last digit of 3²⁰²⁶ (its cycle is 4 long) → 9 · Last digit of 2³¹ (its cycle is 4 long) → 8 · 9 + 8, keeping only the last digit → 7","more":"What is special here: Find each last digit with its own cycle, add, and keep only the last digit.","cta":"Watch it step by step","where":"The Strategy School · Level 10","level":10,"route":"#/stop/units-digit-cycles|learn|2"},"why-units-digit-cycles-why2":{"id":"why-units-digit-cycles-why2","kind":"why","src":"stop:units-digit-cycles#why2","title":"Why “Ride the cycle” works","body":"Any repeating pattern works the same way — a necklace of beads, a row of digits that repeats. Find the block that repeats, count how long it is, and use the remainder to jump straight to the place you need. For a sum, find each last digit separately, add them, and keep only the last digit.","more":"The trick: Last digits go round in a cycle. Find how long the cycle is, then see where your number lands in it.","cta":"See why","where":"The Strategy School · Level 10","level":10,"route":"#/stop/units-digit-cycles|learn"},"moral-units-digit-cycles-beat5":{"id":"moral-units-digit-cycles-beat5","kind":"moral","src":"story:units-digit-cycles#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The last digit”","body":"The second ending in the cycle is the 9 of 49 — take away the tens.","more":"The trick in the story: Last digits go round in a cycle. Find how long the cycle is, then see where your number lands in it.","cta":"Read the story","where":"The Strategy School · Level 10","level":10,"route":"#/stop/units-digit-cycles|story|5"},"algebra-units-digit-cycles-alg":{"id":"algebra-units-digit-cycles-alg","kind":"algebra","src":"stop:units-digit-cycles#alg","title":"The algebra behind “Ride the cycle”","body":"nth item of a cycle of length L = item number (n ÷ L remainder), 0 meaning L","more":"In words: Last digits go round in a cycle. Find how long the cycle is, then see where your number lands in it.","cta":"See why","where":"The Strategy School · Level 10","level":10,"route":"#/stop/units-digit-cycles|learn"},"try-units-digit-cycles-L10":{"id":"try-units-digit-cycles-L10","kind":"try","level":10,"src":"try:units-digit-cycles@10/3#0","title":"Ride the cycle — your turn","where":"The Strategy School · Level 10","route":"#/stop/units-digit-cycles|drill","cta":"Practise this stop","play":{"q":"22¹⁴⁸⁶ means 1486 lots of 22 multiplied together. What is its last digit?","opts":["4","2","5"],"after":"Last digits go round in a cycle. Find how long the cycle is, then see where your number lands in it.","show":[0,1,2]}},"word-algebra":{"id":"word-algebra","kind":"word","src":"dictionary:algebra#def","title":"algebra","body":"Maths that uses letters to stand for numbers, so one rule can cover every case. For example: 2 + 9 = 9 + 2, and a + b = b + a for every a and b.","more":"Taught at: Letters for numbers.","where":"Set Island","route":"#/lib/dictionary|algebra","cta":"algebra in the Dictionary","level":10},"wordq-algebra":{"id":"wordq-algebra","kind":"wordq","src":"dictionary:algebra#ex","title":"Which maths word?","route":"#/lib/dictionary|algebra","cta":"Look it up","play":{"q":"Which word is this an example of? “2 + 9 = 9 + 2, and a + b = b + a for every a and b.”","opts":["algebra","direct proportion","coordinates"],"after":"algebra: Maths that uses letters to stand for numbers, so one rule can cover every case.","show":[2,0,1]},"level":10},"word-circle":{"id":"word-circle","kind":"word","src":"dictionary:circle#def","title":"circle","body":"A round flat shape where every point on the edge is the same distance from the centre. For example: Radius 3 cm: area about 3.14 × 3 × 3 = 28.26 cm².","more":"Taught at: Round the circle.","where":"Shape City","route":"#/lib/dictionary|circle","cta":"circle in the Dictionary","level":10},"wordq-circle":{"id":"wordq-circle","kind":"wordq","src":"dictionary:circle#ex","title":"Which maths word?","route":"#/lib/dictionary|circle","cta":"Look it up","play":{"q":"Which word is this an example of? “Radius 3 cm: area about 3.14 × 3 × 3 = 28.26 cm².”","opts":["circle","like terms","speed"],"after":"circle: A round flat shape where every point on the edge is the same distance from the centre.","show":[1,0,2]},"level":10},"word-circumference":{"id":"word-circumference","kind":"word","src":"dictionary:circumference#def","title":"circumference","body":"The distance all the way round a circle. For example: About 3.14 times the width: a 10 cm wheel is about 31.4 cm round.","more":"Taught at: Round the circle.","where":"Shape City","route":"#/lib/dictionary|circumference","cta":"circumference in the Dictionary","level":10},"wordq-circumference":{"id":"wordq-circumference","kind":"wordq","src":"dictionary:circumference#ex","title":"Which maths word?","route":"#/lib/dictionary|circumference","cta":"Look it up","play":{"q":"Which word is this an example of? “About 3.14 times the width: a 10 cm wheel is about 31.4 cm round.”","opts":["circumference","half","equation"],"after":"circumference: The distance all the way round a circle.","show":[0,2,1]},"level":10},"word-combination":{"id":"word-combination","kind":"word","src":"dictionary:combination#def","title":"combination","body":"A choice of things where the order does not count, so ABC and CBA are the same group. From n things, r of them: n! ÷ (r! × (n − r)!). For example: A team of 3 from 7 players: 7 × 6 × 5 ÷ 6 = 35.","more":"Taught at: Combinations: order doesn't matter.","where":"The Data Carnival","route":"#/lib/dictionary|combination","cta":"combination in the Dictionary","level":10},"wordq-combination":{"id":"wordq-combination","kind":"wordq","src":"dictionary:combination#ex","title":"Which maths word?","route":"#/lib/dictionary|combination","cta":"Look it up","play":{"q":"Which word is this an example of? “A team of 3 from 7 players: 7 × 6 × 5 ÷ 6 = 35.”","opts":["combination","triangular number","cuboid"],"after":"combination: A choice of things where the order does not count, so ABC and CBA are the same group. From n things, r of them: n! ÷ (r! × (n − r)!).","show":[2,0,1]},"level":10},"word-diameter":{"id":"word-diameter","kind":"word","src":"dictionary:diameter#def","title":"diameter","body":"The distance straight across a circle through its centre — two radii end to end. For example: Radius 4 cm → 8 cm across.","more":"Taught at: Round the circle.","where":"Shape City","route":"#/lib/dictionary|diameter","cta":"diameter in the Dictionary","level":10},"wordq-diameter":{"id":"wordq-diameter","kind":"wordq","src":"dictionary:diameter#ex","title":"Which maths word?","route":"#/lib/dictionary|diameter","cta":"Look it up","play":{"q":"Which word is this an example of? “Radius 4 cm → 8 cm across.”","opts":["diameter","even","unlikely"],"after":"diameter: The distance straight across a circle through its centre — two radii end to end.","show":[1,2,0]},"level":10},"word-discount":{"id":"word-discount","kind":"word","src":"dictionary:discount#def","title":"discount","body":"An amount taken off a price. For example: 20% off £40 saves £8, so you pay £32.","more":"Taught at: Sales and rises.","where":"The Decimal Dock","route":"#/lib/dictionary|discount","cta":"discount in the Dictionary","level":10},"wordq-discount":{"id":"wordq-discount","kind":"wordq","src":"dictionary:discount#ex","title":"Which maths word?","route":"#/lib/dictionary|discount","cta":"Look it up","play":{"q":"Which word is this an example of? “20% off £40 saves £8, so you pay £32.”","opts":["discount","volume","numerator"],"after":"discount: An amount taken off a price.","show":[0,2,1]},"level":10},"word-equation":{"id":"word-equation","kind":"word","src":"dictionary:equation#def","title":"equation","body":"A statement that two things are equal, with an = sign between them. For example: 2x + 1 = 9.","more":"Taught at: Solving equations on a balance.","where":"Set Island","route":"#/lib/dictionary|equation","cta":"equation in the Dictionary","level":10},"wordq-equation":{"id":"wordq-equation","kind":"wordq","src":"dictionary:equation#ex","title":"Which maths word?","route":"#/lib/dictionary|equation","cta":"Look it up","play":{"q":"Which word is this an example of? “2x + 1 = 9.”","opts":["equation","quotient","perpendicular height"],"after":"equation: A statement that two things are equal, with an = sign between them.","show":[1,2,0]},"level":10},"word-expression":{"id":"word-expression","kind":"word","src":"dictionary:expression#def","title":"expression","body":"Numbers and letters joined by operations, with no equals sign. For example: 3x + 2 (while 3x + 2 = 11 is an equation).","more":"Taught at: Collecting like terms · Letters for numbers.","where":"Set Island","route":"#/lib/dictionary|expression","cta":"expression in the Dictionary","level":10},"wordq-expression":{"id":"wordq-expression","kind":"wordq","src":"dictionary:expression#ex","title":"Which maths word?","route":"#/lib/dictionary|expression","cta":"Look it up","play":{"q":"Which word is this an example of? “3x + 2 (while 3x + 2 = 11 is an equation).”","opts":["expression","line of symmetry","hexagon"],"after":"expression: Numbers and letters joined by operations, with no equals sign.","show":[1,0,2]},"level":10},"word-formula":{"id":"word-formula","kind":"word","src":"dictionary:formula#def","title":"formula","body":"A rule written with letters that links quantities together. For example: A = l × w: a 5 by 3 rectangle has A = 15.","more":"Taught at: Letters for numbers · Area of a rectangle.","where":"Set Island","route":"#/lib/dictionary|formula","cta":"formula in the Dictionary","level":10},"wordq-formula":{"id":"wordq-formula","kind":"wordq","src":"dictionary:formula#ex","title":"Which maths word?","route":"#/lib/dictionary|formula","cta":"Look it up","play":{"q":"Which word is this an example of? “A = l × w: a 5 by 3 rectangle has A = 15.”","opts":["formula","brackets","vertically opposite angles"],"after":"formula: A rule written with letters that links quantities together.","show":[0,1,2]},"level":10},"word-gradient":{"id":"word-gradient","kind":"word","src":"dictionary:gradient#def","title":"gradient","body":"How steep a line is: how far it rises for each one step across. For example: y = 3x + 1 rises 3 for every 1 across.","more":"Taught at: Straight-line graphs.","where":"Set Island","route":"#/lib/dictionary|gradient","cta":"gradient in the Dictionary","level":10},"wordq-gradient":{"id":"wordq-gradient","kind":"wordq","src":"dictionary:gradient#ex","title":"Which maths word?","route":"#/lib/dictionary|gradient","cta":"Look it up","play":{"q":"Which word is this an example of? “y = 3x + 1 rises 3 for every 1 across.”","opts":["gradient","cuboid","chance"],"after":"gradient: How steep a line is: how far it rises for each one step across.","show":[2,0,1]},"level":10},"word-index-laws":{"id":"word-index-laws","kind":"word","src":"dictionary:index laws#def","title":"index laws","body":"Rules for powers of the same number: add the little raised numbers when you multiply, take them away when you divide. For example: 2³ × 2⁴ = 2⁷ = 128.","more":"Taught at: The index laws.","where":"The Square Palace","route":"#/lib/dictionary|index laws","cta":"index laws in the Dictionary","level":10},"wordq-index-laws":{"id":"wordq-index-laws","kind":"wordq","src":"dictionary:index laws#ex","title":"Which maths word?","route":"#/lib/dictionary|index laws","cta":"Look it up","play":{"q":"Which word is this an example of? “2³ × 2⁴ = 2⁷ = 128.”","opts":["index laws","universal set","reciprocal"],"after":"index laws: Rules for powers of the same number: add the little raised numbers when you multiply, take them away when you divide.","show":[2,0,1]},"level":10},"word-intercept":{"id":"word-intercept","kind":"word","src":"dictionary:intercept#def","title":"intercept","body":"Where a line crosses the y-axis — the one that runs up and down. For example: y = 2x + 5 crosses it at (0, 5).","more":"Taught at: Straight-line graphs.","where":"Set Island","route":"#/lib/dictionary|intercept","cta":"intercept in the Dictionary","level":10},"wordq-intercept":{"id":"wordq-intercept","kind":"wordq","src":"dictionary:intercept#ex","title":"Which maths word?","route":"#/lib/dictionary|intercept","cta":"Look it up","play":{"q":"Which word is this an example of? “y = 2x + 5 crosses it at (0, 5).”","opts":["intercept","regular","sample space"],"after":"intercept: Where a line crosses the y-axis — the one that runs up and down.","show":[2,0,1]},"level":10},"word-intersection":{"id":"word-intersection","kind":"word","src":"dictionary:intersection#def","title":"intersection","body":"Only the things that are in both sets at once. Sign: ∩. For example: {1, 2} ∩ {2, 3} = {2}.","more":"Taught at: Union and intersection.","where":"Set Island","route":"#/lib/dictionary|intersection","cta":"intersection in the Dictionary","level":10},"word-linear":{"id":"word-linear","kind":"word","src":"dictionary:linear#def","title":"linear","body":"Making a straight line when you draw it, with no letter squared or higher. For example: y = 2x + 1.","more":"Taught at: Straight-line graphs.","where":"Set Island","route":"#/lib/dictionary|linear","cta":"linear in the Dictionary","level":10},"word-nth-term":{"id":"word-nth-term","kind":"word","src":"dictionary:nth term#def","title":"nth term","body":"A rule that gives any number in a sequence straight from its position, n. For example: 4n − 1 gives 3, 7, 11, 15, …; the 10th is 39.","more":"Taught at: The nth term.","where":"Set Island","route":"#/lib/dictionary|nth term","cta":"nth term in the Dictionary","level":10},"wordq-nth-term":{"id":"wordq-nth-term","kind":"wordq","src":"dictionary:nth term#ex","title":"Which maths word?","route":"#/lib/dictionary|nth term","cta":"Look it up","play":{"q":"Which word is this an example of? “4n − 1 gives 3, 7, 11, 15, …; the 10th is 39.”","opts":["nth term","multiplication","kilometre"],"after":"nth term: A rule that gives any number in a sequence straight from its position, n.","show":[1,2,0]},"level":10},"word-percentage-change":{"id":"word-percentage-change","kind":"word","src":"dictionary:percentage change#def","title":"percentage change","body":"How much something went up or down, as a part of what it started at, times 100. For example: From 50 to 60: a rise of 10, and 10 ÷ 50 × 100 = 20%.","more":"Taught at: Sales and rises.","where":"The Decimal Dock","route":"#/lib/dictionary|percentage change","cta":"percentage change in the Dictionary","level":10},"wordq-percentage-change":{"id":"wordq-percentage-change","kind":"wordq","src":"dictionary:percentage change#ex","title":"Which maths word?","route":"#/lib/dictionary|percentage change","cta":"Look it up","play":{"q":"Which word is this an example of? “From 50 to 60: a rise of 10, and 10 ÷ 50 × 100 = 20%.”","opts":["percentage change","scale factor","decimal point"],"after":"percentage change: How much something went up or down, as a part of what it started at, times 100.","show":[0,2,1]},"level":10},"word-permutation":{"id":"word-permutation","kind":"word","src":"dictionary:permutation#def","title":"permutation","body":"A choice of things where the order counts, so ABC and CBA are different. From n things, r in order: n! ÷ (n − r)!. For example: Gold, silver and bronze from 8 runners: 8 × 7 × 6 = 336.","more":"Taught at: Permutations: order matters.","where":"The Data Carnival","route":"#/lib/dictionary|permutation","cta":"permutation in the Dictionary","level":10},"wordq-permutation":{"id":"wordq-permutation","kind":"wordq","src":"dictionary:permutation#ex","title":"Which maths word?","route":"#/lib/dictionary|permutation","cta":"Look it up","play":{"q":"Which word is this an example of? “Gold, silver and bronze from 8 runners: 8 × 7 × 6 = 336.”","opts":["permutation","angles round a point","term-to-term rule"],"after":"permutation: A choice of things where the order counts, so ABC and CBA are different. From n things, r in order: n! ÷ (n − r)!.","show":[1,0,2]},"level":10},"word-pi":{"id":"word-pi","kind":"word","src":"dictionary:pi#def","title":"pi","body":"The number you get by dividing any circle’s distance round by its distance across — about 3.14. Sign: π. For example: C = π × d: 10 cm across gives about 31.4 cm round.","more":"Taught at: Round the circle.","where":"Shape City","route":"#/lib/dictionary|pi","cta":"pi in the Dictionary","level":10},"word-proportion":{"id":"word-proportion","kind":"word","src":"dictionary:proportion#def","title":"proportion","body":"A part compared with the whole — or two amounts that grow and shrink together at the same rate. For example: 3 sweets out of 12 is a quarter.","more":"Taught at: Find one, then scale · Ratio: simplify and share.","where":"The Decimal Dock","route":"#/lib/dictionary|proportion","cta":"proportion in the Dictionary","level":10},"wordq-proportion":{"id":"wordq-proportion","kind":"wordq","src":"dictionary:proportion#ex","title":"Which maths word?","route":"#/lib/dictionary|proportion","cta":"Look it up","play":{"q":"Which word is this an example of? “3 sweets out of 12 is a quarter.”","opts":["proportion","set","diagonal"],"after":"proportion: A part compared with the whole — or two amounts that grow and shrink together at the same rate.","show":[1,2,0]},"level":10},"word-radius":{"id":"word-radius","kind":"word","src":"dictionary:radius#def","title":"radius","body":"The distance from the centre of a circle out to its edge. Plural: radii. For example: A circle 10 cm across has one of 5 cm.","more":"Taught at: Round the circle.","where":"Shape City","route":"#/lib/dictionary|radius","cta":"radius in the Dictionary","level":10},"wordq-radius":{"id":"wordq-radius","kind":"wordq","src":"dictionary:radius#ex","title":"Which maths word?","route":"#/lib/dictionary|radius","cta":"Look it up","play":{"q":"Which word is this an example of? “A circle 10 cm across has one of 5 cm.”","opts":["radius","arrangement","function machine"],"after":"radius: The distance from the centre of a circle out to its edge. Plural: radii.","show":[0,1,2]},"level":10},"word-ratio":{"id":"word-ratio","kind":"word","src":"dictionary:ratio#def","title":"ratio","body":"A way of comparing amounts, written with a colon, like 2 : 3. For example: Red to blue 2 : 3 means 2 red for every 3 blue.","more":"Taught at: Ratio: simplify and share.","where":"The Decimal Dock","route":"#/lib/dictionary|ratio","cta":"ratio in the Dictionary","level":10},"wordq-ratio":{"id":"wordq-ratio","kind":"wordq","src":"dictionary:ratio#ex","title":"Which maths word?","route":"#/lib/dictionary|ratio","cta":"Look it up","play":{"q":"Which word is this an example of? “Red to blue 2 : 3 means 2 red for every 3 blue.”","opts":["ratio","factorise","less than"],"after":"ratio: A way of comparing amounts, written with a colon, like 2 : 3.","show":[2,1,0]},"level":10},"word-reciprocal":{"id":"word-reciprocal","kind":"word","src":"dictionary:reciprocal#def","title":"reciprocal","body":"1 divided by a number — for a fraction, the fraction turned upside down. For example: For 3/4 it is 4/3, and 3/4 × 4/3 = 1.","more":"Taught at: Dividing by a fraction.","where":"The Fraction Bakery","route":"#/lib/dictionary|reciprocal","cta":"reciprocal in the Dictionary","level":10},"wordq-reciprocal":{"id":"wordq-reciprocal","kind":"wordq","src":"dictionary:reciprocal#ex","title":"Which maths word?","route":"#/lib/dictionary|reciprocal","cta":"Look it up","play":{"q":"Which word is this an example of? “For 3/4 it is 4/3, and 3/4 × 4/3 = 1.”","opts":["reciprocal","protractor","whole number"],"after":"reciprocal: 1 divided by a number — for a fraction, the fraction turned upside down.","show":[2,0,1]},"level":10},"word-scale":{"id":"word-scale","kind":"word","src":"dictionary:scale#def","title":"scale","body":"A ratio that tells you how lengths on a map or drawing compare with the real ones. For example: 1 : 100 means 1 cm on paper is 1 m for real.","more":"Taught at: Ratio: simplify and share.","where":"The Decimal Dock","route":"#/lib/dictionary|scale","cta":"scale in the Dictionary","level":10},"wordq-scale":{"id":"wordq-scale","kind":"wordq","src":"dictionary:scale#ex","title":"Which maths word?","route":"#/lib/dictionary|scale","cta":"Look it up","play":{"q":"Which word is this an example of? “1 : 100 means 1 cm on paper is 1 m for real.”","opts":["scale","prime number","simplify"],"after":"scale: A ratio that tells you how lengths on a map or drawing compare with the real ones.","show":[0,2,1]},"level":10},"word-sector":{"id":"word-sector","kind":"word","src":"dictionary:sector#def","title":"sector","body":"A slice of a circle between two radii, like a slice of pie. For example: A quarter-circle has a 90° angle at the centre.","more":"Taught at: Round the circle.","where":"Shape City","route":"#/lib/dictionary|sector","cta":"sector in the Dictionary","level":10},"wordq-sector":{"id":"wordq-sector","kind":"wordq","src":"dictionary:sector#ex","title":"Which maths word?","route":"#/lib/dictionary|sector","cta":"Look it up","play":{"q":"Which word is this an example of? “A quarter-circle has a 90° angle at the centre.”","opts":["sector","volume","change"],"after":"sector: A slice of a circle between two radii, like a slice of pie.","show":[2,0,1]},"level":10},"word-sequence":{"id":"word-sequence","kind":"word","src":"dictionary:sequence#def","title":"sequence","body":"A list of numbers that follows a rule. For example: 3, 7, 11, 15, … goes up in 4s.","more":"Taught at: The nth term.","where":"Set Island","route":"#/lib/dictionary|sequence","cta":"sequence in the Dictionary","level":10},"wordq-sequence":{"id":"wordq-sequence","kind":"wordq","src":"dictionary:sequence#ex","title":"Which maths word?","route":"#/lib/dictionary|sequence","cta":"Look it up","play":{"q":"Which word is this an example of? “3, 7, 11, 15, … goes up in 4s.”","opts":["sequence","outlier","nikhilam"],"after":"sequence: A list of numbers that follows a rule.","show":[2,0,1]},"level":10},"word-share-in-a-ratio":{"id":"word-share-in-a-ratio","kind":"word","src":"dictionary:share in a ratio#def","title":"share in a ratio","body":"Split an amount into unequal parts: add the parts of the ratio, find what one part is worth, then multiply. For example: £20 in 2 : 3 → 5 parts of £4 → £8 and £12.","more":"Taught at: Ratio: simplify and share.","where":"The Decimal Dock","route":"#/lib/dictionary|share in a ratio","cta":"share in a ratio in the Dictionary","level":10},"wordq-share-in-a-ratio":{"id":"wordq-share-in-a-ratio","kind":"wordq","src":"dictionary:share in a ratio#ex","title":"Which maths word?","route":"#/lib/dictionary|share in a ratio","cta":"Look it up","play":{"q":"Which word is this an example of? “£20 in 2 : 3 → 5 parts of £4 → £8 and £12.”","opts":["share in a ratio","factor pair","rectangle"],"after":"share in a ratio: Split an amount into unequal parts: add the parts of the ratio, find what one part is worth, then multiply.","show":[1,0,2]},"level":10},"word-solve":{"id":"word-solve","kind":"word","src":"dictionary:solve#def","title":"solve","body":"Find the value that makes an equation true. For example: 2x + 1 = 9 → 2x = 8 → x = 4.","more":"Taught at: Solving equations on a balance.","where":"Set Island","route":"#/lib/dictionary|solve","cta":"solve in the Dictionary","level":10},"wordq-solve":{"id":"wordq-solve","kind":"wordq","src":"dictionary:solve#ex","title":"Which maths word?","route":"#/lib/dictionary|solve","cta":"Look it up","play":{"q":"Which word is this an example of? “2x + 1 = 9 → 2x = 8 → x = 4.”","opts":["solve","analogue clock","vertex"],"after":"solve: Find the value that makes an equation true.","show":[0,2,1]},"level":10},"word-subset":{"id":"word-subset","kind":"word","src":"dictionary:subset#def","title":"subset","body":"A set made only from things that are in another set. For example: {1, 2} is one of {1, 2, 3}.","more":"Taught at: How many subsets?.","where":"Set Island","route":"#/lib/dictionary|subset","cta":"subset in the Dictionary","level":10},"word-substitute":{"id":"word-substitute","kind":"word","src":"dictionary:substitute#def","title":"substitute","body":"Put a number in place of a letter. For example: If a = 3, then 4a + 1 = 4 × 3 + 1 = 13.","more":"Taught at: Letters for numbers.","where":"Set Island","route":"#/lib/dictionary|substitute","cta":"substitute in the Dictionary","level":10},"wordq-substitute":{"id":"wordq-substitute","kind":"wordq","src":"dictionary:substitute#ex","title":"Which maths word?","route":"#/lib/dictionary|substitute","cta":"Look it up","play":{"q":"Which word is this an example of? “If a = 3, then 4a + 1 = 4 × 3 + 1 = 13.”","opts":["substitute","greater than","empty set"],"after":"substitute: Put a number in place of a letter.","show":[1,0,2]},"level":10},"word-term":{"id":"word-term","kind":"word","src":"dictionary:term#def","title":"term","body":"One number in a sequence, or one part of an expression between the + and − signs. For example: 3x + 5y − 2 has three.","more":"Taught at: Collecting like terms · The nth term.","where":"Set Island","route":"#/lib/dictionary|term","cta":"term in the Dictionary","level":10},"wordq-term":{"id":"wordq-term","kind":"wordq","src":"dictionary:term#ex","title":"Which maths word?","route":"#/lib/dictionary|term","cta":"Look it up","play":{"q":"Which word is this an example of? “3x + 5y − 2 has three.”","opts":["term","parallelogram","metric"],"after":"term: One number in a sequence, or one part of an expression between the + and − signs.","show":[0,1,2]},"level":10},"word-union":{"id":"word-union","kind":"word","src":"dictionary:union#def","title":"union","body":"Everything that is in either set, or in both. Sign: ∪. For example: {1, 2} ∪ {2, 3} = {1, 2, 3}.","more":"Taught at: Union and intersection.","where":"Set Island","route":"#/lib/dictionary|union","cta":"union in the Dictionary","level":10},"word-universal-set":{"id":"word-universal-set","kind":"word","src":"dictionary:universal set#def","title":"universal set","body":"Everything being talked about — the box drawn round a Venn diagram. For example: Sorting 1 to 10, it is {1, 2, …, 10}.","more":"Taught at: Venn diagrams that count.","where":"Set Island","route":"#/lib/dictionary|universal set","cta":"universal set in the Dictionary","level":10},"wordq-universal-set":{"id":"wordq-universal-set","kind":"wordq","src":"dictionary:universal set#ex","title":"Which maths word?","route":"#/lib/dictionary|universal set","cta":"Look it up","play":{"q":"Which word is this an example of? “Sorting 1 to 10, it is {1, 2, …, 10}.”","opts":["universal set","sum","number bond"],"after":"universal set: Everything being talked about — the box drawn round a Venn diagram.","show":[2,1,0]},"level":10},"word-unknown":{"id":"word-unknown","kind":"word","src":"dictionary:unknown#def","title":"unknown","body":"A letter standing for one number you are trying to find. For example: In x + 4 = 11, x is 7.","more":"Taught at: Solving equations on a balance.","where":"Set Island","route":"#/lib/dictionary|unknown","cta":"unknown in the Dictionary","level":10},"wordq-unknown":{"id":"wordq-unknown","kind":"wordq","src":"dictionary:unknown#ex","title":"Which maths word?","route":"#/lib/dictionary|unknown","cta":"Look it up","play":{"q":"Which word is this an example of? “In x + 4 = 11, x is 7.”","opts":["unknown","decimal place","clockwise"],"after":"unknown: A letter standing for one number you are trying to find.","show":[2,1,0]},"level":10},"word-variable":{"id":"word-variable","kind":"word","src":"dictionary:variable#def","title":"variable","body":"A letter that stands for a number which can change. For example: In y = 2x + 1, x and y can both take many values.","more":"Taught at: Letters for numbers · Straight-line graphs.","where":"Set Island","route":"#/lib/dictionary|variable","cta":"variable in the Dictionary","level":10},"wordq-variable":{"id":"wordq-variable","kind":"wordq","src":"dictionary:variable#ex","title":"Which maths word?","route":"#/lib/dictionary|variable","cta":"Look it up","play":{"q":"Which word is this an example of? “In y = 2x + 1, x and y can both take many values.”","opts":["variable","cuboid","chance"],"after":"variable: A letter that stands for a number which can change.","show":[0,2,1]},"level":10},"word-venn-diagram":{"id":"word-venn-diagram","kind":"word","src":"dictionary:Venn diagram#def","title":"Venn diagram","body":"Overlapping circles that sort things into groups; the overlap holds what belongs to both. For example: 5 have only a cat, 4 only a dog, 3 have both.","more":"Taught at: Venn diagrams that count.","where":"Set Island","route":"#/lib/dictionary|Venn diagram","cta":"Venn diagram in the Dictionary","level":10},"wordq-venn-diagram":{"id":"wordq-venn-diagram","kind":"wordq","src":"dictionary:Venn diagram#ex","title":"Which maths word?","route":"#/lib/dictionary|Venn diagram","cta":"Look it up","play":{"q":"Which word is this an example of? “5 have only a cat, 4 only a dog, 3 have both.”","opts":["Venn diagram","vertically opposite angles","even"],"after":"Venn diagram: Overlapping circles that sort things into groups; the overlap holds what belongs to both.","show":[1,2,0]},"level":10},"formula-circumference":{"id":"formula-circumference","kind":"formula","src":"formula:circumference","title":"Circumference of a circle","body":"C = π × d = 2 × π × r. Unroll any circle: it is just over three diameters long.","more":"Taught at: Round the circle.","where":"Shape City","route":"#/lib/formulas|circumference","cta":"Circumference of a circle in the Formula Book","play":{"q":"Circumference of a circle: A circle 10 cm across (use π = 3.14).","opts":["31.4","13.1","13.4"],"after":"C = 3.14 × 10 · = 31.4 cm","show":[2,0,1]},"level":10},"formula-why-circumference-0":{"id":"formula-why-circumference-0","kind":"formula-why","src":"formula:circumference#why0","title":"Why C = π × d = 2 × π × r","body":"Every circle, big or small, is the same shape — only its size changes. So the distance round it is always the same number of times the distance across.","more":"The card: Circumference of a circle — Unroll any circle: it is just over three diameters long.","route":"#/lib/formulas|circumference","cta":"Circumference of a circle in the Formula Book","level":10},"formula-why-circumference-1":{"id":"formula-why-circumference-1","kind":"formula-why","src":"formula:circumference#why1","title":"Why C = π × d = 2 × π × r","body":"That number is π, a little more than 3: about 3.14. Wrap a string round a tin and it goes just over three times its width. So C = π × d — or 2 × π × r, because the diameter is two radii.","more":"The card: Circumference of a circle — Unroll any circle: it is just over three diameters long.","route":"#/lib/formulas|circumference","cta":"Circumference of a circle in the Formula Book","level":10},"formula-story-circumference":{"id":"formula-story-circumference","kind":"formula-story","src":"formula:circumference#story","badge":{"id":"story","label":"A story"},"title":"The bicycle wheel","body":"Pip’s bike wheel is 60 cm across. How far does the bike roll in one turn of the wheel? — with Theo and Pip.","art":"art/s-city.webp","route":"#/lib/formulas|circumference","cta":"Circumference of a circle in the Formula Book","level":10},"formula-try-circumference":{"id":"formula-try-circumference","kind":"formula-try","src":"formula:circumference#gen0","title":"Circumference of a circle — your turn","route":"#/lib/formulas|circumference","cta":"Circumference of a circle in the Formula Book","play":{"q":"Distance round a circle 20 cm across (use π = 3.14; in cm) = ?","opts":["62.8","23.1","68.2"],"after":"C = π × d = 2 × π × r","show":[2,0,1]},"level":10},"formula-area-circle":{"id":"formula-area-circle","kind":"formula","src":"formula:area-circle","title":"Area of a circle","body":"A = π × r². Slices laid top-to-tail make a near-rectangle, r tall and π × r long.","more":"Taught at: Round the circle.","where":"Shape City","route":"#/lib/formulas|area-circle","cta":"Area of a circle in the Formula Book","play":{"q":"Area of a circle: A circle with radius 5 cm (use π = 3.14).","opts":["78.5","68.5","314.3"],"after":"r² = 5 × 5 = 25 · A = 3.14 × 25 = 78.5 cm²","show":[0,2,1]},"level":10},"formula-why-area-circle-0":{"id":"formula-why-area-circle-0","kind":"formula-why","src":"formula:area-circle#why0","title":"Why A = π × r²","body":"Cut a circle into many thin slices, like a pizza, and lay them in a row, pointing up and down in turn. They make a shape that is nearly a rectangle — and the thinner the slices, the straighter it gets.","more":"The card: Area of a circle — Slices laid top-to-tail make a near-rectangle, r tall and π × r long.","route":"#/lib/formulas|area-circle","cta":"Area of a circle in the Formula Book","level":10},"formula-why-area-circle-1":{"id":"formula-why-area-circle-1","kind":"formula-why","src":"formula:area-circle#why1","title":"Why A = π × r²","body":"Its height is the radius r. Its length is half the way round the circle, π × r. So the area is π × r × r, written π r².","more":"The card: Area of a circle — Slices laid top-to-tail make a near-rectangle, r tall and π × r long.","route":"#/lib/formulas|area-circle","cta":"Area of a circle in the Formula Book","level":10},"formula-story-area-circle":{"id":"formula-story-area-circle","kind":"formula-story","src":"formula:area-circle#story","badge":{"id":"story","label":"A story"},"title":"The round pond","body":"The park pond is a circle with a radius of 10 metres. Rafi wants its area for a school project. — with Mira and Rafi.","art":"art/s-pond.webp","route":"#/lib/formulas|area-circle","cta":"Area of a circle in the Formula Book","level":10},"formula-try-area-circle":{"id":"formula-try-area-circle","kind":"formula-try","src":"formula:area-circle#gen0","title":"Area of a circle — your turn","route":"#/lib/formulas|area-circle","cta":"Area of a circle in the Formula Book","play":{"q":"Area of a circle with radius 3 cm (use π = 3.14; in cm²) = ?","opts":["28.26","12.42","82.26"],"after":"A = π × r²","show":[1,2,0]},"level":10},"formula-volume-cylinder":{"id":"formula-volume-cylinder","kind":"formula","src":"formula:volume-cylinder","title":"Volume of a cylinder","body":"V = π × r² × h. A circle, stacked up to height h.","more":"Taught at: Round the circle · Volume and surface area.","where":"Shape City","route":"#/lib/formulas|volume-cylinder","cta":"Volume of a cylinder in the Formula Book","play":{"q":"Volume of a cylinder: A tin with radius 5 cm and height 10 cm (use π = 3.14).","opts":["785","758","775"],"after":"end: 3.14 × 5 × 5 = 78.5 cm² · V = 78.5 × 10 = 785 cm³","show":[0,1,2]},"level":10},"formula-why-volume-cylinder-0":{"id":"formula-why-volume-cylinder-0","kind":"formula-why","src":"formula:volume-cylinder#why0","title":"Why V = π × r² × h","body":"A cylinder is a prism with a circle at each end, so the prism rule still works: area of the end × length.","more":"The card: Volume of a cylinder — A circle, stacked up to height h.","route":"#/lib/formulas|volume-cylinder","cta":"Volume of a cylinder in the Formula Book","level":10},"formula-why-volume-cylinder-1":{"id":"formula-why-volume-cylinder-1","kind":"formula-why","src":"formula:volume-cylinder#why1","title":"Why V = π × r² × h","body":"The end is a circle with area π × r², so V = π × r² × h. A tin twice as tall holds twice as much; a tin twice as wide holds four times as much, because the radius is squared.","more":"The card: Volume of a cylinder — A circle, stacked up to height h.","route":"#/lib/formulas|volume-cylinder","cta":"Volume of a cylinder in the Formula Book","level":10},"formula-story-volume-cylinder":{"id":"formula-story-volume-cylinder","kind":"formula-story","src":"formula:volume-cylinder#story","badge":{"id":"story","label":"A story"},"title":"The water tank","body":"A round water tank in the garden has a radius of 1 metre and stands 2 metres tall. — with Kwame and Nova.","art":"art/s-garden.webp","route":"#/lib/formulas|volume-cylinder","cta":"Volume of a cylinder in the Formula Book","level":10},"formula-try-volume-cylinder":{"id":"formula-try-volume-cylinder","kind":"formula-try","src":"formula:volume-cylinder#gen0","title":"Volume of a cylinder — your turn","route":"#/lib/formulas|volume-cylinder","cta":"Volume of a cylinder in the Formula Book","play":{"q":"Volume of a cylinder, radius 2 cm and height 18 cm (use π = 3.14; in cm³) = ?","opts":["226.08","75.14","30.56"],"after":"V = π × r² × h","show":[0,1,2]},"level":10},"formula-index-multiply":{"id":"formula-index-multiply","kind":"formula","src":"formula:index-multiply","title":"Multiplying powers","body":"aᵐ × aⁿ = aᵐ⁺ⁿ. Three 2s and two more 2s make a row of five 2s.","more":"Taught at: The index laws · Powers: the little number.","where":"The Square Palace","route":"#/lib/formulas|index-multiply","cta":"Multiplying powers in the Formula Book","play":{"q":"Multiplying powers: 2³ × 2⁴.","opts":["128","182","1280"],"after":"3 + 4 = 7, so 2⁷ · 2⁷ = 128","show":[1,2,0]},"level":10},"formula-why-index-multiply-0":{"id":"formula-why-index-multiply-0","kind":"formula-why","src":"formula:index-multiply#why0","title":"Why aᵐ × aⁿ = aᵐ⁺ⁿ","body":"2³ means three 2s multiplied together, and 2² means two more. Multiply them and you just have a longer row of 2s: 2 × 2 × 2 × 2 × 2.","more":"The card: Multiplying powers — Three 2s and two more 2s make a row of five 2s.","route":"#/lib/formulas|index-multiply","cta":"Multiplying powers in the Formula Book","level":10},"formula-why-index-multiply-1":{"id":"formula-why-index-multiply-1","kind":"formula-why","src":"formula:index-multiply#why1","title":"Why aᵐ × aⁿ = aᵐ⁺ⁿ","body":"Count the 2s: 3 + 2 = 5. So when the base is the same, multiplying powers adds the little numbers, and dividing takes them away: 2⁵ ÷ 2² = 2³, because two of the 2s cancel.","more":"The card: Multiplying powers — Three 2s and two more 2s make a row of five 2s.","route":"#/lib/formulas|index-multiply","cta":"Multiplying powers in the Formula Book","level":10},"formula-story-index-multiply":{"id":"formula-story-index-multiply","kind":"formula-story","src":"formula:index-multiply#story","badge":{"id":"story","label":"A story"},"title":"The folded paper","body":"Theo folds a sheet of paper in half 3 times. Kwame takes it and folds it in half 2 more times. How many layers thick is it now? — with Kwame and Theo.","art":"art/s-library.webp","route":"#/lib/formulas|index-multiply","cta":"Multiplying powers in the Formula Book","level":10},"formula-try-index-multiply":{"id":"formula-try-index-multiply","kind":"formula-try","src":"formula:index-multiply#gen0","title":"Multiplying powers — your turn","route":"#/lib/formulas|index-multiply","cta":"Multiplying powers in the Formula Book","play":{"q":"3¹ × 3³ is 3 to the power of what?","opts":["4","2","1"],"after":"aᵐ × aⁿ = aᵐ⁺ⁿ","show":[1,2,0]},"level":10},"formula-index-power":{"id":"formula-index-power","kind":"formula","src":"formula:index-power","title":"A power of a power","body":"(aᵐ)ⁿ = aᵐˣⁿ. Two copies of three 2s: six 2s.","more":"Taught at: The index laws.","where":"The Square Palace","route":"#/lib/formulas|index-power","cta":"A power of a power in the Formula Book","play":{"q":"A power of a power: (3²)³.","opts":["729","739","829"],"after":"2 × 3 = 6, so 3⁶ · 3⁶ = 729","show":[2,0,1]},"level":10},"formula-why-index-power-0":{"id":"formula-why-index-power-0","kind":"formula-why","src":"formula:index-power#why0","title":"Why (aᵐ)ⁿ = aᵐˣⁿ","body":"(2³)² means 2³ written down twice and multiplied: (2 × 2 × 2) × (2 × 2 × 2).","more":"The card: A power of a power — Two copies of three 2s: six 2s.","route":"#/lib/formulas|index-power","cta":"A power of a power in the Formula Book","level":10},"formula-why-index-power-1":{"id":"formula-why-index-power-1","kind":"formula-why","src":"formula:index-power#why1","title":"Why (aᵐ)ⁿ = aᵐˣⁿ","body":"That is 2 copies of 3 twos — 6 twos in all. So a power of a power multiplies the little numbers: (aᵐ)ⁿ = aᵐˣⁿ. And a⁰ = 1, because dividing aᵐ by itself takes all m away and leaves 1.","more":"The card: A power of a power — Two copies of three 2s: six 2s.","route":"#/lib/formulas|index-power","cta":"A power of a power in the Formula Book","level":10},"formula-story-index-power":{"id":"formula-story-index-power","kind":"formula-story","src":"formula:index-power#story","badge":{"id":"story","label":"A story"},"title":"The bakery trolley","body":"At the bakery a tray holds cakes in a square, 3 by 3. A trolley holds trays in a square too, 3 by 3. How many cakes on a full trolley? — with Rafi and Vesper.","art":"art/s-bakery.webp","route":"#/lib/formulas|index-power","cta":"A power of a power in the Formula Book","level":10},"formula-try-index-power":{"id":"formula-try-index-power","kind":"formula-try","src":"formula:index-power#gen0","title":"A power of a power — your turn","route":"#/lib/formulas|index-power","cta":"A power of a power in the Formula Book","play":{"q":"(3²)³ is 3 to the power of what?","opts":["6","1","4"],"after":"(aᵐ)ⁿ = aᵐˣⁿ","show":[1,2,0]},"level":10},"formula-nth-term":{"id":"formula-nth-term","kind":"formula","src":"formula:nth-term","title":"The nth term","body":"Tₙ = a + (n − 1) × d. Each step adds d; the nth term is n − 1 steps from the first.","more":"Taught at: The nth term.","where":"Set Island","route":"#/lib/formulas|nth-term","cta":"The nth term in the Formula Book","play":{"q":"The nth term: The 20th term of 5, 8, 11, 14, …","opts":["62","25","58"],"after":"19 steps of 3 = 57 · 5 + 57 = 62","show":[2,0,1]},"level":10},"formula-why-nth-term-0":{"id":"formula-why-nth-term-0","kind":"formula-why","src":"formula:nth-term#why0","title":"Why Tₙ = a + (n − 1) × d","body":"In a sequence that goes up by the same step d each time, the first number is a. To reach the 2nd you take 1 step; to reach the 3rd you take 2 steps; to reach the nth you take n − 1 steps.","more":"The card: The nth term — Each step adds d; the nth term is n − 1 steps from the first.","route":"#/lib/formulas|nth-term","cta":"The nth term in the Formula Book","level":10},"formula-why-nth-term-1":{"id":"formula-why-nth-term-1","kind":"formula-why","src":"formula:nth-term#why1","title":"Why Tₙ = a + (n − 1) × d","body":"So the nth term is a + (n − 1) × d. Tidied up, it is d × n + (a − d): for 5, 8, 11, 14, … that is 3n + 2. The number in front of n is always the step.","more":"The card: The nth term — Each step adds d; the nth term is n − 1 steps from the first.","route":"#/lib/formulas|nth-term","cta":"The nth term in the Formula Book","level":10},"formula-story-nth-term":{"id":"formula-story-nth-term","kind":"formula-story","src":"formula:nth-term#story","badge":{"id":"story","label":"A story"},"title":"The cup pyramid","body":"At the fair Dax lines up rows of cups: 4 in the first row, 7 in the second, 10 in the third. How many would row 25 need? — with Dax and Kwame.","art":"art/s-fair.webp","route":"#/lib/formulas|nth-term","cta":"The nth term in the Formula Book","level":10},"formula-try-nth-term":{"id":"formula-try-nth-term","kind":"formula-try","src":"formula:nth-term#gen0","title":"The nth term — your turn","route":"#/lib/formulas|nth-term","cta":"The nth term in the Formula Book","play":{"q":"6, 14, 22, 30, … What is term number 23?","opts":["182","172","82"],"after":"Tₙ = a + (n − 1) × d","show":[2,0,1]},"level":10},"formula-pythagoras":{"id":"formula-pythagoras","kind":"formula","src":"formula:pythagoras","title":"Pythagoras’ theorem","body":"a² + b² = c². The squares on the two short sides, 9 + 16, fill the square on the longest side, 25.","more":"Taught at: Pythagoras’ theorem · Kinds of triangle · Square roots · The next square up.","where":"The Lighthouse","route":"#/lib/formulas|pythagoras","cta":"Pythagoras’ theorem in the Formula Book","play":{"q":"Pythagoras’ theorem: Shorter sides 6 cm and 8 cm. The longest side?","opts":["10","20","11"],"after":"6² + 8² = 36 + 64 = 100 · c = √100 = 10 cm","show":[2,1,0]},"level":10},"formula-why-pythagoras-0":{"id":"formula-why-pythagoras-0","kind":"formula-why","src":"formula:pythagoras#why0","title":"Why a² + b² = c²","body":"This card is for 13- and 14-year-olds. In a right-angled triangle, build a square on each side. The two squares on the shorter sides, a² and b², together have exactly the area of the square on the longest side, c².","more":"The card: Pythagoras’ theorem — The squares on the two short sides, 9 + 16, fill the square on the longest side, 25.","route":"#/lib/formulas|pythagoras","cta":"Pythagoras’ theorem in the Formula Book","level":10},"formula-story-pythagoras":{"id":"formula-story-pythagoras","kind":"formula-story","src":"formula:pythagoras#story","badge":{"id":"story","label":"A story"},"title":"The shortcut across the park","body":"Dax walks 30 m along one edge of a rectangular park, then 40 m up the side. Vesper cuts straight across the grass. How much shorter is her path? — with Vesper and Dax.","art":"art/s-city.webp","route":"#/lib/formulas|pythagoras","cta":"Pythagoras’ theorem in the Formula Book","level":10},"formula-try-pythagoras":{"id":"formula-try-pythagoras","kind":"formula-try","src":"formula:pythagoras#gen0","title":"Pythagoras’ theorem — your turn","route":"#/lib/formulas|pythagoras","cta":"Pythagoras’ theorem in the Formula Book","play":{"q":"A right-angled triangle has a longest side of 5 cm and one shorter side of 4 cm. The other shorter side (in cm)?","opts":["3","2","4"],"after":"a² + b² = c²","show":[2,0,1]},"level":10},"formula-subsets":{"id":"formula-subsets","kind":"formula","src":"formula:subsets","title":"How many subsets","body":"subsets of n things = 2ⁿ. Each thing is in or out: every new thing doubles the ways.","more":"Taught at: How many subsets?.","where":"Set Island","route":"#/lib/formulas|subsets","cta":"How many subsets in the Formula Book","play":{"q":"How many subsets: A set of 3 things: {a, b, c}.","opts":["8","14","10"],"after":"2 × 2 × 2 = 8 · { }, {a}, {b}, {c}, {a,b}, {a,c}, {b,c}, {a,b,c}: 8","show":[1,0,2]},"level":10},"formula-why-subsets-0":{"id":"formula-why-subsets-0","kind":"formula-why","src":"formula:subsets#why0","title":"Why subsets of n things = 2ⁿ","body":"To make a subset, go through the things one at a time and decide: in, or out? Each thing doubles the number of ways, because every choice so far can go either way for the next thing.","more":"The card: How many subsets — Each thing is in or out: every new thing doubles the ways.","route":"#/lib/formulas|subsets","cta":"How many subsets in the Formula Book","level":10},"formula-why-subsets-1":{"id":"formula-why-subsets-1","kind":"formula-why","src":"formula:subsets#why1","title":"Why subsets of n things = 2ⁿ","body":"With n things that is 2 × 2 × … × 2, n times: 2ⁿ. The count includes the empty set (everything out) and the whole set (everything in).","more":"The card: How many subsets — Each thing is in or out: every new thing doubles the ways.","route":"#/lib/formulas|subsets","cta":"How many subsets in the Formula Book","level":10},"formula-story-subsets":{"id":"formula-story-subsets","kind":"formula-story","src":"formula:subsets#story","badge":{"id":"story","label":"A story"},"title":"Pizza toppings","body":"Nova’s pizza has 4 toppings to choose from. You can have any of them, all of them, or none. How many different pizzas is that? — with Ines and Nova.","art":"art/s-kitchen.webp","route":"#/lib/formulas|subsets","cta":"How many subsets in the Formula Book","level":10},"formula-try-subsets":{"id":"formula-try-subsets","kind":"formula-try","src":"formula:subsets#gen0","title":"How many subsets — your turn","route":"#/lib/formulas|subsets","cta":"How many subsets in the Formula Book","play":{"q":"A set has 6 things in it. How many subsets does it have, counting the empty set and the whole set?","opts":["64","54","46"],"after":"subsets of n things = 2ⁿ","show":[1,2,0]},"level":10},"formula-percent-change":{"id":"formula-percent-change","kind":"formula","src":"formula:percent-change","title":"Percentage change","body":"% change = change ÷ original × 100. Compare the change with where it started.","more":"Taught at: Sales and rises.","where":"The Decimal Dock","route":"#/lib/formulas|percent-change","cta":"Percentage change in the Formula Book","play":{"q":"Percentage change: A price goes from £50 to £60.","opts":["20","2","10"],"after":"change: 60 − 50 = 10 · 10 ÷ 50 × 100 = 20%","show":[0,2,1]},"level":10},"formula-why-percent-change-0":{"id":"formula-why-percent-change-0","kind":"formula-why","src":"formula:percent-change#why0","title":"Why % change = change ÷ original × 100","body":"A rise of 10 means a lot on a price of 20 and very little on a price of 1,000. So we compare the change with where it started: change ÷ original.","more":"The card: Percentage change — Compare the change with where it started.","route":"#/lib/formulas|percent-change","cta":"Percentage change in the Formula Book","level":10},"formula-why-percent-change-1":{"id":"formula-why-percent-change-1","kind":"formula-why","src":"formula:percent-change#why1","title":"Why % change = change ÷ original × 100","body":"That gives a fraction of the original; multiply by 100 to say it as a percentage. Always divide by the ORIGINAL amount, never the new one — the change is measured from the start.","more":"The card: Percentage change — Compare the change with where it started.","route":"#/lib/formulas|percent-change","cta":"Percentage change in the Formula Book","level":10},"formula-story-percent-change":{"id":"formula-story-percent-change","kind":"formula-story","src":"formula:percent-change#story","badge":{"id":"story","label":"A story"},"title":"The sunflower","body":"Rafi’s sunflower was 80 cm tall last week. Today it is 100 cm. By what percentage did it grow? — with Ines and Rafi.","art":"art/s-garden.webp","route":"#/lib/formulas|percent-change","cta":"Percentage change in the Formula Book","level":10},"formula-try-percent-change":{"id":"formula-try-percent-change","kind":"formula-try","src":"formula:percent-change#gen0","title":"Percentage change — your turn","route":"#/lib/formulas|percent-change","cta":"Percentage change in the Formula Book","play":{"q":"A price goes from £500 to £475. What is the percentage fall?","opts":["5","1","6"],"after":"% change = change ÷ original × 100","show":[2,1,0]},"level":10},"formula-why-ratio-share-1":{"id":"formula-why-ratio-share-1","kind":"formula-why","src":"formula:ratio-share#why1","title":"Why a : b of x → x ÷ (a + b) × a","body":"So cut the whole amount into a + b equal parts. One part is x ÷ (a + b); one share gets a of them and the other gets b. Check: the two shares must add back to x.","more":"The card: Sharing in a ratio — 2 : 3 means 5 equal parts; one share takes 2, the other 3.","route":"#/lib/formulas|ratio-share","cta":"Sharing in a ratio in the Formula Book","level":10},"formula-try-ratio-share":{"id":"formula-try-ratio-share","kind":"formula-try","src":"formula:ratio-share#gen0","title":"Sharing in a ratio — your turn","route":"#/lib/formulas|ratio-share","cta":"Sharing in a ratio in the Formula Book","play":{"q":"£32 is shared in the ratio 3 : 5. How much is the first share (in £)?","opts":["12","2","8"],"after":"a : b of x → x ÷ (a + b) × a","show":[0,2,1]},"level":10},"formula-combinations":{"id":"formula-combinations","kind":"formula","src":"formula:combinations","title":"Permutations and combinations","body":"ⁿPᵣ = n! ÷ (n − r)!  ·  ⁿCᵣ = n! ÷ (r! × (n − r)!). In order, one team of 3 is counted 3! = 6 times. Divide by 3! to count teams.","more":"Taught at: Permutations: order matters · Combinations: order doesn't matter.","where":"The Data Carnival","route":"#/lib/formulas|combinations","cta":"Permutations and combinations in the Formula Book","play":{"q":"Permutations and combinations: A team of 3 from 7 players.","opts":["35","53","350"],"after":"in order: 7 × 6 × 5 = 210 · each team is counted 3! = 6 times · 210 ÷ 6 = 35","show":[0,2,1]},"level":10},"formula-why-combinations-0":{"id":"formula-why-combinations-0","kind":"formula-why","src":"formula:combinations#why0","title":"Why ⁿPᵣ = n! ÷ (n − r)!  ·  ⁿCᵣ = n! ÷ (r! × (n − r)!)","body":"When order matters — gold, silver, bronze — fill the places one at a time: n choices, then n − 1, for r places. That is ⁿPᵣ = n × (n − 1) × … (r numbers), which is n! with the tail (n − r)! cancelled off.","more":"The card: Permutations and combinations — In order, one team of 3 is counted 3! = 6 times. Divide by 3! to count teams.","route":"#/lib/formulas|combinations","cta":"Permutations and combinations in the Formula Book","level":10},"formula-why-combinations-1":{"id":"formula-why-combinations-1","kind":"formula-why","src":"formula:combinations#why1","title":"Why ⁿPᵣ = n! ÷ (n − r)!  ·  ⁿCᵣ = n! ÷ (r! × (n − r)!)","body":"When order does not matter — a team, a handful of toppings — every group of r was counted once for each of its r! orders. So divide: ⁿCᵣ = ⁿPᵣ ÷ r!. A team of 3 from 7 is 7 × 6 × 5 = 210 in order, and 210 ÷ 6 = 35 teams.","more":"The card: Permutations and combinations — In order, one team of 3 is counted 3! = 6 times. Divide by 3! to count teams.","route":"#/lib/formulas|combinations","cta":"Permutations and combinations in the Formula Book","level":10},"formula-story-combinations":{"id":"formula-story-combinations","kind":"formula-story","src":"formula:combinations#story","badge":{"id":"story","label":"A story"},"title":"Cone or cup?","body":"The ice-cream shop has 5 flavours. Theo wants 2 different scoops stacked on a cone; Ines wants 2 in a cup. — with Ines and Theo.","art":"art/s-shop.webp","route":"#/lib/formulas|combinations","cta":"Permutations and combinations in the Formula Book","level":10},"formula-try-combinations":{"id":"formula-try-combinations","kind":"formula-try","src":"formula:combinations#gen0","title":"Permutations and combinations — your turn","route":"#/lib/formulas|combinations","cta":"Permutations and combinations in the Formula Book","play":{"q":"6 in the final. How many ways to choose gold, silver and bronze?","opts":["120","20","102"],"after":"ⁿPᵣ = n! ÷ (n − r)!  ·  ⁿCᵣ = n! ÷ (r! × (n − r)!)","show":[0,1,2]},"level":10},"stone-vedic-antyayor-2":{"src":"journey:vedic/antyayor#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|antyayor","cta":"Stone 9: When the last digits make ten","where":"The Vedic Maths Journey · stone 9 of 13","id":"stone-vedic-antyayor-2","kind":"stone-step","title":"When the last digits make ten (3 of 3)","body":"Why: (10n + b)(10n + 10 − b) = 100 × n(n + 1) + b(10 − b). Squares ending in 5 are the special case where both last digits are 5.","level":10},"stone-vedic-sankalana":{"src":"journey:vedic/sankalana#0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|sankalana","cta":"Stone 13: By adding and by subtracting","where":"The Vedic Maths Journey · stone 13 of 13","id":"stone-vedic-sankalana","kind":"stone","title":"By adding and by subtracting — Saṅkalana-vyavakalanābhyām","body":"Sometimes two equations have their numbers swapped: 5x + 3y = 21 and 3x + 5y = 19. Add them, and subtract them.","level":10},"stone-vedic-sankalana-1":{"src":"journey:vedic/sankalana#1","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|sankalana","cta":"Stone 13: By adding and by subtracting","where":"The Vedic Maths Journey · stone 13 of 13","id":"stone-vedic-sankalana-1","kind":"stone-step","title":"By adding and by subtracting (2 of 3)","body":"Add: 8x + 8y = 40, so x + y = 5. Subtract: 2x − 2y = 2, so x − y = 1. Now x is halfway between: (5 + 1) ÷ 2 = 3, and y = (5 − 1) ÷ 2 = 2.","level":10},"stone-vedic-sankalana-2":{"src":"journey:vedic/sankalana#2","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|sankalana","cta":"Stone 13: By adding and by subtracting","where":"The Vedic Maths Journey · stone 13 of 13","id":"stone-vedic-sankalana-2","kind":"stone-step","title":"By adding and by subtracting (3 of 3)","body":"Why: adding gives (a + b)(x + y); subtracting gives (a − b)(x − y). Two easy divisions give the sum and the difference, and any two numbers are fixed by their sum and difference.","level":10},"stone-try-vedic-sankalana":{"src":"journey:vedic/sankalana#gen0","badge":{"id":"review","label":"Being checked"},"source":"Sources, being checked by a second reader: Bharati Krishna Tirtha, Vedic Mathematics (Motilal Banarsidass, 1965).","route":"#/lib/vedic|sankalana","cta":"Stone 13: By adding and by subtracting","where":"The Vedic Maths Journey · stone 13 of 13","id":"stone-try-vedic-sankalana","kind":"stone-try","title":"By adding and by subtracting — try it","play":{"q":"6x + 9y = 87 and 9x + 6y = 78. What is x?","opts":["4","2","1"],"after":"Two puzzles at once","show":[2,0,1]},"level":10}};
